def normalize_base_path(value) -> str:
    text = str(value or "").strip()
    if not text or text == "/":
        return ""
    if "?" in text or "#" in text or "\\" in text or "://" in text:
        raise ValueError("GEO_AGENT_BASE_PATH 必须是类似 /geo/service 的 URL 路径")
    parts = [part for part in text.strip("/").split("/") if part]
    if not parts or any(part in {".", ".."} for part in parts):
        raise ValueError("GEO_AGENT_BASE_PATH 包含无效路径段")
    return "/" + "/".join(parts)


GEO_AGENT_BASE_PATH = normalize_base_path(os.environ.get("GEO_AGENT_BASE_PATH", ""))


def app_url(path="/") -> str:
    value = str(path or "/")
    if not value.startswith("/"):
        value = "/" + value
    if not GEO_AGENT_BASE_PATH:
        return value
    if value == GEO_AGENT_BASE_PATH or value.startswith(GEO_AGENT_BASE_PATH + "/"):
        return value
    return GEO_AGENT_BASE_PATH + value


def route_path(raw_path) -> str | None:
    value = str(raw_path or "/")
    if not GEO_AGENT_BASE_PATH:
        return value
    if value == GEO_AGENT_BASE_PATH or value == GEO_AGENT_BASE_PATH + "/":
        return "/"
    if value.startswith(GEO_AGENT_BASE_PATH + "/"):
        return value[len(GEO_AGENT_BASE_PATH) :]
    return None


def auth_cookie_path() -> str:
    return GEO_AGENT_BASE_PATH or "/"


def rewrite_html_base_path(content: bytes) -> bytes:
    if not GEO_AGENT_BASE_PATH:
        return content
    text = content.decode("utf-8")
    meta = f'<meta name="geo-agent-base-path" content="{html_lib.escape(GEO_AGENT_BASE_PATH, quote=True)}" />'
    if re.search(r'<meta\s+name=["\']geo-agent-base-path["\'][^>]*>', text, flags=re.I):
        text = re.sub(
            r'<meta\s+name=["\']geo-agent-base-path["\'][^>]*>',
            meta,
            text,
            count=1,
            flags=re.I,
        )
    else:
        text = text.replace("<head>", "<head>\n    " + meta, 1)
    for quote_char in ('"', "'", "`"):
        for root_path in (
            "/api/",
            "/assets/",
            "/v2-assets/",
            "/login",
            "/dashboard.html",
            "/dashboard-v2.html",
            "/dashboard-legacy.html",
            "/portal.html",
        ):
            text = text.replace(
                quote_char + root_path,
                quote_char + app_url(root_path),
            )
    return text.encode("utf-8")


