def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig")


def write_text(path: Path, content: str) -> None:
    path.write_text(content, encoding="utf-8-sig")


def load_questions():
    with QUESTIONS_FILE.open("r", encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def question_lookup():
    return {row["question_id"]: row for row in load_questions()}


def now_iso():
    return datetime.now().replace(microsecond=0).isoformat()


def split_raw_samples(raw_text: str):
    first = re.search(r"(?m)^##\s+Q\d+\s+", raw_text)
    if not first:
        return raw_text.rstrip() + "\n\n", []

    header = raw_text[: first.start()].rstrip() + "\n\n"
    body = raw_text[first.start() :].strip()
    chunks = re.split(r"\n---\s*(?:\n|$)", body)

    sections = []
    for chunk in chunks:
        chunk = chunk.strip()
        if not chunk:
            continue
        match = re.match(r"(?s)^##\s+(Q\d+)\s+(.+?)\s*\n\n(.*)$", chunk)
        if not match:
            continue
        sections.append(
            {
                "question_id": match.group(1).strip(),
                "question": match.group(2).strip(),
                "answer": match.group(3).strip(),
            }
        )
    return header, sections


def save_sample_to_file(
    question_id: str,
    answer: str,
    target_file: Path,
    default_header: str,
):
    questions = question_lookup()
    if question_id not in questions:
        raise ValueError(f"Unknown question_id: {question_id}")
    if not answer.strip():
        raise ValueError("answer cannot be empty")

    raw_text = read_text(target_file) if target_file.exists() else default_header
    header, sections = split_raw_samples(raw_text)
    question = questions[question_id]["question"]
    replacement = {
        "question_id": question_id,
        "question": question,
        "answer": answer.strip(),
    }

    replaced = False
    for index, section in enumerate(sections):
        if section["question_id"] == question_id:
            sections[index] = replacement
            replaced = True
            break

    if not replaced:
        sections.append(replacement)

    blocks = []
    for section in sections:
        blocks.append(
            f"## {section['question_id']} {section['question']}\n\n{section['answer'].strip()}\n\n---"
        )
    write_text(target_file, header + "\n".join(blocks) + "\n")
    return replacement


