def load_run_store():
    if not RUNS_FILE.exists():
        try:
            export_runs_from_db()
        except Exception:
            pass
    if not RUNS_FILE.exists():
        return {"runs": []}
    try:
        store = json.loads(read_text(RUNS_FILE))
    except json.JSONDecodeError:
        try:
            export_runs_from_db()
            store = json.loads(read_text(RUNS_FILE))
        except Exception:
            store = {"runs": []}
    if "runs" not in store or not isinstance(store["runs"], list):
        store = {"runs": []}
    return store


def save_run_store(store):
    write_text(RUNS_FILE, json.dumps(store, ensure_ascii=False, indent=2))


def sampled_question_ids():
    try:
        return db_sampled_question_ids()
    except Exception:
        pass
    if not RAW_FILE.exists():
        return set()
    _, sections = split_raw_samples(read_text(RAW_FILE))
    return {section["question_id"] for section in sections}


def count_sections(path: Path):
    if not path.exists():
        return 0
    _, sections = split_raw_samples(read_text(path))
    return len(sections)


def select_questions(scope="next_unsampled", limit=5, category=""):
    questions = load_questions()
    sampled = sampled_question_ids()
    if category:
        questions = [row for row in questions if row.get("category") == category]

    if scope == "all":
        candidates = questions
    elif scope == "high_priority":
        candidates = [row for row in questions if row.get("priority") == "高"]
    elif scope == "unsampled":
        candidates = [row for row in questions if row["question_id"] not in sampled]
    else:
        high_unsampled = [
            row
            for row in questions
            if row.get("priority") == "高" and row["question_id"] not in sampled
        ]
        other_unsampled = [
            row
            for row in questions
            if row.get("priority") != "高" and row["question_id"] not in sampled
        ]
        candidates = high_unsampled + other_unsampled

    try:
        limit = int(limit)
    except (TypeError, ValueError):
        limit = 5
    limit = max(1, min(limit, 20))
    return candidates[:limit]


def build_task(question):
    task_id = f"task_{uuid.uuid4().hex[:10]}"
    return {
        "task_id": task_id,
        "question_id": question["question_id"],
        "category": question.get("category", ""),
        "priority": question.get("priority", ""),
        "question": question["question"],
        "status": "queued",
        "answer_chars": 0,
        "error": "",
        "created_at": now_iso(),
        "completed_at": "",
    }


def create_sampling_run(payload):
    sampler = str(payload.get("sampler", "mock_doubao")).strip() or "mock_doubao"
    platform = str(payload.get("platform", "豆包")).strip() or "豆包"
    scope = str(payload.get("scope", "next_unsampled")).strip() or "next_unsampled"
    category = str(payload.get("category", "")).strip()
    purpose = normalize_sampling_purpose(payload.get("purpose", "exploration"))
    limit = payload.get("limit", 5)
    selected = select_questions(scope=scope, limit=limit, category=category)
    if not selected:
        raise ValueError("没有可创建任务的问题，请调整范围或继续维护问题库")

    run_id = f"run_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:6]}"
    run = {
        "run_id": run_id,
        "name": str(payload.get("name", "自动采样批次")).strip() or "自动采样批次",
        "platform": platform,
        "sampler": sampler,
        "scope": scope,
        "category": category,
        "purpose": purpose,
        "status": "queued",
        "created_at": now_iso(),
        "started_at": "",
        "completed_at": "",
        "total_tasks": len(selected),
        "success_count": 0,
        "failed_count": 0,
        "tasks": [build_task(question) for question in selected],
    }
    persist_run_db_first(run)
    return run


def create_doubao_assisted_run(question_id: str):
    questions = question_lookup()
