def normalize_question_review_status(value):
    status = str(value or "pending").strip().lower()
    return status if status in QUESTION_REVIEW_STATUSES else "pending"


def question_review_status_meta(value):
    status = normalize_question_review_status(value)
    meta = QUESTION_REVIEW_STATUSES[status]
    return {"status": status, "label": meta["label"], "class": meta["class"]}


