def sampling_category_coverage(tasks):
    standard_rows = [
        {
            "category_id": item["category_id"],
            "name": item["name"],
            "count": 0,
            "covered": False,
        }
        for item in QUESTION_CATEGORY_STANDARDS
    ]
    by_id = {item["category_id"]: item for item in standard_rows}
    raw_counts = {}
    unmapped = {}
    for task in tasks or []:
        if task.get("status") == "skipped":
            continue
        raw_category = str(task.get("category") or "未分类").strip() or "未分类"
        raw_counts[raw_category] = raw_counts.get(raw_category, 0) + 1
        standard_id = standard_category_id_for(raw_category)
        if standard_id in by_id:
            by_id[standard_id]["count"] += 1
            by_id[standard_id]["covered"] = True
        else:
            unmapped[raw_category] = unmapped.get(raw_category, 0) + 1
    covered = [item for item in standard_rows if item["covered"]]
    missing = [item for item in standard_rows if not item["covered"]]
    top_raw = [
        {"name": name, "count": count}
        for name, count in sorted(raw_counts.items(), key=lambda item: (-item[1], item[0]))
    ]
    summary_parts = [f"{item['name']} {item['count']}" for item in covered[:4]]
    if len(covered) > 4:
        summary_parts.append(f"另 {len(covered) - 4} 类")
    summary_text = (
        f"覆盖 {len(covered)}/{len(standard_rows)} 类"
        + (f"：{'、'.join(summary_parts)}" if summary_parts else "")
    )
    return {
        "covered_standard_count": len(covered),
        "total_standard_count": len(standard_rows),
        "standard_categories": standard_rows,
        "raw_categories": top_raw,
        "missing_standard_categories": [
            {"category_id": item["category_id"], "name": item["name"]}
            for item in missing
        ],
        "unmapped_categories": [
            {"name": name, "count": count}
            for name, count in sorted(unmapped.items(), key=lambda item: (-item[1], item[0]))
        ],
        "summary_text": summary_text,
    }


