def report_version_to_dict(row):
    item = db_row_to_dict(row)
    if not item:
        return None
    item["applied_polish"] = bool(item.get("applied_polish"))
    item["markdown_chars"] = int(item.get("markdown_chars") or 0)
    item["version_no"] = int(item.get("version_no") or 0)
    item["pdf_available"] = bool(item.get("pdf_storage_path") and item.get("pdf_sha256"))
    item.pop("pdf_storage_path", None)
    item["schema_version"] = int(item.get("schema_version") or 1)
    return item


def db_project_report_versions_payload(project_id, query=None):
    project_id = unquote(str(project_id or "").strip())
    query = query or {}
    report_type = normalize_report_type((query.get("report_type") or [""])[0])
    status = str((query.get("status") or [""])[0] or "").strip().lower()
    allowed_statuses = {"draft", "published", "superseded", "saved"}
    if status and status not in allowed_statuses:
        raise ValueError("Unknown report status filter")
    limit = parse_bounded_int((query.get("limit") or [10])[0], default=10, minimum=1, maximum=50)
    with db_connect() as conn:
        ensure_report_versions_table(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        where = "project_id = ? AND report_type = ?"
        params = [project_id, report_type]
        if status:
            where += " AND status = ?"
            params.append(status)
        params.append(limit)
        rows = conn.execute(
            f"""
            SELECT *
            FROM report_versions
            WHERE {where}
            ORDER BY version_no DESC, created_at DESC
            LIMIT ?
            """,
            params,
        ).fetchall()
    return {
        "ok": True,
        "project": project,
        "report_type": report_type,
        "status": status,
        "versions": [report_version_to_dict(row) for row in rows],
        "source": "sqlite",
    }


def db_save_project_report_version_payload(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    report_type = normalize_report_type(payload.get("report_type"))
    markdown_text = str(
        payload.get("markdown_text")
        or payload.get("report_markdown")
        or ""
    ).strip()
    if not markdown_text:
        raise ValueError("当前报告内容为空，无法保存版本")

    title = str(payload.get("title") or "").strip()[:200]
    executive_summary = str(payload.get("executive_summary") or "").strip()[:1000]
    status = str(payload.get("status") or "draft").strip().lower()[:40] or "draft"
    if status not in {"draft", "published", "superseded", "saved"}:
        raise ValueError("报告版本状态无效")
    source = str(payload.get("source") or "dashboard").strip()[:80] or "dashboard"
    timestamp = now_iso()
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_report_versions_table(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        row = conn.execute(
            """
            SELECT COALESCE(MAX(version_no), 0) AS max_version
            FROM report_versions
            WHERE project_id = ? AND report_type = ?
            """,
            (project_id, report_type),
        ).fetchone()
        version_no = int(row["max_version"] or 0) + 1
        version_id = make_id("report")
        conn.execute(
            """
            INSERT INTO report_versions (
              report_version_id, project_id, report_type, version_no, title,
              executive_summary, markdown_text, markdown_chars, applied_polish,
              polish_json, llm_meta_json, metrics_json, source, status,
              created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                version_id,
                project_id,
                report_type,
                version_no,
                title,
                executive_summary,
                markdown_text,
                len(markdown_text),
                bool_int(payload.get("applied_polish")),
                json_dump(payload.get("polish") or {}),
                json_dump(payload.get("llm") or {}),
                json_dump(payload.get("metrics") or {}),
                source,
                status,
                timestamp,
                timestamp,
            ),
        )
        conn.commit()
        saved = conn.execute(
            "SELECT * FROM report_versions WHERE report_version_id = ?",
            (version_id,),
        ).fetchone()
    return {
        "ok": True,
        "project": project,
        "version": report_version_to_dict(saved),
        "source": "sqlite",
    }


def db_publish_project_report_version_payload(project_id, report_version_id):
    project_id = unquote(str(project_id or "").strip())
    report_version_id = unquote(str(report_version_id or "").strip())
    timestamp = now_iso()
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_report_versions_table(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        row = conn.execute(
            """
            SELECT * FROM report_versions
            WHERE project_id = ? AND report_version_id = ?
            """,
            (project_id, report_version_id),
        ).fetchone()
        if not row:
            raise ValueError("Unknown report_version_id")
        if row["report_type"] != "client":
            raise ValueError("仅客户诊断报告可以发布到客户模式")
        conn.execute(
            """
            UPDATE report_versions
            SET status = 'superseded', updated_at = ?
            WHERE project_id = ?
              AND report_type = 'client'
              AND status = 'published'
              AND report_version_id <> ?
            """,
            (timestamp, project_id, report_version_id),
        )
        conn.execute(
            """
            UPDATE report_versions
            SET status = 'published', updated_at = ?
            WHERE project_id = ? AND report_version_id = ?
            """,
            (timestamp, project_id, report_version_id),
        )
        conn.commit()
        published = conn.execute(
            "SELECT * FROM report_versions WHERE report_version_id = ?",
            (report_version_id,),
        ).fetchone()
    return {
        "ok": True,
        "project": project,
        "version": report_version_to_dict(published),
        "source": "sqlite",
    }


def normalize_formal_report_type(value):
    report_type = str(value or "client").strip().lower()
    if report_type not in REPORT_FORMAL_TYPES:
        raise ValueError("正式报告类型必须为首次诊断或周期跟踪。")
    return report_type


def report_draft_to_dict(row):
    item = db_row_to_dict(row)
    if not item:
        return None
    item["revision"] = int(item.get("revision") or 0)
    item["current_step"] = int(item.get("current_step") or 1)
    return item


def validate_report_json(report):
    if not isinstance(report, dict):
        raise ValueError("报告结构必须是 JSON 对象。")
    sections = report.get("sections")
    if not isinstance(sections, list) or not sections:
        raise ValueError("报告缺少章节内容。")
    seen = set()
    for section in sections:
        if not isinstance(section, dict):
            raise ValueError("报告章节格式无效。")
        section_id = str(section.get("id") or "").strip()
        if section_id not in REPORT_SECTION_LABELS or section_id in seen:
            raise ValueError(f"报告章节标识无效：{section_id or '空值'}")
        seen.add(section_id)
        if not str(section.get("markdown") or "").strip():
            raise ValueError(f"报告章节内容为空：{REPORT_SECTION_LABELS[section_id]}")
    missing = set(REPORT_SECTION_LABELS) - seen
    if missing:
        raise ValueError("报告缺少必要章节：" + "、".join(REPORT_SECTION_LABELS[item] for item in REPORT_SECTION_LABELS if item in missing))
    return report


def report_markdown_from_json(report):
    report = validate_report_json(report)
    title = str(report.get("title") or "GEO 可见度诊断报告").strip()
    sections = {
        str(section.get("id") or ""): str(section.get("markdown") or "").strip()
        for section in report["sections"]
    }
    if str(report.get("reportType") or "").strip().lower() == "internal":
        return "\n\n".join([f"# {title}"] + [sections[item] for item in REPORT_SECTION_LABELS])

    def body(section_id):
        return re.sub(r"^##\s+\d+\.\s+[^\n]+\n*", "", sections.get(section_id, ""), count=1).strip()

    return "\n\n".join([
        f"# {title}",
        f"## 1. 本期结论与核心指标\n\n{body('conclusion')}\n\n### 核心可见度指标\n\n{body('metrics')}",
        f"## 2. 四场景可见度诊断\n\n{body('scenes')}",
        f"## 3. 关键问题与回答证据\n\n{body('evidence')}",
        f"## 4. 不可见或被压制的原因\n\n{body('causes')}",
        f"## 5. 内容资产行动方案\n\n{body('actions')}",
        f"## 6. 复测与验收标准\n\n{body('retest')}",
        f"## 附录：全量异常证据与方法说明\n\n{body('appendix')}",
    ])


def report_selected_evidence_ids(report):
    rows = report.get("evidence") if isinstance(report, dict) else []
    return [str(item.get("id") or "").strip() for item in rows or [] if isinstance(item, dict) and str(item.get("id") or "").strip()]


def normalize_report_evidence_for_lock(value, inside_verified_sources=False):
    """Ignore only the editor-controlled source selection flag during fact locking."""
    if isinstance(value, list):
        return [normalize_report_evidence_for_lock(item, inside_verified_sources) for item in value]
    if not isinstance(value, dict):
        return value
    normalized = {}
    for key, item in value.items():
        if inside_verified_sources and key == "selected":
            continue
        normalized[key] = normalize_report_evidence_for_lock(
            item,
            inside_verified_sources or key == "verifiedSources",
        )
    return normalized


def report_selected_source_evidence(report):
    selected = []
    seen = set()
    evidence_groups = []
    if isinstance(report, dict):
        evidence_groups.extend(report.get("evidence") or [])
        evidence_groups.extend(report.get("allAnomalies") or [])
    for evidence in evidence_groups:
        if not isinstance(evidence, dict):
            continue
        for source in evidence.get("verifiedSources") or []:
            if not isinstance(source, dict) or source.get("selected") is False:
                continue
            source_id = str(source.get("id") or source.get("source_evidence_id") or "").strip()
            if not source_id or source_id in seen:
                continue
            seen.add(source_id)
            selected.append({
                **source,
                "id": source_id,
                "questionId": str(evidence.get("questionId") or evidence.get("question_id") or ""),
                "sampleEvidenceId": str(evidence.get("id") or ""),
            })
    return selected


def validate_report_sources_for_publish(conn, project_id, report):
    selected = report_selected_source_evidence(report)
    if not selected:
        return []
    source_ids = [item["id"] for item in selected]
    placeholders = ",".join("?" for _ in source_ids)
    rows = conn.execute(
        f"SELECT * FROM source_evidence WHERE project_id = ? AND source_evidence_id IN ({placeholders})",
        [project_id, *source_ids],
    ).fetchall()
    found = {row["source_evidence_id"]: db_row_to_dict(row) for row in rows}
    missing = [source_id for source_id in source_ids if source_id not in found]
    if missing:
        raise ValueError("报告选用的信源记录已不存在，请返回证据审核区重新选择。")
    invalid = []
    for source_id in source_ids:
        item = found[source_id]
        if item.get("verification_status") != "confirmed":
            invalid.append(f"{item.get('title') or source_id}（状态已变化）")
        elif item.get("fetch_status") not in {"accessible", "local"}:
            invalid.append(f"{item.get('title') or source_id}（来源失效）")
        elif item.get("relation") == "contradicts":
            invalid.append(f"{item.get('title') or source_id}（与正文矛盾）")
    if invalid:
        raise ValueError("以下已选信源不能用于发布：" + "；".join(invalid[:6]))
    return [found[source_id] for source_id in source_ids]


def report_source_run_exists(conn, project_id, run_id):
    if not run_id:
        return True
    return bool(conn.execute(
        "SELECT 1 FROM sample_runs WHERE project_id = ? AND run_id = ?",
        (project_id, run_id),
    ).fetchone())


def report_publish_warnings(report, section_status):
    warnings = []
    metrics = report.get("metrics") or {}
    if int(metrics.get("total_samples") or 0) <= 0:
        warnings.append({"code": "no_samples", "message": "当前报告没有真实样本，发布后只能作为待采样说明。"})
    evidence = report.get("evidence") or []
    if not evidence:
        warnings.append({"code": "no_evidence", "message": "报告尚未选择代表证据。"})
    if not report_selected_source_evidence(report):
        warnings.append({"code": "no_confirmed_sources", "message": "报告正文尚未选用人工确认的公开信源或客户资料依据。"})
    by_scene = {}
    for item in evidence:
        if isinstance(item, dict):
            scene_id = str(item.get("sceneId") or item.get("scene_id") or "")
            by_scene[scene_id] = by_scene.get(scene_id, 0) + 1
    for scene in report.get("scenes") or []:
        scene_id = str(scene.get("id") or "") if isinstance(scene, dict) else ""
        if scene_id and not by_scene.get(scene_id):
            warnings.append({"code": f"scene_evidence_{scene_id}", "message": f"{scene.get('label') or scene_id}尚未选择代表证据。"})
    section_status = section_status if isinstance(section_status, dict) else {}
    pending = [REPORT_SECTION_LABELS[item] for item in REPORT_EDITABLE_SECTION_IDS if section_status.get(item) not in {"reviewed", "ai_applied"}]
    if pending:
        warnings.append({"code": "sections_pending", "message": "以下叙事章节尚未完成审核：" + "、".join(pending)})
    if not report.get("actions"):
        warnings.append({"code": "no_actions", "message": "当前没有结构化内容资产行动项。"})
    return warnings


def db_project_report_drafts_payload(project_id, draft_id="", query=None):
    project_id = unquote(str(project_id or "").strip())
    draft_id = unquote(str(draft_id or "").strip())
    query = query or {}
    report_type = str((query.get("report_type") or [""])[0] or "").strip()
    status = str((query.get("status") or [""])[0] or "").strip()
    with db_connect() as conn:
        ensure_report_center_tables(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        if draft_id:
            row = conn.execute(
                "SELECT * FROM report_drafts WHERE project_id = ? AND draft_id = ?",
                (project_id, draft_id),
            ).fetchone()
            return {"ok": True, "project": project, "draft": report_draft_to_dict(row), "source": "sqlite"} if row else None
        where = ["project_id = ?"]
        params = [project_id]
        if report_type:
            where.append("report_type = ?")
            params.append(normalize_formal_report_type(report_type))
        if status:
            where.append("status = ?")
            params.append(status)
        rows = conn.execute(
            f"SELECT * FROM report_drafts WHERE {' AND '.join(where)} ORDER BY updated_at DESC",
            params,
        ).fetchall()
    return {"ok": True, "project": project, "drafts": [report_draft_to_dict(row) for row in rows], "source": "sqlite"}


def db_create_project_report_draft(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    report_type = normalize_formal_report_type(payload.get("report_type"))
    report = validate_report_json(payload.get("report") or payload.get("report_json") or {})
    source_snapshot = payload.get("source_snapshot") or report.get("sourceSnapshot") or {}
    source_run_id = str(payload.get("source_run_id") or source_snapshot.get("run_id") or "").strip()
    comparison_run_id = str(payload.get("comparison_run_id") or source_snapshot.get("comparison_run_id") or "").strip()
    timestamp = now_iso()
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_report_center_tables(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        if not report_source_run_exists(conn, project_id, source_run_id):
            raise ValueError("所选来源批次不存在或不属于当前项目。")
        if comparison_run_id and not report_source_run_exists(conn, project_id, comparison_run_id):
            raise ValueError("所选对比批次不存在或不属于当前项目。")
        draft_id = make_id("draft")
        section_status = payload.get("section_status") or {
            section_id: ("pending" if section_id in REPORT_EDITABLE_SECTION_IDS else "locked")
            for section_id in REPORT_SECTION_LABELS
        }
        conn.execute(
            """
            INSERT INTO report_drafts (
              draft_id, project_id, report_type, title, current_step,
              source_run_id, comparison_run_id, source_snapshot_json,
              report_json, evidence_ids_json, section_status_json, llm_meta_json,
              revision, status, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 'editing', ?, ?)
            """,
            (
                draft_id, project_id, report_type, str(report.get("title") or "")[:200],
                max(1, min(4, int(payload.get("current_step") or 2))), source_run_id,
                comparison_run_id, json_dump(source_snapshot), json_dump(report),
                json_dump(report_selected_evidence_ids(report)), json_dump(section_status),
                json_dump(payload.get("llm") or {}), timestamp, timestamp,
            ),
        )
        row = conn.execute("SELECT * FROM report_drafts WHERE draft_id = ?", (draft_id,)).fetchone()
    return {"ok": True, "project": project, "draft": report_draft_to_dict(row), "source": "sqlite"}


def db_update_project_report_draft(project_id, draft_id, payload):
    project_id = unquote(str(project_id or "").strip())
    draft_id = unquote(str(draft_id or "").strip())
    payload = payload or {}
    requested_revision = int(payload.get("revision") or 0)
    report = validate_report_json(payload.get("report") or payload.get("report_json") or {})
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_report_center_tables(conn)
        row = conn.execute(
            "SELECT * FROM report_drafts WHERE project_id = ? AND draft_id = ?",
            (project_id, draft_id),
        ).fetchone()
        if not row:
            return None
        current = report_draft_to_dict(row)
        if requested_revision != current["revision"]:
            raise ReportRevisionConflict(current)
        if current.get("status") == "published":
            raise ValueError("已发布草稿不可继续修改，请复制为新草稿。")
        original = current.get("report") or {}
        for key in ("metrics", "scenes", "sourceSnapshot", "originalSections"):
            if key in original and json_dump(report.get(key)) != json_dump(original.get(key)):
                raise ValueError(f"报告锁定事实不可修改：{key}")
        for key in ("allAnomalies", "allEvidence"):
            if key in original and json_dump(normalize_report_evidence_for_lock(report.get(key))) != json_dump(normalize_report_evidence_for_lock(original.get(key))):
                raise ValueError(f"报告锁定事实不可修改：{key}")
        allowed_evidence_ids = {
            str(item.get("id") or "")
            for item in (original.get("allEvidence") or original.get("allAnomalies") or original.get("evidence") or [])
            if isinstance(item, dict)
        }
        selected_ids = report_selected_evidence_ids(report)
        if any(item not in allowed_evidence_ids for item in selected_ids):
            raise ValueError("代表证据必须来自当前报告锁定的真实样本。")
        next_revision = requested_revision + 1
        timestamp = now_iso()
        section_status = payload.get("section_status") or current.get("section_status") or {}
        conn.execute(
            """
            UPDATE report_drafts
            SET title = ?, current_step = ?, report_json = ?, evidence_ids_json = ?,
                section_status_json = ?, llm_meta_json = ?, revision = ?,
                status = ?, updated_at = ?
            WHERE project_id = ? AND draft_id = ?
            """,
            (
                str(report.get("title") or current.get("title") or "")[:200],
                max(1, min(4, int(payload.get("current_step") or current.get("current_step") or 1))),
                json_dump(report), json_dump(selected_ids), json_dump(section_status),
                json_dump(payload.get("llm") or current.get("llm_meta") or {}), next_revision,
                str(payload.get("status") or current.get("status") or "editing"), timestamp,
                project_id, draft_id,
            ),
        )
        saved = conn.execute("SELECT * FROM report_drafts WHERE draft_id = ?", (draft_id,)).fetchone()
    return {"ok": True, "draft": report_draft_to_dict(saved), "source": "sqlite"}


def insert_report_version_from_draft(conn, draft, project, status="draft", publish_warnings=None, pdf_meta=None):
    report_type = normalize_formal_report_type(draft.get("report_type"))
    report = validate_report_json(draft.get("report") or {})
    markdown_text = report_markdown_from_json(report)
    timestamp = now_iso()
    row = conn.execute(
        "SELECT COALESCE(MAX(version_no), 0) AS max_version FROM report_versions WHERE project_id = ? AND report_type = ?",
        (project["project_id"], report_type),
    ).fetchone()
    version_no = int(row["max_version"] or 0) + 1
    version_id = str((pdf_meta or {}).get("version_id") or make_id("report"))
    frozen_source_snapshot = dict(draft.get("source_snapshot") or report.get("sourceSnapshot") or {})
    selected_sources = report_selected_source_evidence(report)
    frozen_source_snapshot["source_evidence_ids"] = [item["id"] for item in selected_sources]
    frozen_source_snapshot["verified_sources"] = selected_sources
    conn.execute(
        """
        INSERT INTO report_versions (
          report_version_id, project_id, report_type, version_no, title,
          executive_summary, markdown_text, markdown_chars, applied_polish,
          polish_json, llm_meta_json, metrics_json, source, status,
          created_at, updated_at, report_json, source_snapshot_json,
          publish_warnings_json, pdf_storage_path, pdf_sha256, pdf_bytes,
          published_at, draft_id, schema_version
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            version_id, project["project_id"], report_type, version_no,
            str(report.get("title") or draft.get("title") or "")[:200],
            str(report.get("executiveSummary") or "")[:1000], markdown_text, len(markdown_text),
            bool_int(bool(draft.get("llm_meta"))), json_dump({"report_bundle": report, "section_statuses": draft.get("section_status") or {}}),
            json_dump(draft.get("llm_meta") or {}), json_dump(report.get("metrics") or {}),
            "report-center-v2", status, timestamp, timestamp, json_dump(report),
            json_dump(frozen_source_snapshot),
            json_dump(publish_warnings or []), str((pdf_meta or {}).get("path") or ""),
            str((pdf_meta or {}).get("sha256") or ""), int((pdf_meta or {}).get("bytes") or 0),
            timestamp if status == "published" else "", draft.get("draft_id") or "", REPORT_SCHEMA_VERSION,
        ),
    )
    return conn.execute("SELECT * FROM report_versions WHERE report_version_id = ?", (version_id,)).fetchone()


def db_checkpoint_project_report_draft(project_id, draft_id, payload=None):
    project_id = unquote(str(project_id or "").strip())
    draft_id = unquote(str(draft_id or "").strip())
    payload = payload or {}
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_report_center_tables(conn)
        project = db_project_detail(conn, project_id)
        row = conn.execute("SELECT * FROM report_drafts WHERE project_id = ? AND draft_id = ?", (project_id, draft_id)).fetchone()
        if not project or not row:
            return None
        draft = report_draft_to_dict(row)
        if payload.get("revision") is not None and int(payload.get("revision")) != draft["revision"]:
            raise ReportRevisionConflict(draft)
        version = insert_report_version_from_draft(conn, draft, project, status="draft")
    return {"ok": True, "draft": draft, "version": report_version_to_dict(version), "source": "sqlite"}


def db_copy_report_version_to_draft(project_id, version_id):
    project_id = unquote(str(project_id or "").strip())
    version_id = unquote(str(version_id or "").strip())
    with db_connect() as conn:
        ensure_report_center_tables(conn)
        row = conn.execute("SELECT * FROM report_versions WHERE project_id = ? AND report_version_id = ?", (project_id, version_id)).fetchone()
        if not row:
            return None
        version = db_row_to_dict(row)
    report = version.get("report") or (version.get("polish") or {}).get("report_bundle") or {}
    if not report:
        raise ValueError("该历史版本缺少结构化内容，不能直接复制为工作草稿。")
    return db_create_project_report_draft(project_id, {
        "report_type": version.get("report_type"),
        "report": report,
        "source_snapshot": version.get("source_snapshot") or report.get("sourceSnapshot") or {},
        "source_run_id": (version.get("source_snapshot") or {}).get("run_id") or "",
        "current_step": 3,
        "section_status": (version.get("polish") or {}).get("section_statuses") or {},
        "llm": version.get("llm_meta") or {},
    })


def db_publish_project_report_draft(project_id, draft_id, payload=None):
    project_id = unquote(str(project_id or "").strip())
    draft_id = unquote(str(draft_id or "").strip())
    payload = payload or {}
    with db_connect() as conn:
        ensure_report_center_tables(conn)
        project = db_project_detail(conn, project_id)
        row = conn.execute("SELECT * FROM report_drafts WHERE project_id = ? AND draft_id = ?", (project_id, draft_id)).fetchone()
        if not project or not row:
            return None
        draft = report_draft_to_dict(row)
        if int(payload.get("revision") or 0) != draft["revision"]:
            raise ReportRevisionConflict(draft)
        if not report_source_run_exists(conn, project_id, draft.get("source_run_id") or ""):
            raise ValueError("报告来源批次已不存在，不能发布。")
        validate_report_sources_for_publish(conn, project_id, draft.get("report") or {})
        warnings = report_publish_warnings(draft.get("report") or {}, draft.get("section_status") or {})
        if warnings and not payload.get("acknowledge_warnings"):
            raise ReportPublishWarning(warnings)
        report = draft.get("report") or {}
        markdown_text = report_markdown_from_json(report)
        publish_revision = draft["revision"]

    pdf_payload = {
        "report_type": draft.get("report_type"),
        "title": report.get("title") or draft.get("title"),
        "executive_summary": report.get("executiveSummary") or "",
        "markdown_text": markdown_text,
        "metrics": report.get("metrics") or {},
    }
    pdf_bytes, engine = generate_report_pdf_bytes(pdf_payload, project)
    if not pdf_bytes.startswith(b"%PDF"):
        raise ValueError("PDF 生成失败，未输出有效文件。")
    version_id = make_id("report")
    customer_id = safe_db_token(project.get("customer_id"), "customer")
    project_token = safe_db_token(project_id, "project")
    export_dir = REPORT_EXPORT_ROOT / customer_id / project_token
    export_dir.mkdir(parents=True, exist_ok=True)
    final_path = export_dir / f"{version_id}.pdf"
    temp_path = export_dir / f".{version_id}.tmp"
    temp_path.write_bytes(pdf_bytes)
    pdf_hash = hashlib.sha256(pdf_bytes).hexdigest()
    os.replace(temp_path, final_path)
    try:
        with db_connect() as conn:
            conn.execute("PRAGMA foreign_keys = ON")
            ensure_report_center_tables(conn)
            latest_row = conn.execute("SELECT * FROM report_drafts WHERE project_id = ? AND draft_id = ?", (project_id, draft_id)).fetchone()
            latest = report_draft_to_dict(latest_row)
            if not latest or latest["revision"] != publish_revision:
                raise ReportRevisionConflict(latest or {})
            if draft.get("report_type") == "client":
                conn.execute(
                    "UPDATE report_versions SET status = 'superseded', updated_at = ? WHERE project_id = ? AND report_type = 'client' AND status = 'published'",
                    (now_iso(), project_id),
                )
            version = insert_report_version_from_draft(conn, latest, project, status="published", publish_warnings=warnings, pdf_meta={
                "version_id": version_id,
                "path": str(final_path.relative_to(ROOT)),
                "sha256": pdf_hash,
                "bytes": len(pdf_bytes),
            })
            conn.execute(
                "UPDATE report_drafts SET status = 'published', current_step = 4, revision = revision + 1, updated_at = ? WHERE draft_id = ?",
                (now_iso(), draft_id),
            )
            saved_draft = conn.execute("SELECT * FROM report_drafts WHERE draft_id = ?", (draft_id,)).fetchone()
    except Exception:
        final_path.unlink(missing_ok=True)
        raise
    return {
        "ok": True,
        "draft": report_draft_to_dict(saved_draft),
        "version": report_version_to_dict(version),
        "pdf": {"available": True, "sha256": pdf_hash, "bytes": len(pdf_bytes), "engine": engine},
        "warnings": warnings,
        "source": "sqlite",
    }


def db_report_version_pdf_payload(project_id, version_id, customer_id=""):
    project_id = unquote(str(project_id or "").strip())
    version_id = unquote(str(version_id or "").strip())
    with db_connect() as conn:
        ensure_report_center_tables(conn)
        project = db_project_detail(conn, project_id)
        row = conn.execute(
            "SELECT * FROM report_versions WHERE project_id = ? AND report_version_id = ?",
            (project_id, version_id),
        ).fetchone()
    if not project or not row:
        return None
    if customer_id and str(project.get("customer_id") or "") != str(customer_id):
        return None
    item = db_row_to_dict(row)
    if customer_id and item.get("status") not in {"published", "superseded"}:
        return None
    relative_path = str(item.get("pdf_storage_path") or "").strip()
    if not relative_path:
        return None
    path = (ROOT / relative_path).resolve()
    try:
        path.relative_to(REPORT_EXPORT_ROOT.resolve())
    except ValueError:
        return None
    if not path.exists() or not path.is_file():
        return None
    expected_hash = str(item.get("pdf_sha256") or "")
    actual_hash = hashlib.sha256(path.read_bytes()).hexdigest()
    if expected_hash and not hmac.compare_digest(expected_hash, actual_hash):
        raise ValueError("正式报告 PDF 校验失败，请联系内部人员重新发布。")
    filename = f"{safe_filename_segment(item.get('title') or 'GEO诊断报告')}-V{int(item.get('version_no') or 0)}.pdf"
    return {"path": path, "filename": filename, "content_type": "application/pdf", "sha256": actual_hash}


