def db_save_customer_portal_account(customer_id, payload):
    customer_id = unquote(str(customer_id or "").strip())
    payload = payload or {}
    username = str(payload.get("username") or "").strip()
    password = str(payload.get("password") or "")
    status = str(payload.get("status") or "active").strip().lower()
    if not re.fullmatch(r"[A-Za-z0-9_.@-]{4,80}", username):
        raise ValueError("客户账号需为 4-80 位字母、数字或 . _ @ -。")
    if password and len(password) < 10:
        raise ValueError("客户账号密码至少需要 10 个字符。")
    if status not in {"active", "disabled"}:
        raise ValueError("客户账号状态无效。")
    timestamp = now_iso()
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_report_center_tables(conn)
        customer = conn.execute("SELECT * FROM customers WHERE customer_id = ?", (customer_id,)).fetchone()
        if not customer:
            return None
        existing = conn.execute("SELECT * FROM customer_portal_accounts WHERE customer_id = ?", (customer_id,)).fetchone()
        duplicate = conn.execute("SELECT customer_id FROM customer_portal_accounts WHERE username = ? AND customer_id <> ?", (username, customer_id)).fetchone()
        if duplicate:
            raise ValueError("该客户账号名称已被使用。")
        if existing:
            if password:
                conn.execute(
                    "UPDATE customer_portal_accounts SET username = ?, password_hash = ?, status = ?, updated_at = ? WHERE customer_id = ?",
                    (username, password_hash(password), status, timestamp, customer_id),
                )
            else:
                conn.execute(
                    "UPDATE customer_portal_accounts SET username = ?, status = ?, updated_at = ? WHERE customer_id = ?",
                    (username, status, timestamp, customer_id),
                )
        else:
            if not password:
                raise ValueError("创建客户账号时必须填写密码。")
            conn.execute(
                "INSERT INTO customer_portal_accounts (account_id, customer_id, username, password_hash, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                (make_id("portal"), customer_id, username, password_hash(password), status, timestamp, timestamp),
            )
        account = conn.execute("SELECT * FROM customer_portal_accounts WHERE customer_id = ?", (customer_id,)).fetchone()
    return {"ok": True, "account": customer_portal_account_to_dict(account), "source": "sqlite"}


