def portal_report_summary(row):
    item = report_version_to_dict(row)
    if not item:
        return None
    for key in ("markdown_text", "polish", "llm_meta", "metrics", "report", "source_snapshot", "publish_warnings"):
        item.pop(key, None)
    return item


def db_portal_workspace_payload(customer_id):
    customer_id = str(customer_id or "").strip()
    with db_connect() as conn:
        ensure_report_center_tables(conn)
        customer = conn.execute("SELECT * FROM customers WHERE customer_id = ? AND status = 'active'", (customer_id,)).fetchone()
        if not customer:
            return None
        brand = conn.execute("SELECT * FROM customer_brand_assets WHERE customer_id = ?", (customer_id,)).fetchone()
        projects = conn.execute(
            "SELECT * FROM projects WHERE customer_id = ? AND status = 'active' ORDER BY created_at",
            (customer_id,),
        ).fetchall()
        versions = conn.execute(
            """
            SELECT rv.*, p.name AS project_name
            FROM report_versions rv
            JOIN projects p ON p.project_id = rv.project_id
            WHERE p.customer_id = ?
              AND rv.report_type IN ('client', 'weekly')
              AND rv.status IN ('published', 'superseded')
            ORDER BY COALESCE(NULLIF(rv.published_at, ''), rv.updated_at) DESC, rv.version_no DESC
            """,
            (customer_id,),
        ).fetchall()
    summaries = [portal_report_summary(row) for row in versions]
    latest = {}
    for item in summaries:
        key = f"{item.get('project_id')}:{item.get('report_type')}"
        if key not in latest and item.get("status") == "published":
            latest[key] = item
    return {
        "ok": True,
        "customer": db_row_to_dict(customer),
        "brand": customer_brand_to_dict(brand) or {"customer_id": customer_id, "display_name": customer["name"], "logo_available": False},
        "projects": db_rows_to_list(projects),
        "reports": summaries,
        "latest": list(latest.values()),
        "source": "sqlite",
    }


