def create_fact_base_version(conn, customer_id, source="dashboard", note=""):
    ensure_evidence_versioning_tables(conn)
    facts = db_rows_to_list(
        conn.execute(
            """
            SELECT fact_id, fact_type, fact_key, fact_value, visibility, confidence, evidence_url
            FROM customer_facts
            WHERE customer_id = ? AND fact_type <> 'question_profile'
            ORDER BY fact_type, fact_id
            """,
            (customer_id,),
        ).fetchall()
    )
    competitors = db_rows_to_list(
        conn.execute(
            """
            SELECT *
            FROM competitors
            WHERE customer_id = ?
            ORDER BY competitor_id
            """,
            (customer_id,),
        ).fetchall()
    )
    forbidden_claims = db_rows_to_list(
        conn.execute(
            """
            SELECT *
            FROM forbidden_claims
            WHERE customer_id = ?
            ORDER BY claim_id
            """,
            (customer_id,),
        ).fetchall()
    )
    row = conn.execute(
        """
        SELECT COALESCE(MAX(version_no), 0) AS max_version
        FROM fact_base_versions
        WHERE customer_id = ?
        """,
        (customer_id,),
    ).fetchone()
    version_no = int(row["max_version"] or 0) + 1
    version_id = make_id("factver")
    timestamp = now_iso()
    conn.execute(
        """
        INSERT INTO fact_base_versions (
          fact_base_version_id, customer_id, version_no, fact_count,
          competitor_count, forbidden_claim_count, facts_json,
          competitors_json, forbidden_claims_json, change_source, note, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            version_id,
            customer_id,
            version_no,
            len(facts),
            len(competitors),
            len(forbidden_claims),
            json_dump(facts),
            json_dump(competitors),
            json_dump(forbidden_claims),
            str(source or "dashboard")[:80],
            str(note or "")[:500],
            timestamp,
        ),
    )
    return fact_base_version_to_dict(
        conn.execute(
            "SELECT * FROM fact_base_versions WHERE fact_base_version_id = ?",
            (version_id,),
        ).fetchone()
    )


def db_fact_base_versions_payload(customer_id, query=None):
    customer_id = unquote(str(customer_id or "").strip())
    query = query or {}
    limit = parse_bounded_int((query.get("limit") or [5])[0], default=5, minimum=1, maximum=50)
    with db_connect() as conn:
        ensure_evidence_versioning_tables(conn)
        customer = db_row_to_dict(
            conn.execute("SELECT * FROM customers WHERE customer_id = ?", (customer_id,)).fetchone()
        )
        if not customer:
            return None
        rows = conn.execute(
            """
            SELECT *
            FROM fact_base_versions
            WHERE customer_id = ?
            ORDER BY version_no DESC
            LIMIT ?
            """,
            (customer_id, limit),
        ).fetchall()
    return {
        "ok": True,
        "customer": customer,
        "versions": [fact_base_version_to_dict(row) for row in rows],
        "source": "sqlite",
    }


def ensure_analysis_result_versions_table(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS analysis_result_versions (
          analysis_version_id TEXT PRIMARY KEY,
          project_id TEXT NOT NULL,
          version_no INTEGER NOT NULL DEFAULT 1,
          status TEXT NOT NULL DEFAULT 'confirmed',
          source TEXT NOT NULL DEFAULT 'llm_confirm',
          analyzer_version TEXT NOT NULL DEFAULT '',
          analysis_count INTEGER NOT NULL DEFAULT 0,
          recommendation_count INTEGER NOT NULL DEFAULT 0,
          action_task_count INTEGER NOT NULL DEFAULT 0,
          question_ids_json TEXT NOT NULL DEFAULT '[]',
          input_package_json TEXT NOT NULL DEFAULT '{}',
          result_json TEXT NOT NULL DEFAULT '{}',
          validation_json TEXT NOT NULL DEFAULT '{}',
          review_decisions_json TEXT NOT NULL DEFAULT '[]',
          llm_meta_json TEXT NOT NULL DEFAULT '{}',
          note TEXT NOT NULL DEFAULT '',
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          FOREIGN KEY (project_id) REFERENCES projects(project_id)
        )
        """
    )
    conn.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_analysis_versions_project
        ON analysis_result_versions(project_id, version_no)
        """
    )


def analysis_result_version_to_dict(row):
    item = db_row_to_dict(row)
    if not item:
        return None
    for key in ("version_no", "analysis_count", "recommendation_count", "action_task_count"):
        item[key] = int(item.get(key) or 0)
    return item


def create_analysis_result_version(
    conn,
    project_id,
    brief,
    result_obj,
    validation,
    review_decisions,
    llm_meta,
    saved_analysis_count,
    saved_recommendation_count,
    saved_action_task_count,
    note="",
    source="llm_confirm",
):
    ensure_analysis_result_versions_table(conn)
    row = conn.execute(
        """
        SELECT COALESCE(MAX(version_no), 0) AS max_version
        FROM analysis_result_versions
        WHERE project_id = ?
        """,
        (project_id,),
    ).fetchone()
    version_no = int(row["max_version"] or 0) + 1
    version_id = make_id("analysisver")
    timestamp = now_iso()
    input_package = (brief or {}).get("input_package") or {}
    samples = input_package.get("samples") or []
    question_ids = [
        sample.get("question_id")
        for sample in samples
        if isinstance(sample, dict) and sample.get("question_id")
    ]
    conn.execute(
        """
        INSERT INTO analysis_result_versions (
          analysis_version_id, project_id, version_no, status, source,
          analyzer_version, analysis_count, recommendation_count,
          action_task_count, question_ids_json, input_package_json,
          result_json, validation_json, review_decisions_json, llm_meta_json,
          note, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            version_id,
            project_id,
            version_no,
            "confirmed",
            str(source or "llm_confirm")[:80],
            LLM_CONFIRMED_ANALYZER_VERSION,
            int(saved_analysis_count or 0),
            int(saved_recommendation_count or 0),
            int(saved_action_task_count or 0),
            json_dump(question_ids),
            json_dump(input_package),
            json_dump(result_obj or {}),
            json_dump(validation or {}),
            json_dump(review_decisions or []),
            json_dump(llm_meta or {}),
            str(note or "")[:500],
            timestamp,
            timestamp,
        ),
    )
    return analysis_result_version_to_dict(
        conn.execute(
            "SELECT * FROM analysis_result_versions WHERE analysis_version_id = ?",
            (version_id,),
        ).fetchone()
    )


def db_project_analysis_versions_payload(project_id, query=None):
    project_id = unquote(str(project_id or "").strip())
    query = query or {}
    limit = parse_bounded_int((query.get("limit") or [5])[0], default=5, minimum=1, maximum=50)
    with db_connect() as conn:
        ensure_analysis_result_versions_table(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        rows = conn.execute(
            """
            SELECT *
            FROM analysis_result_versions
            WHERE project_id = ?
            ORDER BY version_no DESC, created_at DESC
            LIMIT ?
            """,
            (project_id, limit),
        ).fetchall()
    return {
        "ok": True,
        "project": project,
        "versions": [analysis_result_version_to_dict(row) for row in rows],
        "source": "sqlite",
    }


def update_recommendation_execution_status(conn, recommendation_id):
    if not recommendation_id:
        return
    rows = conn.execute(
        """
        SELECT status
        FROM action_tasks
        WHERE recommendation_id = ?
        """,
        (recommendation_id,),
    ).fetchall()
    if not rows:
        return
    statuses = [normalize_action_task_status(row["status"]) for row in rows]
    if all(status == "done" for status in statuses):
        execution_status = "completed"
    elif any(status == "blocked" for status in statuses):
        execution_status = "blocked"
    elif any(status == "doing" for status in statuses):
        execution_status = "in_progress"
    else:
        execution_status = "not_started"
    conn.execute(
        """
        UPDATE recommendations
        SET execution_status = ?, updated_at = ?
        WHERE recommendation_id = ?
        """,
        (execution_status, now_iso(), recommendation_id),
    )


def db_update_action_task_payload(project_id, action_task_id, payload):
    project_id = unquote(str(project_id or "").strip())
    action_task_id = unquote(str(action_task_id or "").strip())
    timestamp = now_iso()
    with db_connect() as conn:
        ensure_action_workbench_fields(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        row = conn.execute(
            """
            SELECT *
            FROM action_tasks
            WHERE project_id = ? AND action_task_id = ?
            """,
            (project_id, action_task_id),
        ).fetchone()
        if not row:
            raise ValueError(f"Unknown action_task_id: {action_task_id}")

        current = decorate_action_task(row)
        recommendation_row = conn.execute(
            "SELECT * FROM recommendations WHERE project_id = ? AND recommendation_id = ?",
            (project_id, current.get("recommendation_id", "")),
        ).fetchone()
        recommendation = db_row_to_dict(recommendation_row) or {}
        recommendation_plan = recommendation.get("implementation_plan")
        recommendation_plan = recommendation_plan if isinstance(recommendation_plan, dict) else {}
        linked_draft = next(
            (
                item
                for item in recommendation_task_drafts(recommendation_plan)
                if str(item.get("linked_action_task_id") or "") == action_task_id
                and item.get("status") == "approved"
            ),
            None,
        )
        formal_approved = bool(linked_draft and recommendation.get("approval_status") == "approved")
        status = normalize_action_task_status(payload.get("status", current.get("status")))
        started_at = current.get("started_at", "")
        completed_at = current.get("completed_at", "")
        if status == "doing" and not started_at:
            started_at = timestamp
        if status == "done" and not completed_at:
            completed_at = timestamp
        if status != "done":
            completed_at = "" if payload.get("clear_completed_at") else completed_at
        retest_status = str(payload.get("retest_status") or current.get("retest_status") or "").strip()
        if status == "done" and retest_status in {"", "not_ready"}:
            retest_status = "ready"
        if status in {"todo", "doing", "blocked"} and retest_status == "ready":
            retest_status = "not_ready"

        owner = str(payload.get("owner", current.get("owner", "")) or "").strip()[:100]
        due_date = str(payload.get("due_date", current.get("due_date", "")) or "").strip()[:30]
        execution_note = str(payload.get("execution_note", current.get("execution_note", "")) or "").strip()[:2000]
        evidence_url = str(payload.get("evidence_url", current.get("evidence_url", "")) or "").strip()[:500]
        blocked_reason = str(payload.get("blocked_reason", current.get("blocked_reason", "")) or "").strip()[:1000]

        if status != "todo" and not formal_approved:
            raise ValueError("历史规则任务必须先形成合格草稿并经人工批准，才能开始执行。")
        if status in {"doing", "done"} and not owner:
            raise ValueError("开始执行前必须填写负责人。")
        if status in {"doing", "done"} and not due_date:
            raise ValueError("开始执行前必须填写截止时间。")
        if status == "doing" and not execution_note:
            raise ValueError("开始执行前必须填写执行说明。")
        if status == "done" and not execution_note:
            raise ValueError("标记已交付前必须填写执行说明。")
        if status == "done" and not evidence_url:
            raise ValueError("标记已交付前必须填写交付证据。")
        if status == "done" and payload.get("acceptance_confirmed") is not True:
            raise ValueError("标记已交付前必须完成人工验收确认。")
        if status == "blocked" and not blocked_reason:
            raise ValueError("暂缓任务需要填写暂缓原因。")

        conn.execute(
            """
            UPDATE action_tasks
            SET status = ?, owner = ?, due_date = ?, execution_note = ?,
                evidence_url = ?, retest_status = ?, started_at = ?,
                blocked_reason = ?, completed_at = ?, updated_at = ?
            WHERE project_id = ? AND action_task_id = ?
            """,
            (
                status,
                owner,
                due_date,
                execution_note,
                evidence_url,
                retest_status,
                started_at,
                blocked_reason,
                completed_at,
                timestamp,
                project_id,
                action_task_id,
            ),
        )
        if linked_draft:
            updated_draft = dict(linked_draft)
            if status != "todo" and not updated_draft.get("scope_frozen_at"):
                updated_draft["scope_frozen_at"] = timestamp
            if status == "done" and payload.get("acceptance_confirmed") is True:
                updated_draft["delivery_acceptance"] = {
                    "confirmed": True,
                    "confirmed_at": timestamp,
                    "evidence_url": evidence_url,
                    "execution_note_recorded": True,
                }
            updated_draft["updated_at"] = timestamp
            recommendation_plan = replace_recommendation_task_draft(recommendation_plan, updated_draft)
            conn.execute(
                """
                UPDATE recommendations
                SET implementation_plan_json = ?, updated_at = ?
                WHERE project_id = ? AND recommendation_id = ?
                """,
                (
                    json.dumps(recommendation_plan, ensure_ascii=False),
                    timestamp,
                    project_id,
                    current.get("recommendation_id", ""),
                ),
            )
        update_recommendation_execution_status(conn, current.get("recommendation_id", ""))
        conn.commit()
        updated = conn.execute(
            """
            SELECT *
            FROM action_tasks
            WHERE project_id = ? AND action_task_id = ?
            """,
            (project_id, action_task_id),
        ).fetchone()
        task = decorate_action_task(updated)
    recommendations_payload = db_project_recommendations_payload(project_id)
    task = next(
        (
            item
            for item in recommendations_payload.get("action_tasks", [])
            if item.get("action_task_id") == action_task_id
        ),
        task,
    )
    return {
        "ok": True,
        "project": project,
        "task": task,
        "recommendations": recommendations_payload,
        "source": "sqlite",
    }


def latest_baseline_run_id(conn, project_id):
    row = conn.execute(
        """
        SELECT run_id
        FROM sample_runs
        WHERE project_id = ?
          AND purpose = 'baseline'
          AND status IN ('completed', 'partial_failed', 'waiting_answer', 'running')
        ORDER BY
          CASE WHEN status = 'completed' THEN 0 ELSE 1 END,
          created_at DESC,
          run_id DESC
        LIMIT 1
        """,
        (project_id,),
    ).fetchone()
    return row["run_id"] if row else ""


def baseline_question_rows_for_retest(conn, project_id, baseline_run_id, limit=30):
    limit = parse_bounded_int(limit, default=30, minimum=1, maximum=50)
    rows = conn.execute(
        """
        SELECT
          q.question_id,
          q.question,
          q.category,
          q.intent,
          q.commercial_value,
          COALESCE(pq.priority, '') AS priority,
          COALESCE(pq.fit_reason, '') AS fit_reason
        FROM sample_tasks st
        JOIN sample_runs sr ON sr.run_id = st.run_id
        JOIN samples s
          ON s.project_id = sr.project_id
         AND s.run_id = st.run_id
         AND s.task_id = st.task_id
         AND s.question_id = st.question_id
         AND s.sample_type = 'real'
        JOIN question_pool q ON q.question_id = st.question_id
        LEFT JOIN project_questions pq
          ON pq.project_id = sr.project_id AND pq.question_id = st.question_id
        WHERE sr.project_id = ?
          AND sr.run_id = ?
        ORDER BY st.created_at, st.task_id
        LIMIT ?
        """,
        (project_id, baseline_run_id, limit),
    ).fetchall()
    return db_rows_to_list(rows)


def db_update_retest_question_selection_payload(project_id, action_task_id, payload):
    project_id = unquote(str(project_id or "").strip())
    action_task_id = unquote(str(action_task_id or "").strip())
    selected_question_ids = normalize_question_id_list(payload.get("selected_question_ids"))
    timestamp = now_iso()
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_recommendation_detail_fields(conn)
        ensure_retest_question_match_fields(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        task = conn.execute(
            """
            SELECT *
            FROM action_tasks
            WHERE project_id = ? AND action_task_id = ?
            """,
            (project_id, action_task_id),
        ).fetchone()
        if not task:
            raise ValueError(f"Unknown action_task_id: {action_task_id}")
        if normalize_action_task_status(task["status"]) != "todo" or str(task["started_at"] or "").strip():
            raise ValueError("任务开始执行后复测范围已冻结，不能再修改。重大变更请创建新修订任务。")
        if not selected_question_ids:
            raise ValueError("同题复测计划至少需要保留 1 个问题。")
        refresh_retest_question_matches(conn, project_id, action_task_id=action_task_id)
        matches = retest_question_match_rows(conn, project_id, action_task_id)
        match_by_question = {item["question_id"]: item for item in matches}
        unknown = [question_id for question_id in selected_question_ids if question_id not in match_by_question]
        if unknown:
            raise ValueError("存在不属于当前任务候选范围的复测题：" + "、".join(unknown[:5]))
        not_comparable = [
            question_id
            for question_id in selected_question_ids
            if not match_by_question.get(question_id, {}).get("before_run_id")
        ]
        if not_comparable:
            raise ValueError("以下问题没有前序批次样本，不能进入同题复测：" + "、".join(not_comparable[:5]))
        conn.execute(
            """
            UPDATE recommendation_retest_questions
            SET selected = 0, updated_at = ?
            WHERE project_id = ? AND action_task_id = ?
            """,
            (timestamp, project_id, action_task_id),
        )
        for question_id in selected_question_ids:
            conn.execute(
                """
                UPDATE recommendation_retest_questions
                SET selected = 1, updated_at = ?
                WHERE project_id = ? AND action_task_id = ? AND question_id = ?
                """,
                (timestamp, project_id, action_task_id, question_id),
            )
        conn.commit()
    data = db_project_recommendations_payload(project_id)
    updated_task = next(
        (item for item in data.get("action_tasks", []) if item.get("action_task_id") == action_task_id),
        None,
    )
    return {
        "ok": True,
        "project": data.get("project"),
        "action_task": updated_task,
        "selected_question_ids": selected_question_ids,
        "recommendations": data,
        "source": "sqlite",
    }


def extract_question_ids(value):
    if isinstance(value, dict):
        parts = [value.get("question_id", ""), value.get("evidence_text", ""), value.get("sample_id", "")]
    elif isinstance(value, (list, tuple, set)):
        found = []
        for item in value:
            found.extend(extract_question_ids(item))
        return list(dict.fromkeys(found))
    else:
        parts = [value]
    found = []
    for part in parts:
        for match in re.findall(r"Q\d+", str(part or "").upper()):
            found.append(match)
    return list(dict.fromkeys(found))


def normalize_question_id_list(value):
    if value is None:
        return []
    if isinstance(value, str):
        return extract_question_ids(value)
    if isinstance(value, (list, tuple, set)):
        found = []
        for item in value:
            if isinstance(item, dict):
                found.extend(extract_question_ids(item))
            else:
                text = str(item or "").strip().upper()
                if re.fullmatch(r"Q\d+", text):
                    found.append(text)
                else:
                    found.extend(extract_question_ids(text))
        return list(dict.fromkeys(found))
    return extract_question_ids(value)


def contains_any(text, tokens):
    haystack = str(text or "")
    return any(token in haystack for token in tokens)


def retest_candidate_question_rows(conn, project_id):
    ensure_question_quality_fields(conn)
    rows = conn.execute(
        """
        WITH real_samples AS (
          SELECT project_id, question_id, COUNT(*) AS real_sample_count
          FROM samples
          WHERE sample_type = 'real'
          GROUP BY project_id, question_id
        ),
        analysis_flags AS (
          SELECT
            project_id,
            question_id,
            MAX(brand_mentioned) AS brand_mentioned,
            MAX(brand_recommended) AS brand_recommended,
            MAX(CASE WHEN LENGTH(high_risk_json) > 2 THEN 1 ELSE 0 END) AS has_high_risk,
            MAX(CASE
              WHEN risk_level LIKE '%极高%' THEN 3
              WHEN risk_level LIKE '%高%' THEN 2
              WHEN risk_level LIKE '%中%' THEN 1
              ELSE 0
            END) AS risk_score,
            MAX(CASE WHEN LENGTH(competitors_json) > 2 THEN 1 ELSE 0 END) AS has_competitors
          FROM analysis_results
          GROUP BY project_id, question_id
        )
        SELECT
          q.question_id,
          q.question,
          q.category,
          q.intent,
          q.commercial_value,
          q.competition_level,
          q.is_core,
          pq.priority,
          pq.fit_reason,
          pq.target_positioning,
          pq.status AS project_question_status,
          pq.review_status,
          COALESCE(rs.real_sample_count, 0) AS real_sample_count,
          COALESCE(af.brand_mentioned, 0) AS brand_mentioned,
          COALESCE(af.brand_recommended, 0) AS brand_recommended,
          COALESCE(af.has_high_risk, 0) AS has_high_risk,
          COALESCE(af.risk_score, 0) AS risk_score,
          COALESCE(af.has_competitors, 0) AS has_competitors,
          COALESCE((
            SELECT sr.run_id
            FROM sample_tasks st
            JOIN sample_runs sr ON sr.run_id = st.run_id
            JOIN samples s
              ON s.project_id = sr.project_id
             AND s.run_id = st.run_id
             AND s.task_id = st.task_id
             AND s.question_id = st.question_id
             AND s.sample_type = 'real'
            WHERE sr.project_id = pq.project_id
              AND st.question_id = q.question_id
            ORDER BY
              CASE WHEN sr.purpose = 'baseline' THEN 0 ELSE 1 END,
              sr.created_at DESC,
              sr.run_id DESC
            LIMIT 1
          ), '') AS before_run_id,
          COALESCE((
            SELECT CASE WHEN sr.purpose = 'baseline' THEN 1 ELSE 0 END
            FROM sample_tasks st
            JOIN sample_runs sr ON sr.run_id = st.run_id
            JOIN samples s
              ON s.project_id = sr.project_id
             AND s.run_id = st.run_id
             AND s.task_id = st.task_id
             AND s.question_id = st.question_id
             AND s.sample_type = 'real'
            WHERE sr.project_id = pq.project_id
              AND st.question_id = q.question_id
            ORDER BY
              CASE WHEN sr.purpose = 'baseline' THEN 0 ELSE 1 END,
              sr.created_at DESC,
              sr.run_id DESC
            LIMIT 1
          ), 0) AS in_baseline
        FROM project_questions pq
        JOIN question_pool q ON q.question_id = pq.question_id
        LEFT JOIN real_samples rs
          ON rs.project_id = pq.project_id AND rs.question_id = pq.question_id
        LEFT JOIN analysis_flags af
          ON af.project_id = pq.project_id AND af.question_id = pq.question_id
        WHERE pq.project_id = ?
          AND pq.status = 'active'
          AND COALESCE(pq.review_status, 'pending') = 'approved'
        """,
        (project_id,),
    ).fetchall()
    candidates = []
    for row in db_rows_to_list(rows):
        if is_internal_retest_question(row.get("question", "")):
            continue
        candidates.append(row)
    return candidates


def score_retest_candidate(candidate, recommendation, task, evidence_question_ids):
    rec_text = " ".join(
        str(value or "")
        for value in [
            recommendation.get("category"),
            recommendation.get("title"),
            recommendation.get("reason"),
            recommendation.get("action"),
            task.get("title"),
            task.get("done_definition"),
        ]
    )
    question_text = " ".join(
        str(value or "")
        for value in [
            candidate.get("question"),
            candidate.get("category"),
            candidate.get("intent"),
            candidate.get("fit_reason"),
            candidate.get("target_positioning"),
        ]
    )
    category = str(candidate.get("category") or "")
    score = 0.0
    reasons = []
    question_id = candidate.get("question_id")

    if question_id in evidence_question_ids:
        score += 120
        reasons.append("建议证据题")
    if candidate.get("real_sample_count"):
        score += 35
        reasons.append("已有前序样本")
    if candidate.get("in_baseline"):
        score += 15
        reasons.append("属于优化前基线")
    if candidate.get("is_core"):
        score += 10
        reasons.append("核心问题")

    risk_intent = contains_any(rec_text, ["风险", "幻觉", "事实", "资质", "成立", "官网", "案例", "禁用", "纠偏"])
    if risk_intent:
        if candidate.get("has_high_risk") or int(candidate.get("risk_score") or 0) >= 2:
            score += 40
            reasons.append("命中过高风险样本")
        if category in {"风险事实", "案例资质", "品牌认知"}:
            score += 16
            reasons.append("适合事实风险复测")

    content_intent = contains_any(rec_text, ["内容", "官网", "FAQ", "服务页", "案例", "公开", "引用", "曝光", "推荐"])
    if content_intent:
        if not candidate.get("brand_mentioned"):
            score += 28
            reasons.append("当前品牌缺席")
        elif not candidate.get("brand_recommended"):
            score += 16
            reasons.append("当前未被推荐")
        if category in {"本地采购", "服务推荐", "内容机会", "品牌认知", "复测验证"}:
            score += 14
            reasons.append("贴近内容补齐目标")

    competitor_intent = contains_any(rec_text, ["竞品", "对比", "差异", "替代", "占位", "平台型", "传统"])
    if competitor_intent:
        if category == "竞品对比":
            score += 35
            reasons.append("竞品对比题")
        if candidate.get("has_competitors") or contains_any(question_text, ["对比", "区别", "谁更", "哪家"]):
            score += 18
            reasons.append("可验证竞品占位变化")

    monitoring_intent = contains_any(rec_text, ["补采", "监测", "基线", "复测", "同题", "样本"])
    if monitoring_intent:
        score += min(int(candidate.get("commercial_value") or 0), 5) * 4
        if candidate.get("real_sample_count"):
            score += 12
        reasons.append("适合持续监测")

    if category == "复测验证":
        score += 10
        reasons.append("自然复测题")

    overlap_bonus = 0
    for token in ["官网", "案例", "资质", "成立", "数字人", "企业宣传片", "AIGC", "TVC", "本地", "示例地区", "示例城市", "高端", "定制"]:
        if token in rec_text and token in question_text:
            overlap_bonus += 5
    if overlap_bonus:
        score += min(overlap_bonus, 20)
        reasons.append("语义关键词匹配")

    if score <= 0:
        score = min(int(candidate.get("commercial_value") or 0), 5) * 3
        if score:
            reasons.append("高商业价值候选")

    return score, "；".join(dict.fromkeys(reasons)) or "同类候选题"


def stable_retest_match_id(project_id, action_task_id, question_id):
    digest = hashlib.sha256(
        f"{project_id}|{action_task_id}|{question_id}".encode("utf-8")
    ).hexdigest()[:16]
    return f"rqm_{safe_db_token(project_id)}_{digest}"


def refresh_retest_question_matches(conn, project_id, action_task_id=""):
    """Refresh editable task candidates without deleting selections or frozen scopes."""
    ensure_retest_question_match_fields(conn)
    timestamp = now_iso()
    params = [project_id]
    task_filter = ""
    if action_task_id:
        task_filter = " AND at.action_task_id = ?"
        params.append(action_task_id)
    action_rows = db_rows_to_list(
        conn.execute(
            f"""
            SELECT
              at.*,
              r.category AS recommendation_category,
              r.title AS recommendation_title,
              r.reason AS recommendation_reason,
              r.action AS recommendation_action,
              r.priority AS recommendation_priority
            FROM action_tasks at
            LEFT JOIN recommendations r ON r.recommendation_id = at.recommendation_id
            WHERE at.project_id = ?{task_filter}
            ORDER BY at.priority, at.created_at, at.action_task_id
            """,
            params,
        ).fetchall()
    )
    if not action_rows:
        return

    evidence_rows = db_rows_to_list(
        conn.execute(
            """
            SELECT e.*
            FROM recommendation_evidence e
            JOIN recommendations r ON r.recommendation_id = e.recommendation_id
            WHERE r.project_id = ?
            ORDER BY e.recommendation_id, e.created_at, e.evidence_id
            """,
            (project_id,),
        ).fetchall()
    )
    evidence_by_recommendation = {}
    for evidence in evidence_rows:
        ids = extract_question_ids(evidence)
        evidence_by_recommendation.setdefault(evidence.get("recommendation_id", ""), []).extend(ids)

    candidates = retest_candidate_question_rows(conn, project_id)
    existing_matches = {
        (row["action_task_id"], row["question_id"]): db_row_to_dict(row)
        for row in conn.execute(
            """
            SELECT *
            FROM recommendation_retest_questions
            WHERE project_id = ?
            """,
            (project_id,),
        ).fetchall()
    }
    for task in action_rows:
        if normalize_action_task_status(task.get("status")) != "todo" or str(task.get("started_at") or "").strip():
            continue
        recommendation = {
            "category": task.get("recommendation_category", ""),
            "title": task.get("recommendation_title", ""),
            "reason": task.get("recommendation_reason", ""),
            "action": task.get("recommendation_action", ""),
            "priority": task.get("recommendation_priority", task.get("priority", "")),
        }
        evidence_question_ids = list(dict.fromkeys(evidence_by_recommendation.get(task.get("recommendation_id", ""), [])))
        scored = []
        for candidate in candidates:
            score, reason = score_retest_candidate(candidate, recommendation, task, evidence_question_ids)
            if score <= 0:
                continue
            scored.append((score, reason, candidate))
        scored.sort(
            key=lambda item: (
                -item[0],
                -int(item[2].get("real_sample_count") or 0),
                -int(item[2].get("commercial_value") or 0),
                item[2].get("question_id", ""),
            )
        )
        for score, reason, candidate in scored[:5]:
            task_id = task.get("action_task_id", "")
            question_id = candidate.get("question_id", "")
            existing = existing_matches.get((task_id, question_id))
            if existing:
                conn.execute(
                    """
                    UPDATE recommendation_retest_questions
                    SET score = ?, reason = ?, has_before_sample = ?,
                        before_run_id = ?, in_baseline = ?, updated_at = ?
                    WHERE match_id = ?
                    """,
                    (
                        float(score),
                        reason[:500],
                        1 if candidate.get("real_sample_count") else 0,
                        candidate.get("before_run_id", ""),
                        1 if candidate.get("in_baseline") else 0,
                        timestamp,
                        existing["match_id"],
                    ),
                )
                continue
            match_id = stable_retest_match_id(project_id, task_id, question_id)
            conn.execute(
                """
                INSERT INTO recommendation_retest_questions (
                  match_id, project_id, recommendation_id, action_task_id,
                  question_id, score, reason, source, has_before_sample,
                  before_run_id, in_baseline, selected, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    match_id,
                    project_id,
                    task.get("recommendation_id", ""),
                    task_id,
                    question_id,
                    float(score),
                    reason[:500],
                    "rules_v1",
                    1 if candidate.get("real_sample_count") else 0,
                    candidate.get("before_run_id", ""),
                    1 if candidate.get("in_baseline") else 0,
                    1 if candidate.get("before_run_id") else 0,
                    timestamp,
                    timestamp,
                ),
            )


def retest_question_match_rows(conn, project_id, action_task_id=""):
    params = [project_id]
    filters = ["m.project_id = ?"]
    if action_task_id:
        filters.append("m.action_task_id = ?")
        params.append(action_task_id)
    rows = conn.execute(
        f"""
        SELECT
          m.*,
          q.question,
          q.category,
          q.intent,
          q.commercial_value,
          q.is_core,
          pq.priority,
          pq.review_status,
          pq.status AS project_question_status
        FROM recommendation_retest_questions m
        JOIN question_pool q ON q.question_id = m.question_id
        LEFT JOIN project_questions pq
          ON pq.project_id = m.project_id AND pq.question_id = m.question_id
        WHERE {" AND ".join(filters)}
        ORDER BY m.action_task_id, m.score DESC, CAST(SUBSTR(m.question_id, 2) AS INTEGER), m.question_id
        """,
        params,
    ).fetchall()
    items = db_rows_to_list(rows)
    for item in items:
        item["selected"] = bool(item.get("selected"))
        item["selectable"] = bool(item.get("before_run_id"))
    return items


def best_retest_source_run_id(conn, project_id, question_ids):
    question_ids = normalize_question_id_list(question_ids)
    if not question_ids:
        return ""
    placeholders = ",".join("?" for _ in question_ids)
    rows = conn.execute(
        f"""
        SELECT
          sr.run_id,
          sr.purpose,
          sr.created_at,
          COUNT(DISTINCT st.question_id) AS matched_count
        FROM sample_runs sr
        JOIN sample_tasks st ON st.run_id = sr.run_id
        JOIN samples s
          ON s.project_id = sr.project_id
         AND s.run_id = st.run_id
         AND s.task_id = st.task_id
         AND s.question_id = st.question_id
         AND s.sample_type = 'real'
        WHERE sr.project_id = ?
          AND st.question_id IN ({placeholders})
        GROUP BY sr.run_id, sr.purpose, sr.created_at
        HAVING COUNT(DISTINCT st.question_id) = ?
        ORDER BY
          matched_count DESC,
          CASE WHEN sr.purpose = 'baseline' THEN 0 ELSE 1 END,
          sr.created_at DESC,
          sr.run_id DESC
        LIMIT 1
        """,
        [project_id, *question_ids, len(question_ids)],
    ).fetchone()
    return rows["run_id"] if rows else ""


def question_rows_from_run_for_retest(conn, project_id, run_id, question_ids, limit=30):
    wanted = normalize_question_id_list(question_ids)
    order = {question_id: index for index, question_id in enumerate(wanted)}
    rows = baseline_question_rows_for_retest(conn, project_id, run_id, limit=max(limit, len(wanted) or 1))
    if wanted:
        rows = [row for row in rows if row.get("question_id") in order]
        rows.sort(key=lambda row: order.get(row.get("question_id"), 9999))
    return rows[: parse_bounded_int(limit, default=30, minimum=1, maximum=50)]


def existing_open_retest(conn, project_id, action_task_id):
    ensure_retest_workbench_fields(conn)
    row = conn.execute(
        """
        SELECT *
        FROM retest_runs
        WHERE project_id = ?
          AND related_action_task_id = ?
          AND status IN ('planned', 'sampling', 'waiting_answer')
        ORDER BY created_at DESC, retest_run_id DESC
        LIMIT 1
        """,
        (project_id, action_task_id),
    ).fetchone()
    return db_row_to_dict(row)


def db_prepare_retest_payload(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    action_task_id = str(payload.get("action_task_id", "") or "").strip()
    baseline_run_id = str(payload.get("baseline_run_id", "") or "").strip()
    if not action_task_id:
        raise ValueError("缺少 action_task_id")

    timestamp = now_iso()
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_action_workbench_fields(conn)
        ensure_retest_workbench_fields(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        task_row = conn.execute(
            """
            SELECT *
            FROM action_tasks
            WHERE project_id = ? AND action_task_id = ?
            """,
            (project_id, action_task_id),
        ).fetchone()
        if not task_row:
            raise ValueError(f"Unknown action_task_id: {action_task_id}")
        task = decorate_action_task(task_row)
        if not (task.get("retest_ready") or normalize_action_task_status(task.get("status")) == "done"):
            raise ValueError("请先将该优化任务标记为已完成，再创建复测批次")

        ensure_retest_question_match_fields(conn)
        refresh_retest_question_matches(conn, project_id, action_task_id=action_task_id)
        matched_questions = retest_question_match_rows(conn, project_id, action_task_id)
        limit = parse_bounded_int(payload.get("limit", 30), default=30, minimum=1, maximum=50)
        requested_question_ids = normalize_question_id_list(payload.get("question_ids"))
        frozen_question_ids = [
            item["question_id"]
            for item in matched_questions
            if item.get("selected")
        ]
        if not frozen_question_ids:
            raise ValueError("该任务没有已冻结的同题复测范围，不能创建复测批次。")
        if requested_question_ids and set(requested_question_ids) != set(frozen_question_ids):
            raise ValueError("复测必须完整使用已冻结的问题范围，不允许提交子集或额外问题。")
        requested_question_ids = frozen_question_ids
        if len(requested_question_ids) > 50:
            raise ValueError("已冻结复测范围超过 50 题，不能静默缩减，请创建修订任务。")
        limit = max(limit, len(requested_question_ids))
        if not baseline_run_id:
            baseline_run_id = best_retest_source_run_id(conn, project_id, requested_question_ids)
        if not baseline_run_id:
            raise ValueError("没有一个前序批次同时包含全部冻结问题的精确样本，已阻止复测比较。")
        baseline_run = db_project_run_detail(conn, project_id, baseline_run_id)
        if not baseline_run:
            raise ValueError(f"Unknown baseline_run_id: {baseline_run_id}")

        existing = existing_open_retest(conn, project_id, action_task_id)
        if existing and existing.get("after_run_id"):
            existing_run = db_project_run_detail(conn, project_id, existing["after_run_id"])
            if existing_run:
                if existing_run.get("sampler") == "doubao_assisted_batch":
                    response = assisted_batch_response(
                        existing_run,
                        db_sync={"ok": True, "mode": "existing_retest"},
                    )
                    current_task = response.get("current_task")
                    if current_task:
                        set_clipboard_text(current_task["question"])
                else:
                    response = {
                        "ok": True,
                        "run": existing_run,
                        "summary": run_summary(existing_run),
                        "current_task": next(
                            (item for item in existing_run.get("tasks", []) if item.get("status") == "queued"),
                            None,
                        ),
                        "source": "sqlite",
                    }
                response["retest_run"] = existing
                response["baseline_run"] = run_summary(baseline_run)
                response["action_task"] = task
                response["matched_questions"] = matched_questions
                response["reused"] = True
                return response

        selected = question_rows_from_run_for_retest(
            conn,
            project_id,
            baseline_run_id,
            requested_question_ids,
            limit=limit,
        )
        selected_ids = [item.get("question_id") for item in selected]
        missing_question_ids = [question_id for question_id in requested_question_ids if question_id not in selected_ids]
        if missing_question_ids:
            raise ValueError("指定基线批次缺少精确样本，已阻止复测：" + "、".join(missing_question_ids[:10]))

        baseline_sampler = str(baseline_run.get("sampler") or "")
        if baseline_sampler not in WEBSEARCH_SAMPLERS and baseline_sampler != "doubao_assisted_batch":
            raise ValueError("该基线采样方式不支持严格同配置复测，请先建立新的正式基线")
        baseline_config_snapshot = baseline_run.get("config_snapshot")
        if not isinstance(baseline_config_snapshot, dict):
            baseline_config_snapshot = {}
        baseline_model = str(
            baseline_run.get("model_name")
            or baseline_config_snapshot.get("model")
            or ""
        ).strip()
        if baseline_sampler in WEBSEARCH_SAMPLERS and (not baseline_model or not baseline_config_snapshot):
            raise ValueError("该历史基线未保存模型或配置快照，无法保证严格可比，请先建立新的正式基线")

        assisted_retest = baseline_sampler == "doubao_assisted_batch"
        run = {
            "run_id": make_id("run"),
            "name": str(payload.get("name", "优化后复测批次")).strip() or "优化后复测批次",
            "platform": baseline_run.get("platform") or project.get("platform") or "豆包",
            "sampler": baseline_sampler,
            "cycle_id": "",
            "baseline_run_id": baseline_run_id,
            "model_name": baseline_model,
            "config_snapshot": baseline_config_snapshot,
            "scope": "retest_matched" if requested_question_ids else "retest_baseline",
            "category": "",
            "purpose": "retest",
            "status": "waiting_answer" if assisted_retest else "queued",
            "created_at": timestamp,
            "started_at": timestamp if assisted_retest else "",
            "completed_at": "",
            "tasks": [build_project_task(question) for question in selected],
        }
        first_task = current_waiting_task(run) if assisted_retest else run["tasks"][0]
        if not first_task:
            raise ValueError("复测批次没有可提交的任务")
        if assisted_retest:
            first_task["status"] = "waiting_answer"
        recompute_run_counts(run)
        upsert_project_run_to_db(conn, project_id, run)

        retest_run = {
            "retest_run_id": make_id("retest"),
            "project_id": project_id,
            "baseline_run_id": baseline_run_id,
            "after_run_id": run["run_id"],
            "related_recommendation_id": task.get("recommendation_id", ""),
            "related_action_task_id": action_task_id,
            "status": "sampling",
            "conclusion": "",
            "note": str(payload.get("note", "") or "优化任务完成后创建复测批次")[:500],
            "created_at": timestamp,
            "completed_at": "",
        }
        conn.execute(
            """
            INSERT INTO retest_runs (
              retest_run_id, project_id, baseline_run_id, after_run_id,
              related_recommendation_id, related_action_task_id, status,
              conclusion, note, created_at, completed_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                retest_run["retest_run_id"],
                retest_run["project_id"],
                retest_run["baseline_run_id"],
                retest_run["after_run_id"],
                retest_run["related_recommendation_id"],
                retest_run["related_action_task_id"],
                retest_run["status"],
                retest_run["conclusion"],
                retest_run["note"],
                retest_run["created_at"],
                retest_run["completed_at"],
            ),
        )
        conn.execute(
            """
            UPDATE action_tasks
            SET retest_status = 'created', updated_at = ?
            WHERE project_id = ? AND action_task_id = ?
            """,
            (timestamp, project_id, action_task_id),
        )
        conn.commit()

    if assisted_retest:
        set_clipboard_text(first_task["question"])
        response = assisted_batch_response(run, db_sync={"ok": True, "mode": "retest_prepared"})
    else:
        response = {
            "ok": True,
            "run": run,
            "summary": run_summary(run),
            "current_task": first_task,
            "source": "sqlite",
        }
    response["retest_run"] = retest_run
    response["baseline_run"] = run_summary(baseline_run)
    response["action_task"] = task
    response["matched_questions"] = matched_questions
    response["reused"] = False
    return response


RISK_LEVEL_SCORE = {"低": 0, "中": 1, "高": 2, "极高": 3}

RETEST_METRIC_META = {
    "brand_mention_rate": {"label": "品牌出现率", "direction": "higher"},
    "brand_recommendation_rate": {"label": "被推荐率", "direction": "higher"},
    "high_risk_rate": {"label": "高风险率", "direction": "lower"},
    "competitor_mentions_per_question": {"label": "竞品提及/题", "direction": "lower"},
}


def format_rate(value):
    return f"{round((float(value or 0)) * 100)}%"


def retest_metric_label(metric_name):
    return RETEST_METRIC_META.get(metric_name, {}).get("label", metric_name)


def retest_metric_direction(metric_name):
    return RETEST_METRIC_META.get(metric_name, {}).get("direction", "higher")


def load_project_analysis_inputs(conn, project):
    facts = db_rows_to_list(
        conn.execute(
            """
            SELECT *
            FROM customer_facts
            WHERE customer_id = ? AND fact_type <> 'question_profile'
            ORDER BY fact_type, fact_id
            """,
            (project["customer_id"],),
        ).fetchall()
    )
    competitors = db_rows_to_list(
        conn.execute(
            """
            SELECT *
            FROM competitors
            WHERE customer_id = ?
            ORDER BY competitor_id
            """,
            (project["customer_id"],),
        ).fetchall()
    )
    forbidden_claims = db_rows_to_list(
        conn.execute(
            """
            SELECT *
            FROM forbidden_claims
            WHERE customer_id = ?
            ORDER BY claim_id
            """,
            (project["customer_id"],),
        ).fetchall()
    )
    return facts, competitors, forbidden_claims, project_fact_context(project, facts, competitors)


def run_sample_rows_for_direct_analysis(conn, project_id, run_id):
    rows = conn.execute(
        """
        SELECT
          s.sample_id,
          s.project_id,
          st.run_id,
          st.task_id,
          st.question_id,
          s.platform,
          s.answer_text,
          s.source_url,
          s.screenshot_path,
          s.sample_type,
          s.collected_at,
          q.question,
          q.category,
          q.intent
        FROM sample_tasks st
        JOIN question_pool q ON q.question_id = st.question_id
        JOIN samples s
          ON s.project_id = ?
         AND s.run_id = st.run_id
         AND s.task_id = st.task_id
         AND s.question_id = st.question_id
         AND s.sample_type = 'real'
        WHERE st.run_id = ?
        ORDER BY st.created_at, st.task_id
        """,
        (project_id, run_id),
    ).fetchall()
    samples = []
    for row in db_rows_to_list(rows):
        if row.get("sample_id") and row.get("answer_text"):
            samples.append(row)
    return samples


def direct_run_analyses(conn, project, run_id):
    facts, competitors, forbidden_claims, context = load_project_analysis_inputs(conn, project)
    samples = run_sample_rows_for_direct_analysis(conn, project["project_id"], run_id)
    return [
        analyze_project_sample(sample, project, facts, competitors, forbidden_claims, context)
        for sample in samples
    ]


def analysis_has_high_risk(item):
    return bool(item.get("high_risk_hallucinations")) or "高" in str(item.get("risk_level") or "")


def retest_metrics(analyses):
    total = len(analyses)
    brand_mentions = sum(1 for item in analyses if item.get("brand_mentioned"))
    brand_recommendations = sum(1 for item in analyses if item.get("brand_recommended"))
    high_risk_samples = sum(1 for item in analyses if analysis_has_high_risk(item))
    competitor_mentions = sum(len(item.get("competitors") or []) for item in analyses)
    risk_score = sum(RISK_LEVEL_SCORE.get(str(item.get("risk_level") or "中"), 1) for item in analyses)
    return {
        "total": total,
        "brand_mentions": brand_mentions,
        "brand_mention_rate": ratio(brand_mentions, total),
        "brand_recommendations": brand_recommendations,
        "brand_recommendation_rate": ratio(brand_recommendations, total),
        "high_risk_samples": high_risk_samples,
        "high_risk_rate": ratio(high_risk_samples, total),
        "competitor_mentions": competitor_mentions,
        "competitor_mentions_per_question": ratio(competitor_mentions, total),
        "average_risk_score": ratio(risk_score, total),
    }


def retest_metric_verdict(metric_name, before_value, after_value):
    delta = float(after_value or 0) - float(before_value or 0)
    if abs(delta) < 0.0001:
        return "持平"
    direction = retest_metric_direction(metric_name)
    improved = delta > 0 if direction == "higher" else delta < 0
    return "改善" if improved else "变差"


def retest_overall_verdict(metric_rows):
    improved = sum(1 for row in metric_rows if row["verdict"] == "改善")
    worsened = sum(1 for row in metric_rows if row["verdict"] == "变差")
    if improved >= 2 and worsened == 0:
        return "明显改善"
    if improved >= 1 and worsened == 0:
        return "轻微改善"
    if worsened > improved:
        return "变差，需要继续优化"
    return "无明显变化"


def build_retest_comparison(conn, project_id, retest_run):
    project = db_project_detail(conn, project_id)
    if not project:
        return None
    baseline_run = db_project_run_detail(conn, project_id, retest_run.get("baseline_run_id", ""))
    after_run = db_project_run_detail(conn, project_id, retest_run.get("after_run_id", ""))
    if not baseline_run or not after_run:
        raise ValueError("复测缺少基线批次或复测批次")
    comparison_contract = {
        "platform": (baseline_run.get("platform"), after_run.get("platform")),
        "sampler": (baseline_run.get("sampler"), after_run.get("sampler")),
        "model_name": (baseline_run.get("model_name"), after_run.get("model_name")),
        "config_snapshot": (baseline_run.get("config_snapshot") or {}, after_run.get("config_snapshot") or {}),
    }
    mismatched_fields = [
        field
        for field, (before_value, after_value) in comparison_contract.items()
        if str(before_value or "") != str(after_value or "")
    ]
    if mismatched_fields:
        labels = {"platform": "平台", "sampler": "采样器", "model_name": "模型", "config_snapshot": "配置快照"}
        return {
            "status": "incomparable",
            "comparable": False,
            "overall_verdict": "",
            "conclusion": "复测执行口径与基线不一致，已阻止效果比较。",
            "blocked_reason": "不一致字段：" + "、".join(labels[field] for field in mismatched_fields),
            "metrics": [],
            "question_deltas": [],
            "baseline_run": run_summary(baseline_run),
            "after_run": run_summary(after_run),
        }
    planned_question_ids = list(dict.fromkeys(
        str(task.get("question_id") or "").strip()
        for task in after_run.get("tasks", [])
        if str(task.get("question_id") or "").strip()
    ))
    if after_run.get("status") != "completed":
        return {
            "status": "incomplete" if after_run.get("status") == "partial_failed" else (retest_run.get("status") or "sampling"),
            "comparable": False,
            "overall_verdict": "",
            "conclusion": "复测批次尚未完整结束，不能生成效果比较。",
            "blocked_reason": "复测批次必须全部完成且计划范围完整。",
            "metrics": [],
            "question_deltas": [],
            "planned_question_ids": planned_question_ids,
            "baseline_run": run_summary(baseline_run),
            "after_run": run_summary(after_run),
        }

    before_by_question = {
        item["question_id"]: item
        for item in direct_run_analyses(conn, project, baseline_run["run_id"])
    }
    after_by_question = {
        item["question_id"]: item
        for item in direct_run_analyses(conn, project, after_run["run_id"])
    }
    missing_before = [question_id for question_id in planned_question_ids if question_id not in before_by_question]
    missing_after = [question_id for question_id in planned_question_ids if question_id not in after_by_question]
    if not planned_question_ids or missing_before or missing_after:
        missing_parts = []
        if missing_before:
            missing_parts.append("基线缺失：" + "、".join(missing_before[:10]))
        if missing_after:
            missing_parts.append("复测缺失：" + "、".join(missing_after[:10]))
        return {
            "status": "incomplete",
            "comparable": False,
            "overall_verdict": "",
            "conclusion": "复测范围不完整，已阻止比较。",
            "blocked_reason": "；".join(missing_parts) or "复测批次没有计划问题。",
            "metrics": [],
            "question_deltas": [],
            "planned_question_ids": planned_question_ids,
            "missing_before_question_ids": missing_before,
            "missing_after_question_ids": missing_after,
            "baseline_run": run_summary(baseline_run),
            "after_run": run_summary(after_run),
        }

    common_question_ids = planned_question_ids

    before_items = [before_by_question[question_id] for question_id in common_question_ids]
    after_items = [after_by_question[question_id] for question_id in common_question_ids]
    before_metrics = retest_metrics(before_items)
    after_metrics = retest_metrics(after_items)
    metric_rows = []
    for metric_name in RETEST_METRIC_META:
        before_value = float(before_metrics.get(metric_name) or 0)
        after_value = float(after_metrics.get(metric_name) or 0)
        metric_rows.append(
            {
                "metric_name": metric_name,
                "metric_label": retest_metric_label(metric_name),
                "before_value": before_value,
                "after_value": after_value,
                "delta_value": after_value - before_value,
                "verdict": retest_metric_verdict(metric_name, before_value, after_value),
            }
        )

    question_deltas = []
    for question_id in common_question_ids:
        before = before_by_question[question_id]
        after = after_by_question[question_id]
        question_deltas.append(
            {
                "question_id": question_id,
                "question": after.get("question") or before.get("question") or "",
                "before": {
                    "brand_mentioned": bool(before.get("brand_mentioned")),
                    "brand_recommended": bool(before.get("brand_recommended")),
                    "risk_level": before.get("risk_level", ""),
                    "competitors": before.get("competitors") or [],
                    "high_risk_count": len(before.get("high_risk_hallucinations") or []),
                },
                "after": {
                    "brand_mentioned": bool(after.get("brand_mentioned")),
                    "brand_recommended": bool(after.get("brand_recommended")),
                    "risk_level": after.get("risk_level", ""),
                    "competitors": after.get("competitors") or [],
                    "high_risk_count": len(after.get("high_risk_hallucinations") or []),
                },
            }
        )

    overall = retest_overall_verdict(metric_rows)
    conclusion = (
        f"{overall}：同题复测 {len(common_question_ids)} 条。"
        f"品牌出现率 {format_rate(before_metrics['brand_mention_rate'])} -> {format_rate(after_metrics['brand_mention_rate'])}，"
        f"推荐率 {format_rate(before_metrics['brand_recommendation_rate'])} -> {format_rate(after_metrics['brand_recommendation_rate'])}，"
        f"高风险率 {format_rate(before_metrics['high_risk_rate'])} -> {format_rate(after_metrics['high_risk_rate'])}。"
    )
    return {
        "status": "awaiting_confirmation",
        "comparable": True,
        "overall_verdict": overall,
        "system_verdict": overall,
        "conclusion": conclusion,
        "system_conclusion": conclusion,
        "effect_confirmed": False,
        "question_count": len(common_question_ids),
        "planned_question_ids": planned_question_ids,
        "before_metrics": before_metrics,
        "after_metrics": after_metrics,
        "metrics": metric_rows,
        "question_deltas": question_deltas,
        "baseline_run": run_summary(baseline_run),
        "after_run": run_summary(after_run),
    }


def upsert_retest_comparison(conn, project_id, retest_run_id, *, confirmed=False, human_conclusion=""):
    ensure_retest_workbench_fields(conn)
    retest_row = conn.execute(
        """
        SELECT *
        FROM retest_runs
        WHERE project_id = ? AND retest_run_id = ?
        """,
        (project_id, retest_run_id),
    ).fetchone()
    if not retest_row:
        raise ValueError(f"Unknown retest_run_id: {retest_run_id}")
    retest_run = db_row_to_dict(retest_row)
    comparison = build_retest_comparison(conn, project_id, retest_run)
    if not comparison or comparison.get("status") != "awaiting_confirmation":
        return comparison
    if not confirmed:
        comparison["persisted"] = False
        return comparison
    human_conclusion = str(human_conclusion or "").strip()[:2000]
    if not human_conclusion:
        raise ValueError("请填写人工确认后的最终效果结论。")

    timestamp = now_iso()
    conn.execute("DELETE FROM retest_results WHERE retest_run_id = ?", (retest_run_id,))
    for index, metric in enumerate(comparison.get("metrics", []), start=1):
        conn.execute(
            """
            INSERT INTO retest_results (
              retest_result_id, retest_run_id, metric_name,
              before_value, after_value, delta_value, verdict, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                f"rr_{safe_db_token(retest_run_id)}_{index:03d}",
                retest_run_id,
                metric["metric_name"],
                metric["before_value"],
                metric["after_value"],
                metric["delta_value"],
                metric["verdict"],
                timestamp,
            ),
        )
    conn.execute(
        """
        UPDATE retest_runs
        SET status = 'completed', conclusion = ?, completed_at = ?
        WHERE retest_run_id = ?
        """,
        (human_conclusion, timestamp, retest_run_id),
    )
    action_task_id = retest_run.get("related_action_task_id", "")
    if action_task_id:
        conn.execute(
            """
            UPDATE action_tasks
            SET retest_status = 'tested', updated_at = ?
            WHERE project_id = ? AND action_task_id = ?
            """,
            (timestamp, project_id, action_task_id),
        )
    comparison["status"] = "completed"
    comparison["effect_confirmed"] = True
    comparison["final_conclusion"] = human_conclusion
    comparison["completed_at"] = timestamp
    comparison["persisted"] = True
    return comparison


def retest_result_to_dict(row):
    item = db_row_to_dict(row)
    item["metric_label"] = retest_metric_label(item.get("metric_name", ""))
    return item


def retest_payload_from_row(conn, project_id, row):
    retest = db_row_to_dict(row)
    results = [
        retest_result_to_dict(result)
        for result in conn.execute(
            """
            SELECT *
            FROM retest_results
            WHERE retest_run_id = ?
            ORDER BY retest_result_id
            """,
            (retest["retest_run_id"],),
        ).fetchall()
    ]
    baseline_run = db_project_run_detail(conn, project_id, retest.get("baseline_run_id", ""))
    after_run = db_project_run_detail(conn, project_id, retest.get("after_run_id", ""))
    comparison = None
    if after_run and after_run.get("status") == "completed":
        try:
            comparison = build_retest_comparison(conn, project_id, retest)
        except ValueError:
            comparison = None
    effect_confirmed = bool(retest.get("status") == "completed" and results and str(retest.get("conclusion") or "").strip())
    if comparison:
        comparison["effect_confirmed"] = effect_confirmed
        comparison["final_conclusion"] = retest.get("conclusion", "") if effect_confirmed else ""
        if effect_confirmed:
            comparison["status"] = "completed"
    return {
        **retest,
        "results": results,
        "comparison": comparison,
        "overall_verdict": comparison.get("overall_verdict") if comparison else "",
        "question_deltas": comparison.get("question_deltas", []) if comparison else [],
        "effect_confirmed": effect_confirmed,
        "final_effect_status": "verified" if effect_confirmed else ("awaiting_confirmation" if comparison and comparison.get("comparable") else "not_ready"),
        "baseline_run": run_summary(baseline_run) if baseline_run else None,
        "after_run": run_summary(after_run) if after_run else None,
    }


def db_project_retests_payload(project_id):
    project_id = unquote(str(project_id or "").strip())
    with db_connect() as conn:
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        rows = conn.execute(
            """
            SELECT *
            FROM retest_runs
            WHERE project_id = ?
            ORDER BY created_at DESC, retest_run_id DESC
            LIMIT 20
            """,
            (project_id,),
        ).fetchall()
        items = [retest_payload_from_row(conn, project_id, row) for row in rows]
    latest = items[0] if items else None
    return {
        "ok": True,
        "project": project,
        "items": items,
        "latest": latest,
        "source": "sqlite",
    }


def parse_bounded_int(value, default=100, minimum=1, maximum=500):
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        parsed = default
    return max(minimum, min(parsed, maximum))


def ratio(part, total):
    return part / total if total else 0


GEO_SCENE_SCORE_WEIGHTS = {
    "vendor_selection": 25,
    "demand_solution": 20,
    "brand_named_check": 15,
    "competitor_compare": 15,
    "risk_fact_check": 15,
    "budget_case_process": 10,
}

GEO_CATEGORY_TO_SCENE = {
    "brand_awareness": "brand_named_check",
    "local_procurement": "vendor_selection",
    "service_recommendation": "vendor_selection",
    "competitor_comparison": "competitor_compare",
    "price_budget": "budget_case_process",
    "case_qualification": "budget_case_process",
    "risk_fact_check": "risk_fact_check",
    "content_opportunity": "demand_solution",
    "retest_validation": "brand_named_check",
}


def clamp_geo_score(value):
    try:
        numeric = float(value or 0)
    except (TypeError, ValueError):
        numeric = 0
    return max(0, min(100, int(round(numeric))))


def has_json_payload(value):
    decoded = decode_json_field(value, [])
    if isinstance(decoded, list):
        return len(decoded) > 0
    if isinstance(decoded, dict):
        return bool(decoded)
    return bool(decoded)


def normalize_geo_scene_code(focus, category):
    focus_code = str(focus or "").strip()
    if focus_code in QUESTION_GENERATION_FOCUS_BY_CODE:
        return focus_code
    alias_code = QUESTION_GENERATION_FOCUS_ALIASES.get(focus_code)
    if alias_code in QUESTION_GENERATION_FOCUS_BY_CODE:
        return alias_code
    category_id = standard_category_id_for(category)
    return GEO_CATEGORY_TO_SCENE.get(category_id, "demand_solution")


def geo_scene_sample_status(sample_count):
    if sample_count >= 10:
        return {
            "status": "stable",
            "status_label": "稳定",
            "weight_factor": 1,
            "included_in_total": True,
        }
    if sample_count >= 5:
        return {
            "status": "ready",
            "status_label": "可诊断",
            "weight_factor": 1,
            "included_in_total": True,
        }
    if sample_count >= 3:
        return {
            "status": "trend",
            "status_label": "初步观察",
            "weight_factor": 0.5,
            "included_in_total": True,
        }
    return {
        "status": "insufficient",
        "status_label": "样本不足",
        "weight_factor": 0,
        "included_in_total": False,
    }


def geo_scene_surface_score(scene_code, rates):
    mention_rate = rates["mention_rate"]
    recommendation_rate = rates["recommendation_rate"]
    high_risk_rate = rates["high_risk_rate"]
    unverified_rate = rates["unverified_rate"]
    drift_rate = rates["drift_rate"]
    competitor_rate = rates["competitor_rate"]
    if scene_code == "vendor_selection":
        return clamp_geo_score(mention_rate * 40 + recommendation_rate * 60)
    if scene_code == "brand_named_check":
        return clamp_geo_score(
            mention_rate * 20
            + (1 - unverified_rate) * 25
            + (1 - drift_rate) * 25
            + (1 - high_risk_rate) * 30
        )
    if scene_code == "competitor_compare":
        return clamp_geo_score(
            mention_rate * 55
            + recommendation_rate * 20
            + min(competitor_rate, 1) * 10
            + (1 - drift_rate) * 15
        )
    if scene_code == "budget_case_process":
        return clamp_geo_score(
            mention_rate * 30
            + recommendation_rate * 15
            + (1 - unverified_rate) * 30
            + (1 - high_risk_rate) * 25
        )
    if scene_code == "risk_fact_check":
        return clamp_geo_score(
            mention_rate * 15
            + (1 - high_risk_rate) * 45
            + (1 - unverified_rate) * 30
            + (1 - drift_rate) * 10
        )
    return clamp_geo_score(
        mention_rate * 60
        + recommendation_rate * 25
        + (1 - competitor_rate) * 15
    )


def geo_scene_trusted_score(scene_code, surface_score, rates):
    high_risk_rate = rates["high_risk_rate"]
    unverified_rate = rates["unverified_rate"]
    drift_rate = rates["drift_rate"]
    if scene_code == "risk_fact_check":
        penalty = min(high_risk_rate * 0.9 + unverified_rate * 0.35 + drift_rate * 0.2, 0.95)
    elif scene_code in {"brand_named_check", "budget_case_process"}:
        penalty = min(high_risk_rate * 0.8 + unverified_rate * 0.25 + drift_rate * 0.2, 0.9)
    else:
        penalty = min(high_risk_rate * 0.75 + unverified_rate * 0.2 + drift_rate * 0.15, 0.9)
    return clamp_geo_score(surface_score * (1 - penalty))


def geo_scene_summary_text(scene_code, sample_count, rates, trusted_score):
    if sample_count < 3:
        return "该场景样本不足，建议至少补到 3 条，5 条后再作为正式诊断依据。"
    if trusted_score < 40:
        return "可信表现偏弱，优先补事实源、服务页和可引用证据。"
    if rates["high_risk_rate"] >= 0.3:
        return "已出现较多高风险回答，需先处理事实纠偏。"
    if rates["recommendation_rate"] < 0.25 and scene_code == "vendor_selection":
        return "供应商推荐进入率偏低，需强化服务定位和可推荐理由。"
    if rates["mention_rate"] < 0.3 and scene_code != "risk_fact_check":
        return "品牌出现仍偏弱，建议补充可被模型引用的核心内容资产。"
    return "当前场景已有可观察表现，后续可继续补采到 10 条形成稳定基线。"


def build_geo_scene_scores(analysis_rows, total, brand_mentions, brand_recommendations, high_risk_samples):
    rows_by_scene = {item["code"]: [] for item in QUESTION_GENERATION_FOCUS_OPTIONS}
    for raw_row in analysis_rows or []:
        row = {key: raw_row[key] for key in raw_row.keys()} if hasattr(raw_row, "keys") else dict(raw_row)
        scene_code = normalize_geo_scene_code(row.get("generation_focus"), row.get("category"))
        rows_by_scene.setdefault(scene_code, []).append(row)

    scene_scores = []
    for option in QUESTION_GENERATION_FOCUS_OPTIONS:
        scene_code = option["code"]
        rows = rows_by_scene.get(scene_code, [])
        sample_count = len(rows)
        brand_mentioned = sum(1 for row in rows if row.get("brand_mentioned"))
        brand_recommended = sum(1 for row in rows if row.get("brand_recommended"))
        high_risk = sum(
            1
            for row in rows
            if has_json_payload(row.get("high_risk_json")) or "高" in str(row.get("risk_level") or "")
        )
        unverified = sum(1 for row in rows if has_json_payload(row.get("unverified_claims_json")))
        drift = sum(1 for row in rows if has_json_payload(row.get("positioning_drift_json")))
        competitors = sum(1 for row in rows if has_json_payload(row.get("competitors_json")))
        rates = {
            "mention_rate": ratio(brand_mentioned, sample_count),
            "recommendation_rate": ratio(brand_recommended, sample_count),
            "high_risk_rate": ratio(high_risk, sample_count),
            "unverified_rate": ratio(unverified, sample_count),
            "drift_rate": ratio(drift, sample_count),
            "competitor_rate": ratio(competitors, sample_count),
        }
        status_meta = geo_scene_sample_status(sample_count)
        surface_score = geo_scene_surface_score(scene_code, rates) if status_meta["included_in_total"] else None
        trusted_score = (
            geo_scene_trusted_score(scene_code, surface_score, rates)
            if surface_score is not None
            else None
        )
        effective_weight = GEO_SCENE_SCORE_WEIGHTS.get(scene_code, 10) * status_meta["weight_factor"]
        scene_scores.append(
            {
                "code": scene_code,
                "label": option["label"],
                "weight": GEO_SCENE_SCORE_WEIGHTS.get(scene_code, 10),
                "effective_weight": effective_weight,
                "sample_count": sample_count,
                "status": status_meta["status"],
                "status_label": status_meta["status_label"],
                "included_in_total": status_meta["included_in_total"],
                "surface_score": surface_score,
                "trusted_score": trusted_score,
                "brand_mentions": brand_mentioned,
                "brand_recommendations": brand_recommended,
                "high_risk_samples": high_risk,
                "unverified_samples": unverified,
                "positioning_drift_samples": drift,
                "competitor_samples": competitors,
                "brand_mention_rate": rates["mention_rate"],
                "brand_recommendation_rate": rates["recommendation_rate"],
                "high_risk_rate": rates["high_risk_rate"],
                "summary_text": geo_scene_summary_text(scene_code, sample_count, rates, trusted_score or 0),
            }
        )

    eligible = [
        row
        for row in scene_scores
        if row["included_in_total"] and row["effective_weight"] > 0 and row["surface_score"] is not None
    ]
    if eligible:
        weight_total = sum(row["effective_weight"] for row in eligible)
        surface_geo_score = clamp_geo_score(
            sum(row["surface_score"] * row["effective_weight"] for row in eligible) / weight_total
        )
        trusted_geo_score = clamp_geo_score(
            sum(row["trusted_score"] * row["effective_weight"] for row in eligible) / weight_total
        )
        score_basis = "scene_weighted"
    else:
        surface_geo_score = clamp_geo_score(ratio(brand_mentions, total) * 70 + ratio(brand_recommendations, total) * 30)
        trusted_geo_score = clamp_geo_score(surface_geo_score * (1 - ratio(high_risk_samples, total) * 0.75))
        score_basis = "overall_fallback"

    return {
        "surface_geo_score": surface_geo_score,
        "trusted_geo_score": trusted_geo_score,
        "score_basis": score_basis,
        "score_eligible_scene_count": len(eligible),
        "score_insufficient_scene_count": sum(1 for row in scene_scores if row["status"] == "insufficient"),
        "scene_score_breakdown": scene_scores,
    }


def make_id(prefix: str):
    return f"{prefix}_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:6]}"


def safe_db_token(value, fallback="item"):
    token = re.sub(r"[^0-9A-Za-z_]+", "_", str(value or "").strip()).strip("_")
    return token[:64] or fallback


class PlainTextHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self.ignored_depth = 0

    def handle_starttag(self, tag, attrs):
        if tag.lower() in {"script", "style", "noscript", "svg"}:
            self.ignored_depth += 1
        elif not self.ignored_depth and tag.lower() in {"p", "div", "li", "br", "h1", "h2", "h3", "h4", "tr"}:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag.lower() in {"script", "style", "noscript", "svg"} and self.ignored_depth:
            self.ignored_depth -= 1
        elif not self.ignored_depth and tag.lower() in {"p", "div", "li", "h1", "h2", "h3", "h4", "tr"}:
            self.parts.append("\n")

    def handle_data(self, data):
        if not self.ignored_depth:
            self.parts.append(data)

    def text(self):
        return normalize_source_text(" ".join(self.parts))


class NoRedirectHandler(urllib_request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def normalize_source_text(value):
    text = str(value or "").replace("\x00", " ").replace("\r\n", "\n").replace("\r", "\n")
    lines = [re.sub(r"[\t \u3000]+", " ", line).strip() for line in text.split("\n")]
    return "\n".join(line for line in lines if line).strip()


def safe_source_filename(value):
    name = Path(str(value or "source")).name.strip() or "source"
    name = re.sub(r"[<>:\"/\\|?*\x00-\x1f]+", "_", name).strip(" .")
    return name[:180] or "source"


def relative_root_path(path):
    return path.resolve().relative_to(ROOT.resolve()).as_posix()


def source_document_directory(customer_id, document_id):
    return CUSTOMER_SOURCE_ROOT / safe_db_token(customer_id) / safe_db_token(document_id)


def split_source_blocks(blocks, max_chars=8000):
    result = []
    for block in blocks:
        location = str(block.get("location") or "正文").strip()
        text = normalize_source_text(block.get("text"))
        if not text:
            continue
        if len(text) <= max_chars:
            result.append({"location": location, "text": text})
            continue
        parts = [text[index:index + max_chars] for index in range(0, len(text), max_chars)]
        for index, part in enumerate(parts, start=1):
            result.append({"location": f"{location}（片段 {index}/{len(parts)}）", "text": part})
    return result


def parse_customer_source_file(path, extension):
    extension = extension.lower()
    blocks = []
    if extension == ".pdf":
        try:
            from pypdf import PdfReader
        except ImportError as exc:
            raise ValueError("缺少 PDF 解析依赖 pypdf，请按部署说明安装后重试。") from exc
        reader = PdfReader(str(path))
        for index, page in enumerate(reader.pages, start=1):
            blocks.append({"location": f"第 {index} 页", "text": page.extract_text() or ""})
    elif extension == ".pptx":
        try:
            from pptx import Presentation
        except ImportError as exc:
            raise ValueError("缺少 PPTX 解析依赖 python-pptx，请按部署说明安装后重试。") from exc
        presentation = Presentation(str(path))
        for index, slide in enumerate(presentation.slides, start=1):
            texts = []
            for shape in slide.shapes:
                if getattr(shape, "has_text_frame", False):
                    texts.extend(paragraph.text for paragraph in shape.text_frame.paragraphs if paragraph.text.strip())
                if getattr(shape, "has_table", False):
                    for row in shape.table.rows:
                        texts.append(" | ".join(cell.text.strip() for cell in row.cells if cell.text.strip()))
            blocks.append({"location": f"第 {index} 张幻灯片", "text": "\n".join(texts)})
    elif extension == ".docx":
        try:
            from docx import Document
        except ImportError as exc:
            raise ValueError("缺少 DOCX 解析依赖 python-docx，请按部署说明安装后重试。") from exc
        document = Document(str(path))
        for index, paragraph in enumerate(document.paragraphs, start=1):
            if paragraph.text.strip():
                blocks.append({"location": f"段落 {index}", "text": paragraph.text})
        for table_index, table in enumerate(document.tables, start=1):
            table_lines = []
            for row in table.rows:
                table_lines.append(" | ".join(cell.text.strip() for cell in row.cells if cell.text.strip()))
            blocks.append({"location": f"表格 {table_index}", "text": "\n".join(table_lines)})
    elif extension in {".html", ".htm"}:
        parser = PlainTextHTMLParser()
        parser.feed(path.read_text(encoding="utf-8", errors="replace"))
        blocks = [{"location": "网页正文", "text": parser.text()}]
    elif extension in {".md", ".txt"}:
        blocks = [{"location": "正文", "text": path.read_text(encoding="utf-8-sig", errors="replace")}]
    else:
        raise ValueError("暂不支持该文件格式；旧版 DOC/PPT 请先转换为 DOCX/PPTX。")
    blocks = split_source_blocks(blocks)
    extracted_chars = sum(len(item["text"]) for item in blocks)
    warnings = []
    if extracted_chars < 80:
        warnings.append("可提取文字过少，可能是扫描件或图片型资料；v1 暂不做 OCR，请补充文字版。")
    return {"blocks": blocks, "extracted_chars": extracted_chars, "warnings": warnings}


class PublicSourceSecurityError(ValueError):
    pass


class PublicSourceFetchError(ValueError):
    def __init__(self, message, category="fetch_failed", http_status=0):
        super().__init__(message)
        self.category = category
        self.http_status = int(http_status or 0)


def source_fake_ip_compat_enabled():
    """Detect Clash-style Fake-IP DNS without weakening normal private-address checks."""
    mode = str(os.environ.get("GEO_AGENT_SOURCE_FAKE_IP_COMPAT", "auto") or "auto").strip().lower()
    if mode in {"1", "true", "yes", "on", "allow", "enabled"}:
        return True
    if mode in {"0", "false", "no", "off", "deny", "disabled"}:
        return False
    global SOURCE_FAKE_IP_MODE_CACHE
    with SOURCE_FAKE_IP_MODE_LOCK:
        if SOURCE_FAKE_IP_MODE_CACHE is not None:
            return SOURCE_FAKE_IP_MODE_CACHE
        fake_ip_hosts = 0
        for hostname in SOURCE_FAKE_IP_PROBE_HOSTS:
            try:
                addresses = socket.getaddrinfo(hostname, 443, type=socket.SOCK_STREAM)
                resolved = {
                    ipaddress.ip_address(address[4][0].split("%", 1)[0])
                    for address in addresses
                }
            except (socket.gaierror, ValueError):
                continue
            if resolved and all(ip in SOURCE_FAKE_IP_NETWORK for ip in resolved):
                fake_ip_hosts += 1
        SOURCE_FAKE_IP_MODE_CACHE = fake_ip_hosts == len(SOURCE_FAKE_IP_PROBE_HOSTS)
        return SOURCE_FAKE_IP_MODE_CACHE


def validate_public_source_url(value):
    url = str(value or "").strip()
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"} or not parsed.hostname:
        raise PublicSourceSecurityError("网页地址必须是完整的 HTTP/HTTPS 公网 URL。")
    if parsed.username or parsed.password:
        raise PublicSourceSecurityError("网页地址不能包含账号密码。")
    hostname = parsed.hostname.strip().lower()
    if parsed.port and parsed.port not in {80, 443}:
        raise PublicSourceSecurityError("公开信源仅允许使用 HTTP/HTTPS 标准端口。")
    if hostname in {"localhost", "localhost.localdomain"} or hostname.endswith((".local", ".lan", ".internal", ".home.arpa")):
        raise PublicSourceSecurityError("禁止访问本机或内网地址。")
    try:
        direct_ip = ipaddress.ip_address(hostname.split("%", 1)[0])
    except ValueError:
        direct_ip = None
    if direct_ip is not None:
        raise PublicSourceSecurityError("公开信源必须使用域名，不能直接使用 IP 地址。")
    try:
        addresses = socket.getaddrinfo(hostname, parsed.port or (443 if parsed.scheme == "https" else 80), type=socket.SOCK_STREAM)
    except socket.gaierror as exc:
        raise PublicSourceFetchError("网页域名无法解析。", "fetch_failed") from exc
    fake_ip_compat = source_fake_ip_compat_enabled()
    for address in addresses:
        ip = ipaddress.ip_address(address[4][0].split("%", 1)[0])
        if fake_ip_compat and ip in SOURCE_FAKE_IP_NETWORK:
            continue
        if not ip.is_global:
            raise PublicSourceSecurityError("禁止访问本机、内网、链路本地或保留地址。")
    return url


def public_source_access_barrier_reason(url, text=""):
    parsed = urlparse(str(url or ""))
    hostname = str(parsed.hostname or "").lower()
    path = str(parsed.path or "").lower()
    barrier_hosts = ("wappass.", "passport.", "captcha.", "accounts.")
    barrier_path = re.search(r"(?:^|/)(?:captcha|login|signin|sign-in|auth|sso|verify)(?:/|$)", path)
    if hostname.startswith(barrier_hosts) or barrier_path:
        return "页面跳转到了登录、验证码或访问验证入口，不能作为公开信源。"
    normalized = normalize_source_text(text).casefold()
    barrier_phrases = (
        "安全验证", "人机验证", "请完成验证", "拖动滑块", "访问过于频繁",
        "登录后查看", "登录后继续", "verify you are human", "sign in to continue",
    )
    if normalized and any(phrase.casefold() in normalized[:6000] for phrase in barrier_phrases):
        return "页面正文是登录、验证码或访问验证提示，不能作为公开信源。"
    return ""


def fetch_public_source_url(value):
    requested_url = validate_public_source_url(value)
    current_url = requested_url
    redirect_chain = []
    opener = urllib_request.build_opener(NoRedirectHandler())
    for _ in range(4):
        request = urllib_request.Request(
            current_url,
            headers={"User-Agent": "GEO-Agent-Source-Verifier/1.0", "Accept": "text/html,application/pdf,text/plain;q=0.9"},
        )
        try:
            response = opener.open(request, timeout=20)
        except urllib_error.HTTPError as exc:
            if exc.code in {301, 302, 303, 307, 308}:
                location = exc.headers.get("Location", "")
                if not location:
                    raise PublicSourceFetchError("网页重定向缺少目标地址。", "fetch_failed", exc.code) from exc
                next_url = validate_public_source_url(urljoin(current_url, location))
                redirect_chain.append(next_url)
                current_url = next_url
                continue
            category = (
                "unavailable" if exc.code in {404, 410}
                else "restricted" if exc.code in {401, 403, 407, 429}
                else "fetch_failed"
            )
            raise PublicSourceFetchError(f"网页读取失败：HTTP {exc.code}", category, exc.code) from exc
        except (urllib_error.URLError, socket.timeout, TimeoutError) as exc:
            raise PublicSourceFetchError("网页连接超时或网络暂时不可用。", "fetch_failed") from exc
        content_type = response.headers.get_content_type()
        if content_type not in {"text/html", "text/plain", "application/xhtml+xml", "application/pdf"}:
            raise PublicSourceFetchError(f"网页内容类型不支持：{content_type}", "unsupported")
        declared_length = int(response.headers.get("Content-Length") or 0)
        if declared_length > CUSTOMER_SOURCE_MAX_URL_BYTES:
            raise PublicSourceFetchError("网页正文超过 5MB 限制。", "unsupported")
        raw = response.read(CUSTOMER_SOURCE_MAX_URL_BYTES + 1)
        if len(raw) > CUSTOMER_SOURCE_MAX_URL_BYTES:
            raise PublicSourceFetchError("网页正文超过 5MB 限制。", "unsupported")
        if content_type == "application/pdf":
            try:
                from pypdf import PdfReader
            except ImportError as exc:
                raise PublicSourceFetchError("缺少 PDF 解析依赖 pypdf，请按部署说明安装后重试。", "unsupported") from exc
            try:
                reader = PdfReader(io.BytesIO(raw))
                text = normalize_source_text("\n".join((page.extract_text() or "") for page in reader.pages[:80]))
            except Exception as exc:
                raise PublicSourceFetchError("PDF 页面无法提取可核验文字。", "unsupported") from exc
        else:
            charset = response.headers.get_content_charset() or "utf-8"
            text = raw.decode(charset, errors="replace")
        if content_type in {"text/html", "application/xhtml+xml"}:
            parser = PlainTextHTMLParser()
            parser.feed(text)
            text = parser.text()
        elif content_type != "application/pdf":
            text = normalize_source_text(text)
        final_url = response.geturl() or current_url
        barrier_reason = public_source_access_barrier_reason(final_url, text)
        if barrier_reason:
            raise PublicSourceFetchError(barrier_reason, "restricted")
        requested_domain = source_domain(requested_url)
        final_domain = source_domain(final_url)
        return {
            "url": final_url,
            "requested_url": requested_url,
            "final_url": final_url,
            "redirect_chain": redirect_chain,
            "redirect_count": len(redirect_chain),
            "redirected_across_domain": bool(requested_domain and final_domain and requested_domain != final_domain),
            "text": text,
            "content_type": content_type,
            "raw_bytes": raw,
        }
    raise PublicSourceFetchError("网页重定向次数过多。", "fetch_failed")


def write_source_extraction(document_dir, extraction):
    path = document_dir / "extracted.json"
    path.write_text(json.dumps(extraction, ensure_ascii=False, indent=2), encoding="utf-8")
    return path


def source_document_public_payload(row):
    item = db_row_to_dict(row)
    item.pop("storage_path", None)
    item.pop("extracted_path", None)
    item["download_available"] = item.get("source_type") == "file"
    return item


def db_customer_source_documents_payload(customer_id):
    customer_id = unquote(str(customer_id or "").strip())
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        customer = conn.execute("SELECT customer_id FROM customers WHERE customer_id = ?", (customer_id,)).fetchone()
        if not customer:
            return None
        rows = conn.execute(
            "SELECT * FROM customer_source_documents WHERE customer_id = ? ORDER BY created_at DESC",
            (customer_id,),
        ).fetchall()
    return {"customer_id": customer_id, "items": [source_document_public_payload(row) for row in rows]}


def db_create_customer_source_file(customer_id, filename, content_type, raw_bytes, batch_id=""):
    customer_id = unquote(str(customer_id or "").strip())
    filename = safe_source_filename(filename)
    extension = Path(filename).suffix.lower()
    if extension in {".doc", ".ppt"}:
        raise ValueError("旧版 DOC/PPT 暂不支持，请转换为 DOCX/PPTX 后上传。")
    if extension not in CUSTOMER_SOURCE_ALLOWED_EXTENSIONS:
        raise ValueError("仅支持 PDF、PPTX、DOCX、MD、TXT 和 HTML。")
    if not raw_bytes:
        raise ValueError("上传文件为空。")
    if len(raw_bytes) > CUSTOMER_SOURCE_MAX_FILE_BYTES:
        raise ValueError("单个文件不能超过 20MB。")
    batch_id = safe_db_token(batch_id or make_id("upload"))
    digest = hashlib.sha256(raw_bytes).hexdigest()
    timestamp = now_iso()
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        if not conn.execute("SELECT 1 FROM customers WHERE customer_id = ?", (customer_id,)).fetchone():
            raise ValueError("客户不存在。")
        duplicate = conn.execute(
            "SELECT * FROM customer_source_documents WHERE customer_id = ? AND sha256 = ?",
            (customer_id, digest),
        ).fetchone()
        if duplicate:
            payload = source_document_public_payload(duplicate)
            payload["duplicate"] = True
            return payload
        batch = conn.execute(
            "SELECT COUNT(*) AS file_count, COALESCE(SUM(byte_size), 0) AS total_bytes FROM customer_source_documents WHERE customer_id = ? AND batch_id = ?",
            (customer_id, batch_id),
        ).fetchone()
        if int(batch["file_count"] or 0) >= CUSTOMER_SOURCE_MAX_BATCH_FILES:
            raise ValueError("单批最多上传 10 个文件。")
        if int(batch["total_bytes"] or 0) + len(raw_bytes) > CUSTOMER_SOURCE_MAX_BATCH_BYTES:
            raise ValueError("单批文件总大小不能超过 100MB。")
        document_id = make_id("src")
        document_dir = source_document_directory(customer_id, document_id)
        document_dir.mkdir(parents=True, exist_ok=False)
        original_path = document_dir / filename
        original_path.write_bytes(raw_bytes)
        parse_status = "ready"
        parse_warning = ""
        extracted_path = document_dir / "extracted.json"
        extracted_chars = 0
        try:
            extraction = parse_customer_source_file(original_path, extension)
            extracted_chars = extraction["extracted_chars"]
            parse_warning = "；".join(extraction["warnings"])
            write_source_extraction(document_dir, extraction)
            if extracted_chars < 80:
                parse_status = "text_insufficient"
        except Exception as exc:
            parse_status = "failed"
            parse_warning = truncate_text(mask_secret_text(str(exc)), 800)
            write_source_extraction(document_dir, {"blocks": [], "extracted_chars": 0, "warnings": [parse_warning]})
        conn.execute(
            """
            INSERT INTO customer_source_documents (
              document_id, customer_id, source_type, display_name, mime_type,
              file_extension, byte_size, sha256, storage_path, extracted_path,
              source_url, batch_id, parse_status, parse_warning, extracted_chars,
              created_at, updated_at
            ) VALUES (?, ?, 'file', ?, ?, ?, ?, ?, ?, ?, '', ?, ?, ?, ?, ?, ?)
            """,
            (
                document_id, customer_id, filename, str(content_type or mimetypes.guess_type(filename)[0] or "application/octet-stream"),
                extension, len(raw_bytes), digest, relative_root_path(original_path), relative_root_path(extracted_path),
                batch_id, parse_status, parse_warning, extracted_chars, timestamp, timestamp,
            ),
        )
        row = conn.execute("SELECT * FROM customer_source_documents WHERE document_id = ?", (document_id,)).fetchone()
    return source_document_public_payload(row)


def db_create_customer_source_url(customer_id, payload):
    customer_id = unquote(str(customer_id or "").strip())
    fetched = fetch_public_source_url(payload.get("url"))
    text = normalize_source_text(fetched["text"])
    if not text:
        raise ValueError("网页没有提取到可用正文。")
    digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
    timestamp = now_iso()
    document_id = make_id("srcurl")
    batch_id = safe_db_token(payload.get("batch_id") or make_id("urlbatch"))
    document_dir = source_document_directory(customer_id, document_id)
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        if not conn.execute("SELECT 1 FROM customers WHERE customer_id = ?", (customer_id,)).fetchone():
            raise ValueError("客户不存在。")
        duplicate = conn.execute(
            "SELECT * FROM customer_source_documents WHERE customer_id = ? AND sha256 = ?",
            (customer_id, digest),
        ).fetchone()
        if duplicate:
            duplicate_payload = source_document_public_payload(duplicate)
            duplicate_payload["duplicate"] = True
            return duplicate_payload
        batch = conn.execute(
            "SELECT COUNT(*) AS source_count, COALESCE(SUM(byte_size), 0) AS total_bytes FROM customer_source_documents WHERE customer_id = ? AND batch_id = ?",
            (customer_id, batch_id),
        ).fetchone()
        if int(batch["source_count"] or 0) >= CUSTOMER_SOURCE_MAX_BATCH_FILES:
            raise ValueError("单批最多导入 10 个网页。")
        if int(batch["total_bytes"] or 0) + len(fetched["raw_bytes"]) > CUSTOMER_SOURCE_MAX_BATCH_BYTES:
            raise ValueError("单批网页正文总大小不能超过 100MB。")
        document_dir.mkdir(parents=True, exist_ok=False)
        extraction = {"blocks": split_source_blocks([{"location": "网页正文", "text": text}]), "extracted_chars": len(text), "warnings": []}
        extracted_path = write_source_extraction(document_dir, extraction)
        display_name = safe_source_filename(payload.get("name") or urlparse(fetched["url"]).hostname or "网页资料")
        conn.execute(
            """
            INSERT INTO customer_source_documents (
              document_id, customer_id, source_type, display_name, mime_type,
              file_extension, byte_size, sha256, storage_path, extracted_path,
              source_url, batch_id, parse_status, parse_warning, extracted_chars,
              created_at, updated_at
            ) VALUES (?, ?, 'url', ?, ?, '.html', ?, ?, '', ?, ?, ?, 'ready', '', ?, ?, ?)
            """,
            (
                document_id, customer_id, display_name, fetched["content_type"], len(fetched["raw_bytes"]), digest,
                relative_root_path(extracted_path), fetched["url"], batch_id, len(text), timestamp, timestamp,
            ),
        )
        row = conn.execute("SELECT * FROM customer_source_documents WHERE document_id = ?", (document_id,)).fetchone()
    return source_document_public_payload(row)


def db_customer_source_download(customer_id, document_id):
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        row = conn.execute(
            "SELECT * FROM customer_source_documents WHERE customer_id = ? AND document_id = ?",
            (unquote(customer_id), unquote(document_id)),
        ).fetchone()
    if not row or row["source_type"] != "file" or not row["storage_path"]:
        return None
    path = (ROOT / row["storage_path"]).resolve()
    path.relative_to(CUSTOMER_SOURCE_ROOT.resolve())
    if not path.is_file():
        return None
    return {"path": path, "filename": row["display_name"], "content_type": row["mime_type"] or "application/octet-stream"}


def db_delete_customer_source_document(customer_id, document_id):
    customer_id = unquote(str(customer_id or "").strip())
    document_id = unquote(str(document_id or "").strip())
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        row = conn.execute(
            "SELECT * FROM customer_source_documents WHERE customer_id = ? AND document_id = ?",
            (customer_id, document_id),
        ).fetchone()
        if not row:
            return None
        referenced = conn.execute(
            "SELECT COUNT(*) FROM customer_knowledge_import_runs WHERE customer_id = ? AND document_ids_json LIKE ?",
            (customer_id, f'%"{document_id}"%'),
        ).fetchone()[0]
        if referenced:
            raise ValueError("该资料已被建档任务引用，为保留证据链不能删除。")
        conn.execute("DELETE FROM customer_source_documents WHERE document_id = ?", (document_id,))
    document_dir = source_document_directory(customer_id, document_id).resolve()
    document_dir.relative_to(CUSTOMER_SOURCE_ROOT.resolve())
    if document_dir.is_dir():
        shutil.rmtree(document_dir)
    return {"ok": True, "document_id": document_id}


def canonical_source_url(value):
    url = str(value or "").strip()
    if not url:
        return ""
    if url.startswith("source://"):
        return url
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"} or not parsed.hostname:
        return url
    hostname = parsed.hostname.lower()
    port = parsed.port
    default_port = (parsed.scheme.lower() == "http" and port == 80) or (parsed.scheme.lower() == "https" and port == 443)
    netloc = hostname if not port or default_port else f"{hostname}:{port}"
    query = []
    for key, item in parse_qsl(parsed.query, keep_blank_values=True):
        normalized_key = key.casefold()
        if normalized_key.startswith("utm_") or normalized_key in SOURCE_TRACKING_QUERY_KEYS:
            continue
        query.append((key, item))
    return parsed._replace(
        scheme=parsed.scheme.lower(),
        netloc=netloc,
        path=parsed.path or "/",
        query=urlencode(sorted(query)),
        fragment="",
    ).geturl()


def source_domain(value):
    url = str(value or "").strip()
    if url.startswith("source://"):
        return "客户资料"
    return str(urlparse(url).hostname or "").lower()


def infer_source_type(url, title=""):
    domain = source_domain(url)
    text = f"{domain} {title}".casefold()
    if domain == "客户资料":
        return "customer_supplied"
    if domain.endswith(".gov.cn") or ".gov." in domain or any(token in domain for token in ("samr.gov.cn", "std.samr.gov.cn")):
        return "government_standard"
    if any(token in text for token in ("新华", "人民网", "央视", "财新", "界面新闻", "36kr", "钛媒体")):
        return "industry_media"
    if any(token in domain for token in ("zhihu.com", "baidu.com", "douyin.com", "toutiao.com", "weibo.com")):
        return "commercial_platform"
    return "community_other"


def source_keywords(*values):
    text = " ".join(normalize_source_text(value) for value in values if value)
    stop_words = {"什么", "哪些", "怎么", "如何", "是否", "可以", "需要", "目前", "一个", "这个", "进行", "企业", "公司"}
    result = set()
    for token in re.findall(r"[A-Za-z0-9][A-Za-z0-9._+-]{2,}|[\u4e00-\u9fff]{2,}", text):
        normalized = token.casefold()
        if normalized in stop_words:
            continue
        if re.fullmatch(r"[\u4e00-\u9fff]+", token) and len(token) > 6:
            for size in (4, 3, 2):
                for index in range(0, len(token) - size + 1, max(1, size - 1)):
                    piece = token[index:index + size]
                    if piece not in stop_words:
                        result.add(piece)
        else:
            result.add(normalized)
    return sorted(result, key=lambda item: (-len(item), item))[:40]


def best_source_excerpt(text, *contexts, max_chars=520):
    normalized = normalize_source_text(text)
    if not normalized:
        return ""
    keywords = source_keywords(*contexts)
    segments = [item.strip() for item in re.split(r"\n+|(?<=[。！？；!?])", normalized) if item.strip()]
    best = ""
    best_score = 0
    for index, segment in enumerate(segments):
        lowered = segment.casefold()
        score = sum(min(8, len(keyword)) for keyword in keywords if keyword.casefold() in lowered)
        if score > best_score:
            best_score = score
            best = " ".join(segments[index:index + 2])
    if not best_score:
        return ""
    return truncate_text(best, max_chars)


def source_evidence_public_payload(row):
    item = db_row_to_dict(row) if not isinstance(row, dict) else dict(row)
    if not item:
        return None
    raw_metadata = item.get("metadata", item.get("metadata_json", {}))
    if isinstance(raw_metadata, dict):
        metadata = raw_metadata
    else:
        try:
            metadata = json.loads(str(raw_metadata or "{}"))
        except (TypeError, ValueError):
            metadata = {}
    fetch_error = truncate_text(mask_secret_text(str(metadata.get("fetch_error") or "")), 500)
    match_error = truncate_text(mask_secret_text(str(metadata.get("match_error") or "")), 500)
    if (
        item.get("verification_status") == "unavailable"
        and "禁止访问本机、内网、链路本地或保留地址" in fetch_error
    ):
        item["verification_status"] = "blocked"
        item["fetch_status"] = "blocked"
        fetch_error = "此前被本机网络安全规则拦截；当前已支持代理 Fake-IP，请重新核验。"
    item["status_detail"] = fetch_error or match_error
    item["source_type_label"] = {
        "official": "官方来源",
        "government_standard": "政府/标准",
        "industry_media": "行业媒体",
        "commercial_platform": "商业平台",
        "community_other": "社区/其他",
        "customer_supplied": "客户资料",
    }.get(item.get("source_type"), "社区/其他")
    item["origin_label"] = {
        "model_citation": "模型原始引用",
        "independent_web": "独立公开信源",
        "customer_document": "客户资料依据",
        "manual_url": "指定公开网址",
    }.get(item.get("origin"), "其他来源")
    item["relation_label"] = {
        "supports": "支持结论",
        "contradicts": "与结论矛盾",
        "context": "背景信息",
        "unverified": "尚未判断",
    }.get(item.get("relation"), "尚未判断")
    item["verification_status_label"] = {
        "raw": "未经独立核验",
        "matched": "待人工确认",
        "confirmed": "已确认",
        "rejected": "已驳回",
        "unavailable": "网页不存在",
        "conflict": "已确认矛盾",
        "blocked": "网络策略拦截",
        "restricted": "访问受限",
        "fetch_failed": "读取失败",
        "unsupported": "格式不支持",
    }.get(item.get("verification_status"), "待核验")
    return item


def source_verification_run_payload(row):
    item = db_row_to_dict(row) if not isinstance(row, dict) else dict(row)
    if not item:
        return None
    item["total_questions"] = int(item.get("total_questions") or 0)
    item["completed_questions"] = int(item.get("completed_questions") or 0)
    item["failed_questions"] = int(item.get("failed_questions") or 0)
    work_items = item.get("work_items") or []
    counted_items = [work for work in work_items if "usable_count" in work]
    item["result_counts_available"] = bool(counted_items)
    item["usable_sources"] = sum(int(work.get("usable_count") or 0) for work in counted_items)
    item["questions_without_usable_sources"] = sum(
        1
        for work in counted_items
        if work.get("status") == "completed" and int(work.get("usable_count") or 0) <= 0
    )
    return item


def latest_project_source_contexts(conn, project_id):
    rows = conn.execute(
        """
        SELECT
          s.project_id, s.sample_id, s.question_id, s.answer_text, s.citations_json, s.collected_at,
          q.question, q.category,
          pq.generation_focus, pq.generation_focus_label,
          ar.brand_mentioned, ar.brand_recommended, ar.risk_level,
          ar.competitors_json, ar.high_risk_json, ar.recommended_fix
        FROM samples s
        JOIN question_pool q ON q.question_id = s.question_id
        LEFT JOIN project_questions pq ON pq.project_id = s.project_id AND pq.question_id = s.question_id
        LEFT JOIN analysis_results ar ON ar.sample_id = s.sample_id
        WHERE s.project_id = ? AND s.sample_type = 'real'
        ORDER BY s.collected_at DESC, s.sample_id DESC
        """,
        (project_id,),
    ).fetchall()
    contexts = {}
    for row in rows:
        item = db_row_to_dict(row)
        question_id = str(item.get("question_id") or "")
        if question_id and question_id not in contexts:
            contexts[question_id] = item
    report_question_ids = set()
    for row in conn.execute(
        "SELECT report_json FROM report_drafts WHERE project_id = ? UNION ALL SELECT report_json FROM report_versions WHERE project_id = ? AND status IN ('published', 'superseded')",
        (project_id, project_id),
    ).fetchall():
        report = decode_json_field(row["report_json"], {})
        for evidence in report.get("evidence") or []:
            if isinstance(evidence, dict) and evidence.get("questionId"):
                report_question_ids.add(str(evidence["questionId"]))
    for question_id, item in contexts.items():
        reasons = []
        score = 0
        if item.get("brand_mentioned") in (0, False):
            reasons.append("品牌未出现")
            score += 40
        competitors = item.get("competitors") if isinstance(item.get("competitors"), list) else []
        if competitors:
            reasons.append("竞品压制")
            score += 30
        high_risk = item.get("high_risk") if isinstance(item.get("high_risk"), list) else []
        if high_risk or "高" in str(item.get("risk_level") or ""):
            reasons.append("事实风险")
            score += 35
        if question_id in report_question_ids:
            reasons.append("报告代表证据")
            score += 20
        if item.get("citations"):
            reasons.append("已有模型引用")
            score += 8
        item["priority_reasons"] = reasons or ["常规核验"]
        item["priority_score"] = score
    return contexts


def synthetic_model_citations(contexts, stored_keys):
    rows = []
    for question_id, context in contexts.items():
        sample_id = str(context.get("sample_id") or "")
        for index, citation in enumerate(context.get("citations") or []):
            citation = {"title": str(citation)} if isinstance(citation, str) else (citation or {})
            url = str(citation.get("url") or citation.get("source_url") or "").strip()
            title = str(citation.get("title") or citation.get("name") or url or "模型引用").strip()
            canonical = canonical_source_url(url)
            if not canonical or (question_id, sample_id, canonical) in stored_keys:
                continue
            raw_id = "raw_" + hashlib.sha256(f"{question_id}|{sample_id}|{canonical}".encode("utf-8")).hexdigest()[:20]
            rows.append(source_evidence_public_payload({
                "source_evidence_id": raw_id,
                "project_id": context.get("project_id", ""),
                "verification_run_id": "",
                "sample_id": sample_id,
                "question_id": question_id,
                "question": context.get("question", question_id),
                "scene_id": context.get("generation_focus", ""),
                "scene_label": context.get("generation_focus_label", ""),
                "origin": "model_citation",
                "title": title,
                "url": url,
                "canonical_url": canonical,
                "domain": source_domain(url),
                "source_type": infer_source_type(url, title),
                "relation": "unverified",
                "claim_text": "",
                "excerpt": str(citation.get("snippet") or "")[:520],
                "source_location": "",
                "verification_status": "raw",
                "fetch_status": "not_checked",
                "retrieved_at": context.get("collected_at", ""),
                "created_at": context.get("collected_at", ""),
                "updated_at": context.get("collected_at", ""),
                "synthetic": True,
            }))
    return rows


def db_project_source_evidence_payload(project_id, query=None):
    project_id = unquote(str(project_id or "").strip())
    query = query or {}
    with db_connect() as conn:
        ensure_source_evidence_tables(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        contexts = latest_project_source_contexts(conn, project_id)
        stored_rows = conn.execute(
            """
            SELECT se.*, q.question, pq.generation_focus AS scene_id,
                   pq.generation_focus_label AS scene_label
            FROM source_evidence se
            JOIN question_pool q ON q.question_id = se.question_id
            LEFT JOIN project_questions pq ON pq.project_id = se.project_id AND pq.question_id = se.question_id
            WHERE se.project_id = ?
            ORDER BY se.updated_at DESC, se.created_at DESC
            """,
            (project_id,),
        ).fetchall()
        stored = [source_evidence_public_payload(row) for row in stored_rows]
        stored_keys = {
            (str(item.get("question_id") or ""), str(item.get("sample_id") or ""), str(item.get("canonical_url") or ""))
            for item in stored if item.get("origin") == "model_citation"
        }
        raw_rows = synthetic_model_citations(contexts, stored_keys)
        all_rows = stored + raw_rows
        confirmed_counts = {}
        for item in stored:
            if item.get("verification_status") == "confirmed":
                question_id = str(item.get("question_id") or "")
                confirmed_counts[question_id] = confirmed_counts.get(question_id, 0) + 1

    status = str((query.get("status") or [""])[0] or "").strip()
    origin = str((query.get("origin") or [""])[0] or "").strip()
    source_type = str((query.get("source_type") or [""])[0] or "").strip()
    question_id = str((query.get("question_id") or [""])[0] or "").strip()
    scene = str((query.get("scene") or [""])[0] or "").strip()
    domain = str((query.get("domain") or [""])[0] or "").strip().casefold()

    def matches(item):
        item_status = str(item.get("verification_status") or "")
        if status == "pending" and item_status not in {"raw", "matched"}:
            return False
        if status == "invalid" and item_status not in {"unavailable", "conflict", "blocked", "restricted", "fetch_failed", "unsupported"}:
            return False
        if status and status not in {"pending", "invalid"} and item_status != status:
            return False
        return not (
            (origin and item.get("origin") != origin)
            or (source_type and item.get("source_type") != source_type)
            or (question_id and item.get("question_id") != question_id)
            or (scene and item.get("scene_id") != scene)
            or (domain and domain not in str(item.get("domain") or "").casefold())
        )

    recommended = []
    for item in sorted(contexts.values(), key=lambda row: (-int(row.get("priority_score") or 0), str(row.get("question_id") or ""))):
        recommended.append({
            "question_id": item.get("question_id"),
            "question": item.get("question"),
            "sample_id": item.get("sample_id"),
            "scene_id": item.get("generation_focus", ""),
            "scene_label": item.get("generation_focus_label", ""),
            "priority_reasons": item.get("priority_reasons", []),
            "confirmed_source_count": confirmed_counts.get(str(item.get("question_id") or ""), 0),
            "citation_count": len(item.get("citations") or []),
        })
    stats = {
        "pending": sum(1 for item in all_rows if item.get("verification_status") in {"raw", "matched"}),
        "confirmed": sum(1 for item in all_rows if item.get("verification_status") == "confirmed"),
        "raw": sum(1 for item in all_rows if item.get("origin") == "model_citation" and item.get("verification_status") == "raw"),
        "invalid_or_conflict": sum(
            1 for item in all_rows
            if item.get("verification_status") in {"unavailable", "conflict", "blocked", "restricted", "fetch_failed", "unsupported"}
        ),
    }
    return {
        "ok": True,
        "project": project,
        "stats": stats,
        "items": [item for item in all_rows if matches(item)],
        "recommended_questions": recommended[:60],
        "source": "sqlite",
    }


def db_project_source_verification_runs_payload(project_id, query=None):
    project_id = unquote(str(project_id or "").strip())
    limit = parse_bounded_int(((query or {}).get("limit") or [20])[0], default=20, minimum=1, maximum=100)
    with db_connect() as conn:
        ensure_source_evidence_tables(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        rows = conn.execute(
            "SELECT * FROM source_verification_runs WHERE project_id = ? ORDER BY created_at DESC LIMIT ?",
            (project_id, limit),
        ).fetchall()
    return {"ok": True, "project": project, "runs": [source_verification_run_payload(row) for row in rows], "source": "sqlite"}


def db_create_source_verification_run(project_id, payload, username=""):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    question_ids = []
    for item in payload.get("question_ids") or []:
        question_id = str(item or "").strip()
        if question_id and question_id not in question_ids:
            question_ids.append(question_id)
    if not question_ids:
        raise ValueError("请至少选择 1 道需要核验的问题。")
    if len(question_ids) > SOURCE_VERIFICATION_MAX_QUESTIONS:
        raise ValueError(f"单批最多核验 {SOURCE_VERIFICATION_MAX_QUESTIONS} 道题。")
    config = doubao_api_websearch_config(include_secret=False)
    timestamp = now_iso()
    with db_connect() as conn:
        ensure_source_evidence_tables(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        contexts = latest_project_source_contexts(conn, project_id)
        missing = [question_id for question_id in question_ids if question_id not in contexts]
        if missing:
            raise ValueError("以下问题没有真实样本，暂不能核验：" + "、".join(missing[:8]))
        run_id = make_id("sourcecheck")
        work_items = [
            {"question_id": question_id, "status": "queued", "candidate_count": 0, "error": ""}
            for question_id in question_ids
        ]
        conn.execute(
            """
            INSERT INTO source_verification_runs (
              verification_run_id, project_id, question_ids_json, work_items_json,
              status, total_questions, completed_questions, failed_questions,
              llm_provider, llm_model, last_error, created_by,
              created_at, updated_at, completed_at
            ) VALUES (?, ?, ?, ?, 'queued', ?, 0, 0, ?, ?, '', ?, ?, ?, '')
            """,
            (
                run_id, project_id, json_dump(question_ids), json_dump(work_items), len(question_ids),
                str(config.get("provider") or ""), str(config.get("model") or ""),
                str(username or "")[:120], timestamp, timestamp,
            ),
        )
        row = conn.execute("SELECT * FROM source_verification_runs WHERE verification_run_id = ?", (run_id,)).fetchone()
    return {"ok": True, "run": source_verification_run_payload(row), "source": "sqlite"}


def read_customer_source_blocks(row):
    relative_path = str(row.get("extracted_path") or "").strip()
    if not relative_path:
        return []
    path = (ROOT / relative_path).resolve()
    try:
        path.relative_to(CUSTOMER_SOURCE_ROOT.resolve())
    except ValueError:
        return []
    if not path.is_file():
        return []
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return []
    return payload.get("blocks") if isinstance(payload, dict) and isinstance(payload.get("blocks"), list) else []


def local_customer_source_candidates(conn, project, context):
    customer_id = str(project.get("customer_id") or "")
    facts = conn.execute(
        "SELECT fact_value, evidence_url FROM customer_facts WHERE customer_id = ? AND evidence_url LIKE 'source://%' ORDER BY updated_at DESC",
        (customer_id,),
    ).fetchall()
    candidates = []
    seen_documents = set()
    for fact in facts:
        evidence_url = str(fact["evidence_url"] or "")
        parsed = urlparse(evidence_url)
        document_id = parsed.netloc or parsed.path.lstrip("/")
        if not document_id or document_id in seen_documents:
            continue
        fact_value = str(fact["fact_value"] or "")
        if not best_source_excerpt(fact_value, context.get("question"), context.get("answer_text")):
            continue
        document = conn.execute(
            "SELECT * FROM customer_source_documents WHERE customer_id = ? AND document_id = ?",
            (customer_id, document_id),
        ).fetchone()
        if not document:
            continue
        document_item = db_row_to_dict(document)
        blocks = read_customer_source_blocks(document_item)
        full_text = "\n".join(str(block.get("text") or "") for block in blocks if isinstance(block, dict))
        excerpt = best_source_excerpt(full_text, fact_value, context.get("question"))
        if not excerpt:
            continue
        location = unquote(parsed.fragment or "正文")
        candidates.append({
            "origin": "customer_document",
            "title": str(document_item.get("display_name") or "客户资料"),
            "url": evidence_url,
            "canonical_url": evidence_url,
            "domain": "客户资料",
            "source_type": "customer_supplied",
            "relation": "context",
            "claim_text": fact_value[:800],
            "excerpt": excerpt,
            "source_location": location,
            "verification_status": "matched",
            "fetch_status": "local",
            "content_hash": hashlib.sha256(full_text.encode("utf-8")).hexdigest(),
            "metadata": {"document_id": document_id},
        })
        seen_documents.add(document_id)
        if len(candidates) >= 2:
            break
    return candidates


def upsert_source_evidence(conn, project_id, run_id, context, candidate):
    origin = str(candidate.get("origin") or "independent_web")
    if origin not in SOURCE_ORIGINS:
        origin = "independent_web"
    canonical = str(candidate.get("canonical_url") or canonical_source_url(candidate.get("url"))).strip()
    if not canonical:
        return None
    timestamp = now_iso()
    evidence_id = make_id("evidence")
    conn.execute(
        """
        INSERT INTO source_evidence (
          source_evidence_id, project_id, verification_run_id, sample_id, question_id,
          origin, title, url, canonical_url, domain, source_type, relation,
          claim_text, excerpt, source_location, verification_status, fetch_status,
          content_hash, retrieved_at, confirmed_by, confirmed_at, rejected_reason,
          metadata_json, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, '', '', '', ?, ?, ?)
        ON CONFLICT(project_id, question_id, sample_id, origin, canonical_url) DO UPDATE SET
          verification_run_id = excluded.verification_run_id,
          title = excluded.title,
          url = excluded.url,
          domain = excluded.domain,
          source_type = CASE WHEN source_evidence.verification_status IN ('confirmed', 'conflict') THEN source_evidence.source_type ELSE excluded.source_type END,
          relation = CASE WHEN source_evidence.verification_status IN ('confirmed', 'conflict') THEN source_evidence.relation ELSE excluded.relation END,
          claim_text = excluded.claim_text,
          excerpt = excluded.excerpt,
          source_location = excluded.source_location,
          verification_status = CASE WHEN source_evidence.verification_status IN ('confirmed', 'rejected', 'conflict') THEN source_evidence.verification_status ELSE excluded.verification_status END,
          fetch_status = excluded.fetch_status,
          content_hash = excluded.content_hash,
          retrieved_at = excluded.retrieved_at,
          metadata_json = excluded.metadata_json,
          updated_at = excluded.updated_at
        """,
        (
            evidence_id, project_id, run_id, str(context.get("sample_id") or ""), str(context.get("question_id") or ""),
            origin, str(candidate.get("title") or candidate.get("url") or "来源")[:500], str(candidate.get("url") or "")[:2000],
            canonical[:2000], str(candidate.get("domain") or source_domain(candidate.get("url")))[:255],
            str(candidate.get("source_type") or infer_source_type(candidate.get("url"), candidate.get("title"))),
            str(candidate.get("relation") or "unverified"), str(candidate.get("claim_text") or "")[:1200],
            str(candidate.get("excerpt") or "")[:2000], str(candidate.get("source_location") or "")[:500],
            str(candidate.get("verification_status") or "matched"), str(candidate.get("fetch_status") or "not_checked"),
            str(candidate.get("content_hash") or "")[:128], str(candidate.get("retrieved_at") or timestamp),
            json_dump(candidate.get("metadata") or {}), timestamp, timestamp,
        ),
    )
    return conn.execute(
        "SELECT * FROM source_evidence WHERE project_id = ? AND question_id = ? AND sample_id = ? AND origin = ? AND canonical_url = ?",
        (project_id, context.get("question_id"), context.get("sample_id") or "", origin, canonical),
    ).fetchone()


def web_source_candidate(citation, origin, context):
    citation = citation if isinstance(citation, dict) else {"title": str(citation or "")}
    url = str(citation.get("url") or citation.get("source_url") or "").strip()
    title = str(citation.get("title") or citation.get("name") or source_domain(url) or "公开来源").strip()
    candidate = {
        "origin": origin,
        "title": title,
        "url": url,
        "canonical_url": canonical_source_url(url),
        "domain": source_domain(url),
        "source_type": infer_source_type(url, title),
        "relation": "unverified",
        "claim_text": str(context.get("answer_text") or "")[:800],
        "excerpt": "",
        "source_location": "",
        "verification_status": "raw",
        "fetch_status": "not_checked",
        "content_hash": "",
        "metadata": {"search_snippet": str(citation.get("snippet") or "")[:520]},
    }
    try:
        fetched = fetch_public_source_url(url)
        excerpt = best_source_excerpt(
            fetched.get("text"), context.get("question"), context.get("answer_text"), citation.get("snippet"),
        )
        candidate.update({
            "url": fetched.get("url") or url,
            "canonical_url": canonical_source_url(fetched.get("url") or url),
            "domain": source_domain(fetched.get("url") or url),
            "excerpt": excerpt,
            "verification_status": "matched" if excerpt else "raw",
            "fetch_status": "accessible",
            "content_hash": hashlib.sha256(str(fetched.get("text") or "").encode("utf-8")).hexdigest(),
            "retrieved_at": now_iso(),
            "metadata": {
                "content_type": fetched.get("content_type", ""),
                "search_snippet": str(citation.get("snippet") or "")[:520],
                "requested_url": fetched.get("requested_url") or url,
                "final_url": fetched.get("final_url") or fetched.get("url") or url,
                "redirect_chain": fetched.get("redirect_chain") or [],
                "redirect_count": int(fetched.get("redirect_count") or 0),
                "redirected_across_domain": bool(fetched.get("redirected_across_domain")),
                "match_error": "" if excerpt else "页面可以访问，但未从页面原文中找到与当前问题或回答匹配的内容。",
            },
        })
    except PublicSourceSecurityError as exc:
        candidate.update({
            "verification_status": "blocked",
            "fetch_status": "blocked",
            "metadata": {"fetch_error": truncate_text(mask_secret_text(str(exc)), 500), "error_code": "security_blocked"},
            "retrieved_at": now_iso(),
        })
    except PublicSourceFetchError as exc:
        candidate.update({
            "verification_status": exc.category,
            "fetch_status": exc.category,
            "metadata": {
                "fetch_error": truncate_text(mask_secret_text(str(exc)), 500),
                "error_code": exc.category,
                "http_status": exc.http_status,
            },
            "retrieved_at": now_iso(),
        })
    except Exception as exc:
        candidate.update({
            "verification_status": "fetch_failed",
            "fetch_status": "fetch_failed",
            "metadata": {"fetch_error": truncate_text(mask_secret_text(str(exc)), 500), "error_code": "unexpected_fetch_error"},
            "retrieved_at": now_iso(),
        })
    return candidate


def source_verification_search_prompt(context):
    return (
        "请针对下面这道 GEO 监测问题查找可公开访问、可直接核对原文的资料。"
        "优先官方页面、政府或标准文件、行业媒体和具体产品/服务说明；不要编造来源。\n\n"
        f"问题：{context.get('question') or context.get('question_id')}\n"
        f"当前回答片段：{truncate_text(context.get('answer_text') or '', 1000)}\n"
        "请简要说明可核验事实，并通过联网搜索返回最相关的公开链接。"
    )


def update_source_verification_run(conn, run_id, work_items, last_error=""):
    completed = sum(1 for item in work_items if item.get("status") == "completed")
    failed = sum(1 for item in work_items if item.get("status") == "failed")
    pending = sum(1 for item in work_items if item.get("status") in {"queued", "running"})
    current = conn.execute("SELECT status FROM source_verification_runs WHERE verification_run_id = ?", (run_id,)).fetchone()
    current_status = str(current["status"] or "queued") if current else "queued"
    if current_status == "stopped":
        status = "stopped"
    elif pending:
        status = "running"
    elif failed:
        status = "partial_failed"
    else:
        status = "completed"
    timestamp = now_iso()
    conn.execute(
        """
        UPDATE source_verification_runs
        SET work_items_json = ?, status = ?, completed_questions = ?, failed_questions = ?,
            last_error = ?, updated_at = ?, completed_at = ?
        WHERE verification_run_id = ?
        """,
        (
            json_dump(work_items), status, completed, failed, str(last_error or "")[:1000], timestamp,
            timestamp if status in {"completed", "partial_failed"} else "", run_id,
        ),
    )
    return conn.execute("SELECT * FROM source_verification_runs WHERE verification_run_id = ?", (run_id,)).fetchone()


def db_run_next_source_verification(project_id, run_id):
    project_id = unquote(str(project_id or "").strip())
    run_id = unquote(str(run_id or "").strip())
    with SOURCE_VERIFICATION_LOCK:
        with db_connect() as conn:
            ensure_source_evidence_tables(conn)
            project = db_project_detail(conn, project_id)
            row = conn.execute(
                "SELECT * FROM source_verification_runs WHERE project_id = ? AND verification_run_id = ?",
                (project_id, run_id),
            ).fetchone()
            if not project or not row:
                return None
            run = source_verification_run_payload(row)
            if run.get("status") == "stopped":
                raise ValueError("核验任务已停止，请先继续任务。")
            work_items = run.get("work_items") or []
            if any(item.get("status") == "running" for item in work_items):
                raise ValueError("当前已有问题正在核验，请稍后刷新。")
            next_item = next((item for item in work_items if item.get("status") == "queued"), None)
            if not next_item:
                completed_row = update_source_verification_run(conn, run_id, work_items)
                return {"ok": True, "done": True, "run": source_verification_run_payload(completed_row), "source": "sqlite"}
            next_item["status"] = "running"
            next_item["error"] = ""
            conn.execute(
                "UPDATE source_verification_runs SET work_items_json = ?, status = 'running', updated_at = ? WHERE verification_run_id = ?",
                (json_dump(work_items), now_iso(), run_id),
            )
            context = latest_project_source_contexts(conn, project_id).get(str(next_item.get("question_id") or ""))
            if not context:
                next_item["status"] = "failed"
                next_item["error"] = "真实样本已不存在。"
                failed_row = update_source_verification_run(conn, run_id, work_items, next_item["error"])
                return {"ok": False, "done": False, "run": source_verification_run_payload(failed_row), "error": next_item["error"], "source": "sqlite"}

    candidates = []
    error_message = ""
    try:
        config = doubao_api_websearch_config(include_secret=True)
        if not config.get("configured"):
            raise ValueError("豆包联网采样配置不完整，暂不能开始公开信源核验。")
        search_result, _retry_meta = call_with_ark_retry(
            lambda: call_doubao_api_websearch(source_verification_search_prompt(context), config)
        )
        seen = set()
        independent = []
        for citation in search_result.get("citations") or []:
            canonical = canonical_source_url((citation or {}).get("url") if isinstance(citation, dict) else "")
            if canonical and canonical not in seen:
                independent.append(citation)
                seen.add(canonical)
        raw = []
        for citation in context.get("citations") or []:
            citation_dict = citation if isinstance(citation, dict) else {"title": str(citation)}
            canonical = canonical_source_url(citation_dict.get("url"))
            if canonical and canonical not in seen:
                raw.append(citation_dict)
                seen.add(canonical)
        for citation in independent[:3]:
            candidates.append(web_source_candidate(citation, "independent_web", context))
        for citation in raw[: max(0, SOURCE_VERIFICATION_MAX_CANDIDATES - len(candidates))]:
            candidates.append(web_source_candidate(citation, "model_citation", context))
        with db_connect() as conn:
            project = db_project_detail(conn, project_id)
            local_candidates = local_customer_source_candidates(conn, project, context)
        for candidate in local_candidates:
            if len(candidates) >= SOURCE_VERIFICATION_MAX_CANDIDATES:
                break
            candidates.append(candidate)
        if not candidates:
            raise ValueError("联网搜索未返回可核验的候选来源。")
    except Exception as exc:
        error_message = truncate_text(mask_secret_text(str(exc)), 1000)

    with db_connect() as conn:
        ensure_source_evidence_tables(conn)
        saved_items = []
        if not error_message:
            for candidate in candidates[:SOURCE_VERIFICATION_MAX_CANDIDATES]:
                saved = upsert_source_evidence(conn, project_id, run_id, context, candidate)
                if saved:
                    saved_items.append(source_evidence_public_payload(saved))
        row = conn.execute(
            "SELECT * FROM source_verification_runs WHERE project_id = ? AND verification_run_id = ?",
            (project_id, run_id),
        ).fetchone()
        if not row:
            return None
        run = source_verification_run_payload(row)
        work_items = run.get("work_items") or []
        item = next((entry for entry in work_items if entry.get("question_id") == context.get("question_id")), None)
        if item:
            item["status"] = "failed" if error_message else "completed"
            item["candidate_count"] = len(saved_items)
            item["usable_count"] = sum(
                1
                for saved in saved_items
                if saved.get("fetch_status") in {"accessible", "local"}
                and str(saved.get("excerpt") or "").strip()
            )
            item["error"] = error_message
        updated = update_source_verification_run(conn, run_id, work_items, error_message)
    return {
        "ok": not error_message,
        "done": not any(item.get("status") == "queued" for item in (source_verification_run_payload(updated).get("work_items") or [])),
        "run": source_verification_run_payload(updated),
        "question_id": context.get("question_id"),
        "items": saved_items,
        "error": error_message,
        "source": "sqlite",
    }


def db_control_source_verification_run(project_id, run_id, action):
    project_id = unquote(str(project_id or "").strip())
    run_id = unquote(str(run_id or "").strip())
    with db_connect() as conn:
        ensure_source_evidence_tables(conn)
        row = conn.execute(
            "SELECT * FROM source_verification_runs WHERE project_id = ? AND verification_run_id = ?",
            (project_id, run_id),
        ).fetchone()
        if not row:
            return None
        run = source_verification_run_payload(row)
        work_items = run.get("work_items") or []
        timestamp = now_iso()
        if action == "stop":
            if any(item.get("status") == "running" for item in work_items):
                raise ValueError("当前题目正在核验，请等待本题结束后再停止。")
            conn.execute("UPDATE source_verification_runs SET status = 'stopped', updated_at = ? WHERE verification_run_id = ?", (timestamp, run_id))
        elif action == "resume":
            if not any(item.get("status") == "queued" for item in work_items):
                raise ValueError("当前任务没有待继续的问题。")
            conn.execute("UPDATE source_verification_runs SET status = 'queued', completed_at = '', updated_at = ? WHERE verification_run_id = ?", (timestamp, run_id))
        elif action == "retry-failed":
            failed = [item for item in work_items if item.get("status") == "failed"]
            if not failed:
                raise ValueError("当前任务没有失败问题。")
            for item in failed:
                item.update({"status": "queued", "error": "", "candidate_count": 0})
                item.pop("usable_count", None)
            conn.execute(
                "UPDATE source_verification_runs SET work_items_json = ?, status = 'queued', failed_questions = 0, last_error = '', completed_at = '', updated_at = ? WHERE verification_run_id = ?",
                (json_dump(work_items), timestamp, run_id),
            )
        else:
            raise ValueError("未知的核验任务操作。")
        updated = conn.execute("SELECT * FROM source_verification_runs WHERE verification_run_id = ?", (run_id,)).fetchone()
    return {"ok": True, "run": source_verification_run_payload(updated), "source": "sqlite"}


def db_add_manual_source_evidence(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    question_id = str(payload.get("question_id") or "").strip()
    if not question_id:
        raise ValueError("请先选择对应问题。")
    fetched = fetch_public_source_url(payload.get("url"))
    with db_connect() as conn:
        ensure_source_evidence_tables(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        context = latest_project_source_contexts(conn, project_id).get(question_id)
        if not context:
            raise ValueError("该问题没有真实样本，暂不能补充信源。")
        claim_text = str(payload.get("claim_text") or context.get("answer_text") or "")
        excerpt = best_source_excerpt(fetched.get("text"), context.get("question"), claim_text)
        if not excerpt:
            raise ValueError("指定网页正文未匹配到当前问题或结论，请检查网址或改用更具体的页面。")
        candidate = {
            "origin": "manual_url",
            "title": str(payload.get("title") or source_domain(fetched.get("url")) or "指定公开网址"),
            "url": fetched.get("url"),
            "source_type": str(payload.get("source_type") or infer_source_type(fetched.get("url"))),
            "relation": str(payload.get("relation") or "unverified"),
            "claim_text": claim_text,
            "excerpt": excerpt,
            "verification_status": "matched",
            "fetch_status": "accessible",
            "content_hash": hashlib.sha256(str(fetched.get("text") or "").encode("utf-8")).hexdigest(),
            "retrieved_at": now_iso(),
            "metadata": {
                "content_type": fetched.get("content_type", ""),
                "requested_url": fetched.get("requested_url") or payload.get("url"),
                "final_url": fetched.get("final_url") or fetched.get("url"),
                "redirect_chain": fetched.get("redirect_chain") or [],
                "redirect_count": int(fetched.get("redirect_count") or 0),
                "redirected_across_domain": bool(fetched.get("redirected_across_domain")),
            },
        }
        saved = upsert_source_evidence(conn, project_id, "", context, candidate)
    return {"ok": True, "item": source_evidence_public_payload(saved), "source": "sqlite"}


def db_retry_source_evidence(project_id, evidence_id):
    project_id = unquote(str(project_id or "").strip())
    evidence_id = unquote(str(evidence_id or "").strip())
    with db_connect() as conn:
        ensure_source_evidence_tables(conn)
        row = conn.execute(
            "SELECT * FROM source_evidence WHERE project_id = ? AND source_evidence_id = ?",
            (project_id, evidence_id),
        ).fetchone()
        if not row:
            return None
        item = db_row_to_dict(row)
        if item.get("verification_status") in {"confirmed", "rejected", "conflict"}:
            raise ValueError("已人工处理的信源不能直接重新核验。")
        if item.get("origin") == "customer_document" or not str(item.get("url") or "").startswith(("http://", "https://")):
            raise ValueError("该记录不是可重新读取的公开网页。")
        context = latest_project_source_contexts(conn, project_id).get(str(item.get("question_id") or ""))
        if not context:
            raise ValueError("该问题没有真实样本，暂不能重新核验。")
    candidate = web_source_candidate(
        {"url": item.get("url"), "title": item.get("title"), "snippet": item.get("excerpt")},
        str(item.get("origin") or "independent_web"),
        context,
    )
    with db_connect() as conn:
        saved = upsert_source_evidence(conn, project_id, str(item.get("verification_run_id") or ""), context, candidate)
    return {"ok": True, "item": source_evidence_public_payload(saved), "source": "sqlite"}


def db_decide_source_evidence(project_id, evidence_id, payload, username=""):
    project_id = unquote(str(project_id or "").strip())
    evidence_id = unquote(str(evidence_id or "").strip())
    payload = payload or {}
    decision = str(payload.get("decision") or "").strip()
    if decision not in {"confirm", "reject"}:
        raise ValueError("核验决定必须为确认或驳回。")
    relation = str(payload.get("relation") or "context").strip()
    source_type = str(payload.get("source_type") or "community_other").strip()
    if relation not in SOURCE_RELATIONS:
        raise ValueError("来源与结论的关系无效。")
    if source_type not in SOURCE_TYPES:
        raise ValueError("来源类型无效。")
    timestamp = now_iso()
    with db_connect() as conn:
        ensure_source_evidence_tables(conn)
        row = conn.execute(
            "SELECT * FROM source_evidence WHERE project_id = ? AND source_evidence_id = ?",
            (project_id, evidence_id),
        ).fetchone()
        if not row:
            return None
        item = db_row_to_dict(row)
        if decision == "confirm":
            if item.get("fetch_status") not in {"accessible", "local"} or not str(item.get("excerpt") or "").strip():
                raise ValueError("来源尚未完成原文读取和摘录匹配，不能确认。")
            next_status = "conflict" if relation == "contradicts" else "confirmed"
            conn.execute(
                """
                UPDATE source_evidence
                SET verification_status = ?, relation = ?, source_type = ?,
                    confirmed_by = ?, confirmed_at = ?, rejected_reason = '', updated_at = ?
                WHERE source_evidence_id = ?
                """,
                (next_status, relation, source_type, str(username or "")[:120], timestamp, timestamp, evidence_id),
            )
        else:
            conn.execute(
                """
                UPDATE source_evidence
                SET verification_status = 'rejected', relation = ?, source_type = ?,
                    rejected_reason = ?, confirmed_by = '', confirmed_at = '', updated_at = ?
                WHERE source_evidence_id = ?
                """,
                (relation, source_type, str(payload.get("reason") or "人工驳回")[:800], timestamp, evidence_id),
            )
        updated = conn.execute("SELECT * FROM source_evidence WHERE source_evidence_id = ?", (evidence_id,)).fetchone()
    return {"ok": True, "item": source_evidence_public_payload(updated), "source": "sqlite"}


def action_task_state_payload(row):
    if not row:
        return {}
    item = db_row_to_dict(row)
    item["status"] = normalize_action_task_status(item.get("status"))
    owner = item.get("owner", "")
    if "?" in owner and owner.startswith("GEO"):
        owner = "GEO项目负责人"
    return {
        "status": item.get("status", "todo"),
        "owner": owner,
        "execution_note": item.get("execution_note", ""),
        "evidence_url": item.get("evidence_url", ""),
        "retest_status": item.get("retest_status", "not_ready"),
        "started_at": item.get("started_at", ""),
        "blocked_reason": item.get("blocked_reason", ""),
        "due_date": item.get("due_date", ""),
        "completed_at": item.get("completed_at", ""),
    }


def existing_action_task_states(conn, project_id):
    ensure_action_workbench_fields(conn)
    rows = conn.execute(
        """
        SELECT *
        FROM action_tasks
        WHERE project_id = ?
        """,
        (project_id,),
    ).fetchall()
    by_id = {}
    by_title = {}
    for row in rows:
        payload = action_task_state_payload(row)
        action_task_id = row["action_task_id"]
        title = str(row["title"] or "").strip()
