def merge_generated_task_drafts(existing_plan, generated_plan, generated_drafts):
    existing_plan = existing_plan if isinstance(existing_plan, dict) else {}
    generated_plan = generated_plan if isinstance(generated_plan, dict) else {}
    existing_tasks = existing_plan.get("tasks") if isinstance(existing_plan.get("tasks"), list) else []
    existing_by_id = {
        str(item.get("draft_id") or ""): item
        for item in existing_tasks
        if isinstance(item, dict) and str(item.get("draft_id") or "")
    }
    merged = []
    seen = set()
    for draft in generated_drafts:
        draft_id = str(draft.get("draft_id") or "")
        existing = existing_by_id.get(draft_id)
        if existing and (
            str(existing.get("status") or "") == "approved"
            or existing.get("linked_action_task_id")
            or existing.get("edited_by_human")
        ):
            merged.append(existing)
        else:
            merged.append(draft)
        seen.add(draft_id)
    for existing in existing_tasks:
        if not isinstance(existing, dict):
            continue
        draft_id = str(existing.get("draft_id") or "")
        if draft_id and draft_id not in seen:
            merged.append(existing)
    plan = {**existing_plan, **generated_plan}
    plan["tasks"] = merged
    plan.setdefault("task_center_version", 1)
    return plan


def decorate_action_task(row):
    task = db_row_to_dict(row)
    status_meta = action_task_status_meta(task.get("status"))
    task["status"] = status_meta["status"]
    task["status_label"] = status_meta["label"]
    task["status_class"] = status_meta["class"]
    if "?" in str(task.get("owner", "")) and str(task.get("owner", "")).startswith("GEO"):
        task["owner"] = "GEO项目负责人"
    task["retest_ready"] = task["status"] == "done" or task.get("retest_status") == "ready"
    return task


def action_workbench_summary(action_tasks):
    counts = {"todo": 0, "doing": 0, "done": 0, "blocked": 0}
    ready_for_retest = 0
    for task in action_tasks:
        status = normalize_action_task_status(task.get("status"))
        counts[status] += 1
        if status == "done" or task.get("retest_status") == "ready":
            ready_for_retest += 1
    total = len(action_tasks)
    if not total:
        stage = "待生成任务"
        next_action = "先完成采样和分析。"
    elif counts["todo"]:
        stage = "待优化"
        next_action = "先推进 P0/P1 优化任务。"
    elif counts["doing"] or counts["blocked"]:
        stage = "执行中"
        next_action = "更新执行记录，处理暂缓任务。"
    else:
        stage = "可复测"
        next_action = "创建优化后复测批次，验证指标变化。"
    return {
        "total": total,
        "todo": counts["todo"],
        "doing": counts["doing"],
        "done": counts["done"],
        "blocked": counts["blocked"],
        "ready_for_retest": ready_for_retest,
        "stage": stage,
        "next_action": next_action,
    }


def split_text_lines(value):
    return [line.strip() for line in str(value or "").splitlines() if line.strip()]


FACT_LIST_AGGREGATE_KEYS = {
    ("service", "confirmed_services"),
    ("allowed_claim", "allowed_claims"),
}


def normalize_fact_line_identity(value):
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold()


def unique_fact_value_lines(value):
    lines = []
    seen = set()
    for raw_line in str(value or "").splitlines():
        line = raw_line.strip()
        identity = normalize_fact_line_identity(line)
        if not identity or identity in seen:
            continue
        seen.add(identity)
        lines.append(line)
    return lines


def normalize_fact_value_identity(value):
    return "\n".join(
        normalize_fact_line_identity(line)
        for line in str(value or "").splitlines()
        if normalize_fact_line_identity(line)
    )


def normalize_fact_list_value(value):
    return "\n".join(unique_fact_value_lines(value))


def split_record_line(line, expected_parts=3):
    parts = [part.strip() for part in re.split(r"\s*[|｜]\s*", line.strip())]
    parts = parts[:expected_parts]
    while len(parts) < expected_parts:
        parts.append("")
    return parts


def parse_aliases(value):
    return [
        item.strip()
        for item in re.split(r"[、,，/]+", str(value or ""))
        if item.strip()
    ]


