def normalize_monitoring_samplers(values, default=None):
    if isinstance(values, str):
        values = [values]
    normalized = []
    for value in values or default or [DOUBAO_API_WEBSEARCH_SAMPLER]:
        sampler = str(value or "").strip()
        if sampler in WEBSEARCH_SAMPLERS and sampler not in normalized:
            normalized.append(sampler)
    if not normalized:
        normalized = [DOUBAO_API_WEBSEARCH_SAMPLER]
    return normalized[: len(WEBSEARCH_SAMPLER_DEFINITIONS)]


def safe_websearch_config_snapshot(sampler, config=None):
    config = dict(config or websearch_api_config(sampler, include_secret=False))
    allowed_fields = (
        "sampler",
        "provider",
        "endpoint",
        "model",
        "web_search",
        "temperature",
        "timeout_seconds",
        "formula_uri",
        "reasoning_effort",
        "max_tokens",
        "max_search_uses",
        "forced_search",
        "search_strategy",
    )
    return {
        field: config.get(field)
        for field in allowed_fields
        if field in config and config.get(field) is not None
    }


def monitoring_plan_has_completed_baseline(conn, project_id, version):
    row = conn.execute(
        """
        SELECT MAX(sr.completed_at) AS completed_at
        FROM monitoring_cycles mc
        JOIN sample_runs sr
          ON sr.project_id = mc.project_id AND sr.cycle_id = mc.cycle_id
        WHERE mc.project_id = ?
          AND mc.plan_version = ?
          AND mc.purpose = 'baseline'
        GROUP BY mc.cycle_id
        HAVING COUNT(sr.run_id) > 0
          AND SUM(CASE WHEN sr.status NOT IN ('completed', 'partial_failed') THEN 1 ELSE 0 END) = 0
          AND SUM(CASE WHEN EXISTS (
            SELECT 1 FROM samples s
            WHERE s.project_id = sr.project_id
              AND s.run_id = sr.run_id
              AND s.sample_type = 'real'
          ) THEN 0 ELSE 1 END) = 0
        ORDER BY MAX(sr.completed_at) DESC, mc.created_at DESC
        LIMIT 1
        """,
        (project_id, int(version or 1)),
    ).fetchone()
    if row:
        return str(row["completed_at"] or now_iso())
    if int(version or 1) != 1:
        return ""
    row = conn.execute(
        """
        SELECT sr.completed_at
        FROM sample_runs sr
        WHERE sr.project_id = ?
          AND sr.purpose = 'baseline'
          AND sr.status IN ('completed', 'partial_failed')
          AND EXISTS (
            SELECT 1 FROM samples s
            WHERE s.project_id = sr.project_id
              AND s.run_id = sr.run_id
              AND s.sample_type = 'real'
          )
          AND COALESCE(sr.cycle_id, '') = ''
        ORDER BY sr.completed_at DESC, sr.created_at DESC
        LIMIT 1
        """,
        (project_id,),
    ).fetchone()
    return str(row["completed_at"] or now_iso()) if row else ""


def monitoring_plan_for_project(conn, project_id, create=True):
    ensure_sampling_history_fields(conn)
    row = conn.execute(
        "SELECT * FROM project_monitoring_plans WHERE project_id = ?",
        (project_id,),
    ).fetchone()
    if not row and create:
        timestamp = now_iso()
        conn.execute(
            """
            INSERT INTO project_monitoring_plans (
              project_id, primary_sampler, samplers_json, cadence, version,
              baseline_locked_at, created_at, updated_at
            ) VALUES (?, ?, ?, 'manual', 1, '', ?, ?)
            """,
            (
                project_id,
                DOUBAO_API_WEBSEARCH_SAMPLER,
                json_dump([DOUBAO_API_WEBSEARCH_SAMPLER]),
                timestamp,
                timestamp,
            ),
        )
        row = conn.execute(
            "SELECT * FROM project_monitoring_plans WHERE project_id = ?",
            (project_id,),
        ).fetchone()
    plan = db_row_to_dict(row)
    if not plan:
        return None
    plan["samplers"] = normalize_monitoring_samplers(plan.get("samplers"))
    if plan.get("primary_sampler") not in plan["samplers"]:
        plan["primary_sampler"] = plan["samplers"][0]
    version = max(1, int(plan.get("version") or 1))
    if not plan.get("baseline_locked_at"):
        locked_at = monitoring_plan_has_completed_baseline(conn, project_id, version)
        if locked_at:
            conn.execute(
                """
                UPDATE project_monitoring_plans
                SET baseline_locked_at = ?, updated_at = ?
                WHERE project_id = ? AND version = ?
                """,
                (locked_at, now_iso(), project_id, version),
            )
            plan["baseline_locked_at"] = locked_at
    plan["version"] = version
    plan["cadence"] = plan.get("cadence") if plan.get("cadence") in MONITORING_CADENCES else "manual"
    plan["cadence_label"] = MONITORING_CADENCES[plan["cadence"]]
    plan["baseline_required"] = not bool(plan.get("baseline_locked_at"))
    plan["provider_options"] = [
        {
            **public_websearch_api_config(sampler),
            "selected": sampler in plan["samplers"],
            "primary": sampler == plan["primary_sampler"],
        }
        for sampler in WEBSEARCH_SAMPLER_DEFINITIONS
    ]
    return plan


def db_save_project_monitoring_plan(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    payload = dict(payload or {})
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        current = monitoring_plan_for_project(conn, project_id)
        samplers = normalize_monitoring_samplers(
            payload.get("samplers"),
            current.get("samplers"),
        )
        primary_sampler = str(
            payload.get("primary_sampler") or current.get("primary_sampler") or samplers[0]
        ).strip()
        if primary_sampler not in samplers:
            raise ValueError("主平台必须包含在默认监测平台中")
        cadence = str(payload.get("cadence") or current.get("cadence") or "manual").strip()
        if cadence not in MONITORING_CADENCES:
            raise ValueError("监测频率仅支持手动、每周或每月")

        provider_changed = (
            samplers != current.get("samplers")
            or primary_sampler != current.get("primary_sampler")
        )
        requires_new_baseline = bool(provider_changed and current.get("baseline_locked_at"))
        version = int(current.get("version") or 1) + (1 if requires_new_baseline else 0)
        baseline_locked_at = "" if requires_new_baseline else str(current.get("baseline_locked_at") or "")
        timestamp = now_iso()
        conn.execute(
            """
            UPDATE project_monitoring_plans
            SET primary_sampler = ?, samplers_json = ?, cadence = ?, version = ?,
                baseline_locked_at = ?, updated_at = ?
            WHERE project_id = ?
            """,
            (
                primary_sampler,
                json_dump(samplers),
                cadence,
                version,
                baseline_locked_at,
                timestamp,
                project_id,
            ),
        )
        conn.execute(
            "UPDATE projects SET platform = ?, updated_at = ? WHERE project_id = ?",
            (WEBSEARCH_SAMPLER_DEFINITIONS[primary_sampler]["platform"], timestamp, project_id),
        )
        plan = monitoring_plan_for_project(conn, project_id)
        conn.commit()
    return {
        "ok": True,
        "monitoring_plan": plan,
        "requires_new_baseline": requires_new_baseline,
        "message": (
            "监测平台范围已变更，请创建新基线后再进行正式环比。"
            if requires_new_baseline
            else "默认监测方案已保存。"
        ),
        "source": "sqlite",
    }


