def cleanup_report_export_paths(relative_paths):
    root = REPORT_EXPORT_ROOT.resolve()
    removed = 0
    for relative_path in relative_paths or []:
        path = (ROOT / str(relative_path or "")).resolve()
        try:
            path.relative_to(root)
        except ValueError:
            continue
        if path.exists() and path.is_file():
            path.unlink()
            removed += 1
        parent = path.parent
        while parent != root:
            try:
                parent.rmdir()
            except OSError:
                break
            parent = parent.parent
    return removed


def db_in_clause(values):
    rows = [str(value) for value in values if str(value or "").strip()]
    if not rows:
        return "", []
    return ",".join(["?"] * len(rows)), rows


def db_delete_where_in(conn, table_name, column_name, values):
    placeholders, rows = db_in_clause(values)
    if not placeholders:
        return 0
    return db_delete_count(conn, table_name, f"{column_name} IN ({placeholders})", rows)


def db_project_related_ids(conn, project_id):
    run_ids = [
        row["run_id"]
        for row in conn.execute(
            "SELECT run_id FROM sample_runs WHERE project_id = ?",
            (project_id,),
        ).fetchall()
    ]
    recommendation_ids = [
        row["recommendation_id"]
        for row in conn.execute(
            "SELECT recommendation_id FROM recommendations WHERE project_id = ?",
            (project_id,),
        ).fetchall()
    ]
    retest_run_ids = [
        row["retest_run_id"]
        for row in conn.execute(
            "SELECT retest_run_id FROM retest_runs WHERE project_id = ?",
            (project_id,),
        ).fetchall()
    ]
    return {
        "run_ids": run_ids,
        "recommendation_ids": recommendation_ids,
        "retest_run_ids": retest_run_ids,
    }


def db_project_candidate_question_ids(conn, project_id):
    question_ids = set()
    queries = [
        (
            "SELECT question_id FROM project_questions WHERE project_id = ?",
            (project_id,),
        ),
        (
            """
            SELECT st.question_id
            FROM sample_tasks st
            JOIN sample_runs sr ON sr.run_id = st.run_id
            WHERE sr.project_id = ?
            """,
            (project_id,),
        ),
        (
            "SELECT question_id FROM samples WHERE project_id = ?",
            (project_id,),
        ),
        (
            "SELECT question_id FROM analysis_results WHERE project_id = ?",
            (project_id,),
        ),
        (
            "SELECT question_id FROM recommendation_retest_questions WHERE project_id = ?",
            (project_id,),
        ),
        (
            """
            SELECT e.question_id
            FROM recommendation_evidence e
            JOIN recommendations r ON r.recommendation_id = e.recommendation_id
            WHERE r.project_id = ?
            """,
            (project_id,),
        ),
    ]
    for sql, params in queries:
        for row in conn.execute(sql, params).fetchall():
            question_id = str(row["question_id"] or "").strip()
            if question_id:
                question_ids.add(question_id)
    return sorted(question_ids)


def db_question_has_external_refs(conn, question_id, project_id):
    checks = [
        (
            "SELECT 1 FROM project_questions WHERE question_id = ? AND project_id <> ? LIMIT 1",
            (question_id, project_id),
        ),
        (
            """
            SELECT 1
            FROM sample_tasks st
            JOIN sample_runs sr ON sr.run_id = st.run_id
            WHERE st.question_id = ? AND sr.project_id <> ?
            LIMIT 1
            """,
            (question_id, project_id),
        ),
        (
            "SELECT 1 FROM samples WHERE question_id = ? AND project_id <> ? LIMIT 1",
            (question_id, project_id),
        ),
        (
            "SELECT 1 FROM analysis_results WHERE question_id = ? AND project_id <> ? LIMIT 1",
            (question_id, project_id),
        ),
        (
            "SELECT 1 FROM source_evidence WHERE question_id = ? AND project_id <> ? LIMIT 1",
            (question_id, project_id),
        ),
        (
            "SELECT 1 FROM recommendation_retest_questions WHERE question_id = ? AND project_id <> ? LIMIT 1",
            (question_id, project_id),
        ),
        (
            """
            SELECT 1
            FROM recommendation_evidence e
            JOIN recommendations r ON r.recommendation_id = e.recommendation_id
            WHERE e.question_id = ? AND r.project_id <> ?
            LIMIT 1
            """,
            (question_id, project_id),
        ),
    ]
    return any(conn.execute(sql, params).fetchone() for sql, params in checks)


def db_project_orphan_question_ids(conn, project_id):
    return [
        question_id
        for question_id in db_project_candidate_question_ids(conn, project_id)
        if not db_question_has_external_refs(conn, question_id, project_id)
    ]


def backup_database_for_project_delete(project_id):
    DB_FILE.parent.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    safe_project_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(project_id or "project"))
    backup_path = DB_FILE.parent / f"geo_agent.before_delete_project_{safe_project_id}_{timestamp}.db"
    source = sqlite3.connect(DB_FILE)
    target = sqlite3.connect(backup_path)
    try:
        with target:
            source.backup(target)
    finally:
        target.close()
        source.close()
    return backup_path


