def db_project_delete_preview_payload(project_id):
    project_id = unquote(project_id)
    with db_connect() as conn:
        ensure_report_center_tables(conn)
        ensure_sampling_history_fields(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        ids = db_project_related_ids(conn, project_id)
        run_ids = ids["run_ids"]
        recommendation_ids = ids["recommendation_ids"]
        retest_run_ids = ids["retest_run_ids"]
        run_placeholders, run_params = db_in_clause(run_ids)
        rec_placeholders, rec_params = db_in_clause(recommendation_ids)
        retest_placeholders, retest_params = db_in_clause(retest_run_ids)
        counts = {
            "projects": 1,
            "project_monitoring_plans": db_count(conn, "project_monitoring_plans", "project_id = ?", (project_id,)),
            "monitoring_cycles": db_count(conn, "monitoring_cycles", "project_id = ?", (project_id,)),
            "sampling_schedules": db_count(conn, "sampling_schedules", "project_id = ?", (project_id,)),
            "project_questions": db_count(conn, "project_questions", "project_id = ?", (project_id,)),
            "question_pool_orphans": len(db_project_orphan_question_ids(conn, project_id)),
            "sample_runs": db_count(conn, "sample_runs", "project_id = ?", (project_id,)),
            "sample_tasks": db_count(conn, "sample_tasks", f"run_id IN ({run_placeholders})", run_params) if run_placeholders else 0,
            "samples": db_count(conn, "samples", "project_id = ?", (project_id,)),
            "analysis_results": db_count(conn, "analysis_results", "project_id = ?", (project_id,)),
            "recommendations": db_count(conn, "recommendations", "project_id = ?", (project_id,)),
            "recommendation_evidence": db_count(conn, "recommendation_evidence", f"recommendation_id IN ({rec_placeholders})", rec_params) if rec_placeholders else 0,
            "action_tasks": db_count(conn, "action_tasks", "project_id = ?", (project_id,)),
            "recommendation_retest_questions": db_count(conn, "recommendation_retest_questions", "project_id = ?", (project_id,)),
            "retest_runs": db_count(conn, "retest_runs", "project_id = ?", (project_id,)),
            "retest_results": db_count(conn, "retest_results", f"retest_run_id IN ({retest_placeholders})", retest_params) if retest_placeholders else 0,
            "report_versions": db_count(conn, "report_versions", "project_id = ?", (project_id,)),
            "report_drafts": db_count(conn, "report_drafts", "project_id = ?", (project_id,)),
            "frozen_report_pdfs": len(db_project_report_pdf_paths(conn, project_id)),
            "analysis_result_versions": db_count(conn, "analysis_result_versions", "project_id = ?", (project_id,)),
            "sampling_run_snapshots": db_count(conn, "sampling_run_snapshots", "project_id = ?", (project_id,)),
            "question_generation_runs": db_count(conn, "question_generation_runs", "source_project_id = ? OR target_project_id = ?", (project_id, project_id)),
            "source_verification_runs": db_count(conn, "source_verification_runs", "project_id = ?", (project_id,)),
            "source_evidence": db_count(conn, "source_evidence", "project_id = ?", (project_id,)),
        }
    return {
        "project": project,
        "counts": counts,
        "delete_scope": "project_only",
        "preserves": [
            "客户资料",
            "客户事实库",
            "竞品与禁用声明",
            "项目外 _secrets API 配置",
        ],
        "source": "sqlite",
    }


