def db_reset_project_test_data_payload(project_id, payload):
    project_id = unquote(project_id)
    confirm_text = str(payload.get("confirm_text") or payload.get("confirm_project_id") or "").strip()
    with db_connect() as conn:
        preview = db_project_reset_preview_payload(project_id)
        if preview is None:
            return None
        project = preview["project"]
    valid_confirmations = {project_id, str(project.get("name") or "").strip()}
