def db_fictional_demo_project_id(conn):
    row = conn.execute(
        """
        SELECT project_id
        FROM projects
        WHERE project_id = ?
        LIMIT 1
        """,
        (FICTIONAL_DEMO_PROJECT_ID,),
    ).fetchone()
    if row:
        return row["project_id"]
    row = conn.execute(
        """
        SELECT project_id
        FROM projects
        WHERE customer_id = ?
        ORDER BY created_at DESC, project_id DESC
        LIMIT 1
        """,
        (FICTIONAL_DEMO_CUSTOMER_ID,),
    ).fetchone()
    return row["project_id"] if row else ""


