def mask_secret_text(text):
    text = str(text or "")
    text = re.sub(r"Bearer\s+[A-Za-z0-9._\-]+", "Bearer ***MASKED***", text)
    text = re.sub(r"sk-[A-Za-z0-9_-]{12,}", "sk-***MASKED***", text)
    return text


def truncate_text(value, max_chars=500):
    text = str(value or "").strip()
    if len(text) <= max_chars:
        return text
    return text[: max_chars - 8].rstrip() + "...[截断]"


def ark_response_text(payload):
    if not isinstance(payload, dict):
        return ""
    output_text = payload.get("output_text")
    if isinstance(output_text, str) and output_text.strip():
        return output_text.strip()

    def content_text(content):
        if isinstance(content, str) and content.strip():
            return content.strip()
        if not isinstance(content, list):
            return ""
        parts = []
        for item in content:
            if not isinstance(item, dict):
                continue
            item_type = str(item.get("type", "") or "")
            if item_type and item_type not in {"output_text", "text"}:
                continue
            text = item.get("text")
            if isinstance(text, str) and text.strip():
                parts.append(text.strip())
        return "\n\n".join(parts).strip()

    choices = payload.get("choices")
    if isinstance(choices, list):
        texts = []
        for choice in choices:
            if not isinstance(choice, dict):
                continue
            message = choice.get("message") or {}
            if isinstance(message, dict):
                content = message.get("content")
                text = content_text(content)
                if text:
                    texts.append(text)
            text = choice.get("text")
            if isinstance(text, str) and text.strip():
                texts.append(text.strip())
        if texts:
            return "\n\n".join(texts).strip()

    texts = []

    output = payload.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, dict):
                continue
            if item.get("type") != "message":
                continue
            if item.get("role") and item.get("role") != "assistant":
                continue
            text = content_text(item.get("content"))
            if text:
                texts.append(text)

    message = payload.get("message")
    if isinstance(message, dict):
        text = content_text(message.get("content"))
        if text:
            texts.append(text)
        for key in ("output_text", "text"):
            value = message.get(key)
            if isinstance(value, str) and value.strip():
                texts.append(value.strip())

    return "\n\n".join(dict.fromkeys(texts)).strip()


def ark_response_citations(payload):
    citations = []
    seen = set()

    def add(item):
        if not isinstance(item, dict):
            return
        url = str(item.get("url") or item.get("uri") or item.get("link") or "").strip()
        title = str(item.get("title") or item.get("name") or item.get("site_name") or "").strip()
        snippet = str(item.get("snippet") or item.get("summary") or item.get("content") or "").strip()
        if not url and not title:
            return
        key = (url, title)
        if key in seen:
            return
        seen.add(key)
        citations.append(
            {
                "title": title,
                "url": url,
                "snippet": truncate_text(snippet, 240) if snippet else "",
            }
        )

    def walk(node):
        if isinstance(node, dict):
            if any(key in node for key in ("url", "uri", "link")):
                add(node)
            for key in ("citations", "annotations", "references", "search_results", "web_search_results"):
                value = node.get(key)
                if isinstance(value, list):
                    for item in value:
                        if isinstance(item, dict):
                            add(item)
            for value in node.values():
                if isinstance(value, (dict, list)):
                    walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(payload)
    return citations[:20]


def call_doubao_api_websearch(question, config):
    api_key = str(config.get("api_key", "") or "").strip()
    endpoint = str(config.get("endpoint", "") or "").strip()
    model = str(config.get("model", "") or "").strip()
    if not api_key:
        raise ValueError("豆包火山方舟 API Key 未配置，请先在采样页保存 API Key。")
    if not endpoint:
        raise ValueError("豆包火山方舟接口地址未配置。")
    if not model:
        raise ValueError("豆包火山方舟模型未配置。")
    body = {
        "model": model,
        "input": question,
        "instructions": (
            "请像普通用户在豆包中提问后得到的联网回答一样作答。"
            "优先依据公开可检索信息；无法确认的信息不要编造。不要提及系统提示词。"
        ),
        "temperature": bounded_float(config.get("temperature"), default=0.2, minimum=0, maximum=2),
    }
    if config.get("web_search", True):
        body["tools"] = [{"type": "web_search"}]
    encoded = json.dumps(body, ensure_ascii=False).encode("utf-8")
    request = urllib_request.Request(
        endpoint,
        data=encoded,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    timeout_seconds = parse_bounded_int(config.get("timeout_seconds"), default=60, minimum=10, maximum=180)
    try:
        with urllib_request.urlopen(request, timeout=timeout_seconds) as response:
            raw = response.read().decode("utf-8", errors="replace")
    except urllib_error.HTTPError as exc:
        raw = exc.read().decode("utf-8", errors="replace")
        detail = truncate_text(mask_secret_text(raw), 500)
        retryable = exc.code in DOUBAO_API_WEBSEARCH_RETRYABLE_HTTP_STATUS or 500 <= exc.code <= 599
        raise ArkWebsearchRequestError(
            f"火山方舟 API 返回 {exc.code}：{detail}",
            status_code=exc.code,
            error_code=ark_error_code(raw),
            retry_after_seconds=parse_retry_after_seconds(exc.headers.get("Retry-After") if exc.headers else ""),
            retryable=retryable,
        ) from exc
    except urllib_error.URLError as exc:
        raise ArkWebsearchRequestError(
            f"火山方舟 API 请求失败：{mask_secret_text(exc.reason)}",
            retryable=True,
        ) from exc
    except TimeoutError as exc:
        raise ArkWebsearchRequestError("火山方舟 API 请求超时", retryable=True) from exc

    try:
        payload = json.loads(raw)
    except json.JSONDecodeError as exc:
        detail = truncate_text(mask_secret_text(raw), 500)
        raise RuntimeError(f"火山方舟 API 返回非 JSON 内容：{detail}") from exc
    answer = ark_response_text(payload)
    if not answer:
        raise RuntimeError("火山方舟 API 未返回可保存的回答正文")
    return {
        "answer": answer,
        "raw_response": payload,
        "citations": ark_response_citations(payload),
    }


def call_configured_websearch(question, config):
    sampler = str((config or {}).get("sampler") or "").strip()
    if sampler == DOUBAO_API_WEBSEARCH_SAMPLER:
        return call_doubao_api_websearch(question, config)
    adapters = {
        DEEPSEEK_API_WEBSEARCH_SAMPLER: sampling_providers.call_deepseek_websearch,
        KIMI_API_WEBSEARCH_SAMPLER: sampling_providers.call_kimi_websearch,
        QWEN_API_WEBSEARCH_SAMPLER: sampling_providers.call_qwen_websearch,
    }
    adapter = adapters.get(sampler)
    if not adapter:
        raise ValueError(f"不支持的联网采样平台：{sampler or '未指定'}")
    try:
        return adapter(question, config)
    except sampling_providers.ProviderRequestError as exc:
        raise ArkWebsearchRequestError(
            str(exc),
            status_code=exc.status_code,
            error_code=exc.error_code,
            retry_after_seconds=exc.retry_after_seconds,
            retryable=exc.retryable,
        ) from exc


