def compact_llm_analysis(item):
    return {
        "question_id": item.get("question_id", ""),
        "brand_mentioned": bool(item.get("brand_mentioned")),
        "brand_recommended": bool(item.get("brand_recommended")),
        "risk_level": item.get("risk_level", "中"),
        "competitors": item.get("competitors", []),
        "accurate_claims": item.get("accurate_claims", []),
        "unverified_claims": item.get("unverified_claims", []),
        "high_risk_hallucinations": item.get("high_risk_hallucinations", []),
        "positioning_drift": item.get("positioning_drift", []),
        "recommended_fix": item.get("recommended_fix", ""),
    }


def compact_llm_fact_rows(facts):
    aggregate_types = {
        fact_type
        for fact_type, _fact_key in FACT_LIST_AGGREGATE_KEYS
    }
    granular_line_identities = {
        fact_type: set()
        for fact_type in aggregate_types
    }
    for item in facts:
        fact_type = str(item.get("fact_type", "") or "").strip()
        fact_key = str(item.get("fact_key", "") or "").strip()
        if fact_type not in aggregate_types:
            continue
        if (fact_type, fact_key) in FACT_LIST_AGGREGATE_KEYS:
            continue
        granular_line_identities[fact_type].update(
            normalize_fact_line_identity(line)
            for line in unique_fact_value_lines(item.get("fact_value", ""))
        )

    compacted = []
    row_index_by_identity = {}
    for item in facts:
        fact_type = str(item.get("fact_type", "") or "").strip()
        fact_key = str(item.get("fact_key", "") or "").strip()
        fact_value = str(item.get("fact_value", "") or "").strip()
        if (fact_type, fact_key) in FACT_LIST_AGGREGATE_KEYS:
            fact_value = "\n".join(
                line
                for line in unique_fact_value_lines(fact_value)
                if normalize_fact_line_identity(line)
                not in granular_line_identities.get(fact_type, set())
            )
        if not fact_value:
            continue

        identity = (
            fact_type,
            fact_key,
            normalize_fact_value_identity(fact_value),
        )
        existing_index = row_index_by_identity.get(identity)
        if existing_index is not None:
            existing = compacted[existing_index]
            if not existing["confidence"] and item.get("confidence"):
                existing["confidence"] = item.get("confidence", "")
            if not existing["evidence_url"] and item.get("evidence_url"):
                existing["evidence_url"] = item.get("evidence_url", "")
            continue

        row_index_by_identity[identity] = len(compacted)
        compacted.append(
            {
                "fact_type": fact_type,
                "fact_key": fact_key,
                "fact_value": truncate_for_llm(fact_value, 900),
                "confidence": item.get("confidence", ""),
                "evidence_url": item.get("evidence_url", ""),
            }
        )
    return compacted


def build_project_llm_input_package(project, facts, competitors, forbidden_claims, sample_rows, baseline_analyses):
    brand_terms = project_fact_context(project, facts, competitors).get("brand_terms", [])
    fact_rows = compact_llm_fact_rows(facts)
    competitor_rows = [
        {
            "name": item.get("name", ""),
            "category": item.get("category", ""),
            "watch_reason": item.get("watch_reason", ""),
            "aliases": item.get("aliases") or decode_json_field(item.get("aliases_json", "[]"), []),
        }
        for item in competitors
    ]
    forbidden_rows = [
        {
            "claim": item.get("claim", ""),
            "severity": item.get("severity", "high"),
            "reason": item.get("reason", ""),
        }
        for item in forbidden_claims
    ]
    baseline_by_question = {
        item.get("question_id"): compact_llm_analysis(item)
        for item in baseline_analyses
    }
    samples = []
    for sample in sample_rows:
        question_id = sample.get("question_id", "")
        answer_text = sample.get("answer_text", "")
        brand_mentioned = any(term and term in answer_text for term in brand_terms)
        brand_answer_context = extract_context(answer_text, brand_terms) if brand_mentioned else ""
        samples.append(
            {
                "sample_id": sample.get("sample_id", ""),
                "question_id": question_id,
                "question": sample.get("question", ""),
                "category": sample.get("category", ""),
                "intent": sample.get("intent", ""),
                "platform": sample.get("platform", ""),
                "collected_at": sample.get("collected_at", ""),
                "answer_text": truncate_for_llm(answer_text),
                "brand_answer_context": truncate_for_llm(brand_answer_context, 1800),
                "citations": (sample.get("citations") or decode_json_field(sample.get("citations_json", "[]"), []))[:12],
                "rules_baseline": baseline_by_question.get(question_id),
            }
        )

    return {
        "version": LLM_ANALYSIS_BRIDGE_VERSION,
        "project": {
            "project_id": project.get("project_id", ""),
            "project_name": project.get("name", ""),
            "platform": project.get("platform", "豆包"),
            "language": project.get("language", "中文"),
            "goal": project.get("goal", ""),
            "customer_id": project.get("customer_id", ""),
            "customer_name": project.get("customer_name", ""),
            "industry": project.get("customer_industry", ""),
            "region": project.get("customer_region", ""),
            "business_summary": project.get("customer_business_summary", ""),
        },
        "fact_base": {
            "confirmed_facts": fact_rows,
            "competitors": competitor_rows,
            "forbidden_claims": forbidden_rows,
        },
        "samples": samples,
        "counts": {
            "facts": len(fact_rows),
            "competitors": len(competitor_rows),
            "forbidden_claims": len(forbidden_rows),
            "samples": len(samples),
            "rules_baseline": len(baseline_analyses),
        },
    }


def build_project_llm_prompt(input_package, output_schema, batch_context=None):
    package_text = json.dumps(input_package, ensure_ascii=False, indent=2)
    schema_text = json.dumps(output_schema, ensure_ascii=False, indent=2)
    batch_context = batch_context if isinstance(batch_context, dict) else {}
    batch_index = int(batch_context.get("batch_index") or 0)
    batch_count = int(batch_context.get("batch_count") or 0)
    if batch_index > 0 and batch_count > 1:
        batch_notice = (
            f"\n当前是服务端全量复核的第 {batch_index}/{batch_count} 批。"
            "只分析本批输入包中的问题，不要引用、补写或猜测其他批次的问题；"
            "本批 recommendations 输出 1-2 条，服务端会在全部批次结束后离线合并为最多 5 条。\n"
        )
        recommendation_rule = (
            "recommendations 输出 1-2 条本批最重要、可执行的 B 端 GEO 优化建议，"
            "不要为了凑数重复相近建议。"
        )
    else:
        batch_notice = ""
        recommendation_rule = (
            "recommendations 输出 2-5 条，必须是可执行的 B 端 GEO 优化建议，"
            "不要泛泛而谈。"
        )
    return f"""你是一个面向 B 端客户的 GEO 监测优化 Agent。请基于客户事实库、禁用表述、竞品清单、豆包原始回答和规则分析基线，输出结构化分析与优化建议 JSON。
{batch_notice}

分析原则：
1. analyses 必须一一覆盖输入包 samples 中的 question_id；不得新增、改写、合并或遗漏 question_id。
2. 只能依据输入包中的客户事实、原始回答和明确证据判断，不要补充输入包之外的新事实。
3. 区分“品牌被提到”和“品牌被推荐”；只是出现在列表里不一定等于推荐。
4. 对成立时间、地址、资质、客户案例、排名、效果承诺等内容要严格核验；没有事实库证据时放入 unverified_claims 或 required_facts_to_confirm，不要当成事实。
5. 只有当你的分析字段与 rules_baseline 明确冲突时，才写入 quality_checks.conflicts_with_rules；普通提醒、事实缺口或低置信度不要写入冲突。
6. 做客户品牌风险、事实风险、定位偏移归因时，只能使用客户品牌所在的同一列表项、段落或小标题下的文字；其他公司/竞品段落里的“一键生成、批量、模板、低价”等描述不能归到客户名下。若风险词只出现在其他公司段落，positioning_drift、high_risk_hallucinations、unverified_claims 不要记录该词。
7. samples 中的 brand_answer_context 是已按客户段落截出的客户相关原文，判断客户自身风险时优先依据它；evidence_quotes 必须引用客户品牌所在段落的短原文。recommendations 的 evidence/target_questions 只能引用确有客户归因风险的问题，不要把竞品段落风险当作客户优化证据。
8. {recommendation_rule}优先围绕：官网服务页/案例页/FAQ/城市页/竞品对比页/事实源纠偏/第三方内容/结构化摘要/复测问题。
9. 每条 recommendation 必须包含：
   - target_questions：1-5 个输入包内 question_id，只能来自 samples。
   - evidence：优先放 Q 编号；必要时补充短原文证据，不要放不存在的链接或样本。
   - action：一句可直接分配的任务，避免空泛口号。
   - content_brief：80-220 字，说明要建设的页面/段落模块、要覆盖的采购场景、应如何表达差异化。
   - required_facts_to_confirm：需要客户补充或确认的事实；如果无需补充，返回空数组。
   - expected_impact：说明预计改善哪个 GEO 指标，如品牌出现率、推荐率、事实风险、竞品占位或复测可比性。
   - asset_type：从官网与实体信息、产品/服务页、FAQ/采购解释、案例与证明、竞品对比、第三方引用、事实纠偏中选择最匹配的一类。
   - impacted_scenes：填写受影响的四场景名称。
   - deliverables、content_outline、source_strategy、acceptance_criteria：分别说明交付物、内容提纲、引用来源策略和完成标准。
   - retest_plan：说明用哪些 target_questions 复测以及预期观察指标。
   - limitations：说明当前样本和事实边界，不宣称掌握平台私有排序算法。
10. samples 中的 citations 是当前回答的联网引用，可用于判断内容来源策略，但不能把引用网页未明确支持的内容当成客户事实。
11. 不要建议编造案例、资质、排名、客户名单或效果承诺；事实库没有的信息必须要求客户确认后再写。
12. 建议口径统一为“基于当前豆包样本和联网证据”，不要宣称破解、还原或掌握豆包 App 私有排序算法。
13. 输出必须是合法 JSON，不要输出 Markdown、解释段落或多余文本。

输入包：
{package_text}

输出 JSON Schema：
{schema_text}
"""


def project_llm_question_ids(input_package):
    seen = set()
    question_ids = []
    for sample in (input_package or {}).get("samples", []) or []:
        question_id = str(sample.get("question_id") or "").strip()
        if not question_id or question_id in seen:
            continue
        seen.add(question_id)
        question_ids.append(question_id)
    return question_ids


def project_llm_input_fingerprint(input_package):
    normalized = json.dumps(
        input_package if isinstance(input_package, dict) else {},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def project_llm_execution_metadata(input_package, batch_size=ANALYSIS_LLM_BATCH_SIZE):
    batch_size = max(1, int(batch_size or ANALYSIS_LLM_BATCH_SIZE))
    question_count = len(project_llm_question_ids(input_package))
    sample_count = len((input_package or {}).get("samples", []) or [])
    batch_count = math.ceil(question_count / batch_size) if question_count else 0
    return {
        "mode": "sequential_batches",
        "sample_count": sample_count,
        "question_count": question_count,
        "batch_size": batch_size,
        "batch_count": batch_count,
        "estimated_paid_calls": batch_count,
        "automatic_retry": False,
        "resume_supported": True,
        "input_fingerprint": project_llm_input_fingerprint(input_package),
    }


def split_project_llm_input_package(input_package, batch_size=ANALYSIS_LLM_BATCH_SIZE):
    input_package = input_package if isinstance(input_package, dict) else {}
    batch_size = max(1, int(batch_size or ANALYSIS_LLM_BATCH_SIZE))
    samples = input_package.get("samples", []) or []
    question_ids = project_llm_question_ids(input_package)
    batch_count = math.ceil(len(question_ids) / batch_size) if question_ids else 0
    packages = []
    for offset in range(0, len(question_ids), batch_size):
        batch_question_ids = question_ids[offset : offset + batch_size]
        batch_question_set = set(batch_question_ids)
        batch_samples = [
            copy.deepcopy(sample)
            for sample in samples
            if str(sample.get("question_id") or "").strip() in batch_question_set
        ]
        package = copy.deepcopy(input_package)
        package["samples"] = batch_samples
        counts = copy.deepcopy(package.get("counts") or {})
        counts["samples"] = len(batch_samples)
        counts["questions"] = len(batch_question_ids)
        counts["rules_baseline"] = sum(
            1 for sample in batch_samples if sample.get("rules_baseline")
        )
        package["counts"] = counts
        package["batch"] = {
            "batch_index": len(packages) + 1,
            "batch_count": batch_count,
            "question_ids": batch_question_ids,
        }
        packages.append(package)
    return packages


def report_polish_output_schema():
    return {
        "type": "object",
        "required": [
            "executive_summary",
            "key_findings",
            "recommendation_summary",
            "next_actions",
            "caveats",
        ],
        "properties": {
            "executive_summary": {"type": "string"},
            "key_findings": {"type": "array", "items": {"type": "string"}},
            "recommendation_summary": {"type": "string"},
            "next_actions": {"type": "array", "items": {"type": "string"}},
            "caveats": {"type": "array", "items": {"type": "string"}},
        },
    }


REPORT_SECTION_LABELS = {
    "conclusion": "本期诊断结论",
    "metrics": "核心可见度指标",
    "scenes": "四场景诊断",
    "evidence": "问题与回答证据",
    "causes": "不可见或被压制的原因",
    "actions": "内容资产行动方案",
    "retest": "复测与验收标准",
    "appendix": "全量异常证据及方法附录",
}


def report_section_polish_output_schema(section_id=""):
    section_id = str(section_id or "").strip()
    section_id_schema = {"type": "string"}
    section_title_schema = {"type": "string"}
    if section_id in REPORT_SECTION_LABELS:
        section_id_schema.update({
            "enum": [section_id],
            "description": f"必须原样返回 {section_id}",
        })
        section_title_schema["enum"] = [REPORT_SECTION_LABELS[section_id]]
    return {
        "type": "object",
        "required": ["section_id", "section_title", "section_markdown", "change_summary", "caveats"],
        "properties": {
            "section_id": section_id_schema,
            "section_title": section_title_schema,
            "section_markdown": {"type": "string"},
            "change_summary": {"type": "string"},
            "caveats": {"type": "array", "items": {"type": "string"}},
        },
    }


def build_report_section_polish_prompt(project, report_type, section_id, section_markdown, evidence_context):
    section_title = REPORT_SECTION_LABELS[section_id]
    schema_text = json.dumps(report_section_polish_output_schema(section_id), ensure_ascii=False, indent=2)
    context_text = truncate_for_llm(
        json.dumps(evidence_context, ensure_ascii=False, indent=2)
        if isinstance(evidence_context, (dict, list))
        else str(evidence_context or ""),
        10000,
    )
    return f"""你是一个严谨的 B2B GEO 监测顾问。请只润色客户诊断报告中的单个章节，并只输出合法 JSON。

章节：{section_title}（{section_id}）
报告类型：{report_type}
项目：{project.get("name", "")}
客户：{project.get("customer_name", "")}

不可违反的规则：
1. 只能改善表达、结构和可执行性，不得新增事实、案例、排名、资质、地址或效果承诺。
2. 不得修改任何指标数值、百分比、问题 ID、样本状态、竞品名称、引用来源或验收条件。
3. 保留章节原有 Markdown 层级；只返回本章节，不得生成整份报告或其他章节。
4. 客户文本不得出现 Demo、Agent、API Key、Prompt、数据库、内部验证等内部表述。
5. 如果证据不足，明确说明边界，不得推断平台私有排序算法。
6. 输出中的 section_id 必须逐字返回“{section_id}”，section_title 必须逐字返回“{section_title}”。

当前章节 Markdown：
{truncate_for_llm(section_markdown, 10000)}

锁定的数据与证据上下文：
{context_text}

输出 JSON Schema：
{schema_text}
"""


def build_report_polish_prompt(project, report_type, report_markdown):
    type_labels = {
        "internal": "内部老板版：突出项目价值、当前进度、风险判断和下一步动作。",
        "client": "客户交付版：面向客户，突出主要发现、优化建议、落地计划和判断依据；避免内部流程、Demo、Agent、API 等表述。",
        "weekly": "周报版：突出本周进度、风险观察、下周重点和任务安排。",
    }
    schema_text = json.dumps(report_polish_output_schema(), ensure_ascii=False, indent=2)
    markdown_text = truncate_for_llm(report_markdown, 16000)
    return f"""你是一个严谨的 B2B GEO 监测顾问，请基于当前报告 Markdown 润色汇报文案，并只输出合法 JSON。

报告类型：
{type_labels.get(report_type, type_labels["internal"])}

项目上下文：
- 项目：{project.get("name", "")}
- 客户：{project.get("customer_name", "")}
- 行业：{project.get("customer_industry", "")}
- 区域：{project.get("customer_region", "")}
- 平台：{project.get("platform", "")}

写作要求：
1. 严格基于输入报告，不要新增公司事实、客户案例、排名、资质、地址、效果承诺或未出现的数据。
2. 语言要像顾问报告，清楚、克制、可执行。
3. 如果样本数为 0，不要给出优化成效判断；应建议先补事实库和完成首批采样。
4. 客户交付版不要出现“老板演示”“内部验证”“Demo”“Agent”“API Key”等内部词。
5. executive_summary 控制在 120-180 个中文字符内。
6. key_findings 输出 3-5 条，每条不超过 80 个中文字符。
7. next_actions 输出 3-5 条，每条必须可执行。
8. caveats 输出 1-3 条，说明数据边界或需人工确认事项。

当前报告 Markdown：
{markdown_text}

输出 JSON Schema：
{schema_text}
"""


def llm_numeric_env(name, default, cast_type=float, minimum=None, maximum=None):
    raw = os.environ.get(name, "")
    try:
        value = cast_type(raw) if raw != "" else default
    except (TypeError, ValueError):
        value = default
    if minimum is not None:
        value = max(minimum, value)
    if maximum is not None:
        value = min(maximum, value)
    return value


def extract_llm_message_content(response_obj):
    if not isinstance(response_obj, dict):
        return ""
    choices = response_obj.get("choices")
    if isinstance(choices, list) and choices:
        first = choices[0] if isinstance(choices[0], dict) else {}
        message = first.get("message") if isinstance(first.get("message"), dict) else {}
        content = message.get("content")
        if isinstance(content, str):
            return content
        if isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict):
                    if isinstance(item.get("text"), str):
                        parts.append(item["text"])
                    elif isinstance(item.get("content"), str):
                        parts.append(item["content"])
            if parts:
                return "\n".join(parts)
        text = first.get("text")
        if isinstance(text, str):
            return text
    for key in ("output_text", "content", "text"):
        value = response_obj.get(key)
        if isinstance(value, str):
            return value
    return ""


def extract_llm_finish_reason(response_obj):
    if not isinstance(response_obj, dict):
        return ""
    choices = response_obj.get("choices")
    if isinstance(choices, list) and choices:
        first = choices[0] if isinstance(choices[0], dict) else {}
        finish_reason = first.get("finish_reason") or first.get("stop_reason")
        if finish_reason is not None:
            return str(finish_reason).strip()
    finish_reason = response_obj.get("finish_reason") or response_obj.get("stop_reason")
    return str(finish_reason or "").strip()


def parse_optional_bool(value):
    text = str(value or "").strip().lower()
    if text in {"1", "true", "yes", "on"}:
        return True
    if text in {"0", "false", "no", "off"}:
        return False
    return None


def llm_enable_thinking_value(llm_config):
    explicit = parse_optional_bool(
        llm_config.get("enable_thinking") or os.environ.get("GEO_LLM_ENABLE_THINKING", "")
    )
    if explicit is not None:
        return explicit
    provider = str(llm_config.get("provider") or "").strip().lower()
    model = str(llm_config.get("model") or "").strip().lower()
    if provider in {"dashscope", "aliyun", "qwen"} and model.startswith("qwen3."):
        return False
    return None


def call_llm_chat_completion(prompt, llm_config):
    if not llm_config.get("configured"):
        missing = "、".join(llm_config.get("missing") or ["LLM API 配置"])
        raise ValueError(f"LLM API 尚未配置完整：缺少 {missing}")

    api_key = llm_config.get("api_key") or os.environ.get(llm_config.get("api_key_env", ""), "")
    temperature = llm_numeric_env("GEO_LLM_TEMPERATURE", 0.1, float, 0, 2)
    if llm_config.get("temperature"):
        try:
            temperature = max(0, min(2, float(llm_config["temperature"])))
        except (TypeError, ValueError):
            temperature = 0.1
    max_tokens = llm_numeric_env("GEO_LLM_MAX_TOKENS", 4096, int, 256, 20000)
    if llm_config.get("max_tokens"):
        try:
            max_tokens = max(256, min(20000, int(llm_config["max_tokens"])))
        except (TypeError, ValueError):
            max_tokens = 4096
    timeout = llm_numeric_env("GEO_LLM_TIMEOUT", 90, int, 10, 300)
    if llm_config.get("timeout"):
        try:
            timeout = max(10, min(300, int(llm_config["timeout"])))
        except (TypeError, ValueError):
            timeout = 90
    payload = {
        "model": llm_config["model"],
        "messages": [
            {
                "role": "system",
                "content": "你是严谨的 B2B GEO 监测分析器，只输出合法 JSON。",
            },
            {"role": "user", "content": prompt},
        ],
        "temperature": temperature,
        "max_tokens": max_tokens,
    }
    json_mode = str(llm_config.get("json_mode") or os.environ.get("GEO_LLM_JSON_MODE", "")).strip().lower()
    if json_mode in {"1", "true", "yes", "json"}:
        payload["response_format"] = {"type": "json_object"}
    enable_thinking = llm_enable_thinking_value(llm_config)
    if enable_thinking is not None:
        payload["enable_thinking"] = enable_thinking

    data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request = urllib_request.Request(
        llm_config["endpoint"],
        data=data,
        method="POST",
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
        },
    )
    try:
        with urllib_request.urlopen(request, timeout=timeout) as response:
            body = response.read().decode("utf-8", errors="replace")
            response_obj = json.loads(body)
    except urllib_error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise ValueError(f"LLM API 返回错误 {exc.code}：{body[:500]}") from exc
    except urllib_error.URLError as exc:
        raise ValueError(f"LLM API 请求失败：{exc.reason}") from exc
    except json.JSONDecodeError as exc:
        raise ValueError(f"LLM API 返回内容不是 JSON：{exc}") from exc

    content = extract_llm_message_content(response_obj)
    if not content.strip():
        raise ValueError("LLM API 没有返回可解析的内容")
    return {
        "content": content,
        "model": response_obj.get("model") or llm_config["model"],
        "usage": response_obj.get("usage", {}),
        "provider": llm_config.get("provider", ""),
        "finish_reason": extract_llm_finish_reason(response_obj),
    }


def db_project_analysis_brief_payload(
    project_id,
    limit=ANALYSIS_REVIEW_MAX_SAMPLES,
    *,
    sample_ids=None,
):
    project_id = unquote(str(project_id or "").strip())
    sample_limit = parse_bounded_int(
        limit,
        default=ANALYSIS_REVIEW_MAX_SAMPLES,
        minimum=1,
        maximum=ANALYSIS_REVIEW_MAX_SAMPLES,
    )
    with db_connect() as conn:
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        facts = db_rows_to_list(
            conn.execute(
                """
                SELECT *
                FROM customer_facts
                WHERE customer_id = ? AND fact_type <> 'question_profile'
                ORDER BY fact_type, fact_id
                """,
                (project["customer_id"],),
            ).fetchall()
        )
        competitors = db_rows_to_list(
            conn.execute(
                """
                SELECT *
                FROM competitors
                WHERE customer_id = ?
                ORDER BY competitor_id
                """,
                (project["customer_id"],),
            ).fetchall()
        )
        forbidden_claims = db_rows_to_list(
            conn.execute(
                """
                SELECT *
                FROM forbidden_claims
                WHERE customer_id = ?
                ORDER BY claim_id
                """,
                (project["customer_id"],),
            ).fetchall()
        )
        normalized_sample_ids = []
        for value in sample_ids or []:
            sample_id = str(value or "").strip()
            if sample_id and sample_id not in normalized_sample_ids:
                normalized_sample_ids.append(sample_id)
        if normalized_sample_ids:
            if len(normalized_sample_ids) > ANALYSIS_REVIEW_MAX_SAMPLES:
                raise ValueError("精确复核样本数量超过允许上限")
            placeholders = ",".join("?" for _ in normalized_sample_ids)
            selected_rows = db_rows_to_list(
                conn.execute(
                    f"""
                    SELECT s.*, q.question, q.category, q.intent
                    FROM samples s
                    JOIN question_pool q ON q.question_id = s.question_id
                    WHERE s.project_id = ? AND s.sample_type = 'real'
                      AND s.sample_id IN ({placeholders})
                    """,
                    [project_id, *normalized_sample_ids],
                ).fetchall()
            )
            selected_by_id = {row["sample_id"]: row for row in selected_rows}
            missing_sample_ids = [
                sample_id
                for sample_id in normalized_sample_ids
                if sample_id not in selected_by_id
            ]
            if missing_sample_ids:
                raise ValueError(
                    "以下精确复核样本不存在、不是当前项目真实样本或已失效："
                    + "、".join(missing_sample_ids[:10])
                )
            sample_rows = [
                selected_by_id[sample_id]
                for sample_id in normalized_sample_ids
            ]
        else:
            sample_rows = db_rows_to_list(
                conn.execute(
                    """
                    SELECT s.*, q.question, q.category, q.intent
                    FROM samples s
                    JOIN question_pool q ON q.question_id = s.question_id
                    WHERE s.project_id = ? AND s.sample_type = 'real'
                    ORDER BY s.collected_at DESC, s.question_id
                    LIMIT ?
                    """,
                    (project_id, sample_limit),
                ).fetchall()
            )

    fact_ready = bool(facts or competitors or forbidden_claims)
    baseline_analyses = []
    if fact_ready and sample_rows:
        context = project_fact_context(project, facts, competitors)
        baseline_analyses = [
            analyze_project_sample(
                sample,
                project,
                facts,
                competitors,
                forbidden_claims,
                context,
            )
            for sample in sample_rows
        ]

    input_package = build_project_llm_input_package(
        project,
        facts,
        competitors,
        forbidden_claims,
        sample_rows,
        baseline_analyses,
    )
    output_schema = project_llm_output_schema()
    execution = project_llm_execution_metadata(input_package)
    llm_config = llm_api_config()
    can_generate_prompt = fact_ready and bool(sample_rows)
    readiness = {
        "fact_base_ready": fact_ready,
        "sample_ready": bool(sample_rows),
        "rules_baseline_ready": bool(baseline_analyses),
        "llm_api_configured": llm_config["configured"],
        "can_generate_prompt": can_generate_prompt,
        "can_call_llm": can_generate_prompt and llm_config["configured"],
        "missing": [
            label
            for label, missing in [
                ("客户事实库", not fact_ready),
                ("真实采样回答", not sample_rows),
                *[(item, True) for item in llm_config.get("missing", [])],
            ]
            if missing
        ],
    }
    return {
        "ok": True,
        "project": project,
        "readiness": readiness,
        "llm_config": llm_config,
        "input_package": input_package,
        "output_schema": output_schema,
        "execution": execution,
        "prompt": build_project_llm_prompt(input_package, output_schema) if can_generate_prompt else "",
        "source": "sqlite",
    }


RISK_LEVEL_ORDER = {"低": 0, "中": 1, "高": 2, "极高": 3}


def extract_json_text(value):
    text = str(value or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\s*```$", "", text).strip()
    first = text.find("{")
    last = text.rfind("}")
    if first >= 0 and last > first:
        return text[first : last + 1]
    return text


KNOWLEDGE_FACT_TYPES = {
    "entity", "industry", "region", "positioning", "target_customer", "service",
    "product", "capability", "proof", "case", "qualification", "allowed_claim",
    "competitor", "forbidden_claim", "contact", "website", "custom",
}
KNOWLEDGE_SENSITIVE_TERMS = (
    "第一", "唯一", "最大", "最佳", "顶级", "头部", "领先", "保证", "100%", "百分之百",
    "国家级", "世界级", "永久", "绝对", "知名客户", "合作客户",
)


def read_source_extraction(row):
    path = (ROOT / str(row["extracted_path"] or "")).resolve()
    path.relative_to(CUSTOMER_SOURCE_ROOT.resolve())
    if not path.is_file():
        raise ValueError(f"资料提取结果不存在：{row['display_name']}")
    payload = json.loads(path.read_text(encoding="utf-8"))
    blocks = payload.get("blocks") if isinstance(payload, dict) else []
    return [item for item in blocks if isinstance(item, dict) and str(item.get("text") or "").strip()]


def build_knowledge_work_items(document_rows, max_chars=12000):
    work_items = []
    for row in document_rows:
        blocks = read_source_extraction(row)
        current_indices = []
        current_chars = 0
        for index, block in enumerate(blocks):
            block_chars = len(str(block.get("text") or ""))
            if current_indices and current_chars + block_chars > max_chars:
                work_items.append({
                    "work_item_id": make_id("chunk"),
                    "document_id": row["document_id"],
                    "block_indices": current_indices,
                    "status": "pending",
                    "error": "",
                })
                current_indices = []
                current_chars = 0
            current_indices.append(index)
            current_chars += block_chars
        if current_indices:
            work_items.append({
                "work_item_id": make_id("chunk"),
                "document_id": row["document_id"],
                "block_indices": current_indices,
                "status": "pending",
                "error": "",
            })
    return work_items


def knowledge_run_public_payload(row):
    item = db_row_to_dict(row)
    work_items = item.pop("work_items", [])
    item["work_items"] = [
        {
            "work_item_id": work.get("work_item_id", ""),
            "document_id": work.get("document_id", ""),
            "status": work.get("status", "pending"),
            "error": work.get("error", ""),
        }
        for work in work_items
    ]
    item["progress"] = {
        "completed": int(item.get("completed_items") or 0),
        "failed": int(item.get("failed_items") or 0),
        "total": int(item.get("total_items") or 0),
    }
    item["has_more"] = any(work.get("status") == "pending" for work in work_items)
    return item


def db_customer_knowledge_runs_payload(customer_id, run_id=""):
    customer_id = unquote(str(customer_id or "").strip())
    run_id = unquote(str(run_id or "").strip())
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        if not conn.execute("SELECT 1 FROM customers WHERE customer_id = ?", (customer_id,)).fetchone():
            return None
        if run_id:
            row = conn.execute(
                "SELECT * FROM customer_knowledge_import_runs WHERE customer_id = ? AND import_run_id = ?",
                (customer_id, run_id),
            ).fetchone()
            return {"customer_id": customer_id, "run": knowledge_run_public_payload(row)} if row else None
        rows = conn.execute(
            "SELECT * FROM customer_knowledge_import_runs WHERE customer_id = ? ORDER BY created_at DESC LIMIT 20",
            (customer_id,),
        ).fetchall()
    return {"customer_id": customer_id, "items": [knowledge_run_public_payload(row) for row in rows]}


def db_create_customer_knowledge_run(customer_id, payload):
    customer_id = unquote(str(customer_id or "").strip())
    document_ids = [str(item or "").strip() for item in (payload.get("document_ids") or []) if str(item or "").strip()]
    document_ids = list(dict.fromkeys(document_ids))
    if not document_ids:
        raise ValueError("请至少选择一份已解析资料。")
    if len(document_ids) > CUSTOMER_SOURCE_MAX_BATCH_FILES:
        raise ValueError("单次建档最多使用 10 份资料。")
    placeholders = ",".join("?" for _ in document_ids)
    timestamp = now_iso()
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        customer = conn.execute("SELECT * FROM customers WHERE customer_id = ?", (customer_id,)).fetchone()
        if not customer:
            raise ValueError("客户不存在。")
        rows = conn.execute(
            f"SELECT * FROM customer_source_documents WHERE customer_id = ? AND document_id IN ({placeholders}) ORDER BY created_at",
            (customer_id, *document_ids),
        ).fetchall()
        if len(rows) != len(document_ids):
            raise ValueError("部分资料不存在或不属于当前客户。")
        invalid = [row["display_name"] for row in rows if row["parse_status"] != "ready"]
        if invalid:
            raise ValueError(f"以下资料尚无足够可用文字：{'、'.join(invalid)}")
        work_items = build_knowledge_work_items(rows)
        if not work_items:
            raise ValueError("所选资料没有可用于建档的文字。")
        run_id = make_id("kimport")
        warnings = [row["parse_warning"] for row in rows if row["parse_warning"]]
        conn.execute(
            """
            INSERT INTO customer_knowledge_import_runs (
              import_run_id, customer_id, document_ids_json, work_items_json,
              draft_items_json, conflicts_json, warnings_json, status,
              completed_items, failed_items, total_items, created_at, updated_at
            ) VALUES (?, ?, ?, ?, '[]', '[]', ?, 'queued', 0, 0, ?, ?, ?)
            """,
            (run_id, customer_id, json_dump(document_ids), json_dump(work_items), json_dump(warnings), len(work_items), timestamp, timestamp),
        )
        row = conn.execute("SELECT * FROM customer_knowledge_import_runs WHERE import_run_id = ?", (run_id,)).fetchone()
    return {"customer": db_row_to_dict(customer), "run": knowledge_run_public_payload(row)}


def knowledge_existing_index(conn, customer_id):
    index = {}
    for row in conn.execute(
        "SELECT fact_type, fact_key, fact_value FROM customer_facts WHERE customer_id = ?",
        (customer_id,),
    ).fetchall():
        index[(str(row["fact_type"]), str(row["fact_key"]))] = str(row["fact_value"])
    return index


def knowledge_chunk_text(document_row, work_item):
    blocks = read_source_extraction(document_row)
    selected = []
    for index in work_item.get("block_indices") or []:
        if isinstance(index, int) and 0 <= index < len(blocks):
            selected.append(blocks[index])
    text = "\n\n".join(f"【{item.get('location') or '正文'}】\n{item.get('text') or ''}" for item in selected)
    return selected, text


def build_knowledge_import_prompt(customer, document, chunk_text, existing_facts):
    existing_lines = [f"- {key[0]}/{key[1]}：{value}" for key, value in list(existing_facts.items())[:80]]
    return f"""你是客户知识库建档审核助手。请只根据给定原文提取可以核验的事实，输出合法 JSON，不要补充常识或猜测。

客户：{customer['name']}
行业：{customer['industry'] or '待补充'}
资料：{document['display_name']}

已有确认事实（用于识别冲突，不能用来替代本段原文证据）：
{chr(10).join(existing_lines) or '- 暂无'}

输出格式：
{{"items":[{{"fact_type":"entity|industry|region|positioning|target_customer|service|product|capability|proof|case|qualification|allowed_claim|competitor|forbidden_claim|contact|website|custom","fact_key":"稳定的英文或拼音字段名","fact_value":"简洁事实","source_location":"必须填写原文中的【位置】","evidence_quote":"必须逐字摘录原文中的短句","confidence":0.0,"notes":"必要的审核说明"}}]}}

规则：
1. evidence_quote 必须能在原文中逐字找到；没有原文证据就不要输出。
2. 公司名称、品牌、行业、区域、定位、目标客户、服务、产品线、能力、案例/资质、允许表述、竞品、禁用表述和公开联系方式可提取。
3. 不从普通行业提及推断竞品；只有原文明示对比、替代、竞争关系时才输出 competitor。
4. 排名、头部地位、效果承诺、客户案例和资质必须原文明示，并在 notes 标记“需人工重点确认”。
5. 营销形容词不要改写成客观事实；不确定内容降低 confidence。
6. 每个 item 只表达一个事实，fact_value 不要包含 Markdown。

原文：
{chunk_text}
"""


def normalize_knowledge_draft_items(result_obj, document, chunk_blocks, existing_index):
    raw_items = result_obj.get("items") if isinstance(result_obj, dict) else []
    if not isinstance(raw_items, list):
        raise ValueError("大模型建档结果缺少 items 数组。")
    full_text = "\n".join(str(block.get("text") or "") for block in chunk_blocks)
    normalized_full = re.sub(r"\s+", "", full_text)
    items = []
    warnings = []
    for index, raw in enumerate(raw_items[:80], start=1):
        if not isinstance(raw, dict):
            warnings.append(f"第 {index} 条草稿不是对象，已忽略。")
            continue
        fact_type = str(raw.get("fact_type") or "custom").strip().lower()
        if fact_type not in KNOWLEDGE_FACT_TYPES:
            fact_type = "custom"
        fact_key = safe_db_token(raw.get("fact_key") or f"{fact_type}_{index}", fallback=f"{fact_type}_{index}").lower()
        fact_value = normalize_source_text(raw.get("fact_value"))
        evidence_quote = normalize_source_text(raw.get("evidence_quote"))
        source_location = str(raw.get("source_location") or "正文").strip()
        if not fact_value or len(fact_value) > 2000 or not evidence_quote:
            warnings.append(f"第 {index} 条草稿缺少事实值或证据摘录，已忽略。")
            continue
        if re.sub(r"\s+", "", evidence_quote) not in normalized_full:
            warnings.append(f"第 {index} 条证据摘录无法在原文中定位，已忽略。")
            continue
        try:
            confidence = max(0, min(1, float(raw.get("confidence", 0.5))))
        except (TypeError, ValueError):
            confidence = 0.5
        existing_value = existing_index.get((fact_type, fact_key), "")
        conflict = bool(existing_value and normalize_source_text(existing_value) != fact_value)
        sensitive = fact_type in {"proof", "case", "qualification", "competitor"} or any(term in fact_value for term in KNOWLEDGE_SENSITIVE_TERMS)
        draft_seed = f"{document['document_id']}|{fact_type}|{fact_key}|{fact_value}|{source_location}"
        items.append({
            "draft_id": "draft_" + hashlib.sha1(draft_seed.encode("utf-8")).hexdigest()[:16],
            "fact_type": fact_type,
            "fact_key": fact_key,
            "fact_value": fact_value,
            "source_document_id": document["document_id"],
            "source_name": document["display_name"],
            "source_location": source_location,
            "source_url": document["source_url"] or "",
            "evidence_quote": evidence_quote,
            "confidence": round(confidence, 2),
            "notes": str(raw.get("notes") or "").strip(),
            "conflict": conflict,
            "existing_value": existing_value,
            "requires_review": sensitive or confidence < 0.75,
            "selected": not conflict and not sensitive and confidence >= 0.75,
        })
    return items, warnings


def merge_knowledge_drafts(existing, additions):
    merged = {item.get("draft_id"): item for item in existing if item.get("draft_id")}
    for item in additions:
        merged[item["draft_id"]] = item
    return list(merged.values())


def knowledge_run_status_from_work(work_items):
    pending = sum(1 for item in work_items if item.get("status") == "pending")
    failed = sum(1 for item in work_items if item.get("status") == "failed")
    completed = sum(1 for item in work_items if item.get("status") == "success")
    if pending:
        status = "running"
    elif failed:
        status = "partial_failed" if completed else "failed"
    else:
        status = "ready"
    return status, completed, failed


def is_fatal_llm_configuration_error(message):
    text = str(message or "").lower()
    return any(token in text for token in ("尚未配置", "api key", "unauthorized", "authentication", "401", "403", "缺少 endpoint", "缺少 model"))


def db_run_next_customer_knowledge_step(customer_id, run_id, payload):
    customer_id = unquote(str(customer_id or "").strip())
    run_id = unquote(str(run_id or "").strip())
    retry_failed = bool(payload.get("retry_failed"))
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        run_row = conn.execute(
            "SELECT * FROM customer_knowledge_import_runs WHERE customer_id = ? AND import_run_id = ?",
            (customer_id, run_id),
        ).fetchone()
        if not run_row:
            return None
        run = db_row_to_dict(run_row)
        if run.get("status") == "applied":
            raise ValueError("该建档草稿已经入库。")
        work_items = run.get("work_items") or []
        target = next((item for item in work_items if item.get("status") == ("failed" if retry_failed else "pending")), None)
        if target is None and retry_failed:
            target = next((item for item in work_items if item.get("status") == "pending"), None)
        if target is None:
            status, completed, failed = knowledge_run_status_from_work(work_items)
            conn.execute(
                "UPDATE customer_knowledge_import_runs SET status = ?, completed_items = ?, failed_items = ?, completed_at = ?, updated_at = ? WHERE import_run_id = ?",
                (status, completed, failed, now_iso() if status in {"ready", "partial_failed", "failed"} else "", now_iso(), run_id),
            )
            row = conn.execute("SELECT * FROM customer_knowledge_import_runs WHERE import_run_id = ?", (run_id,)).fetchone()
            return {"run": knowledge_run_public_payload(row), "step": None}
        target["status"] = "running"
        target["error"] = ""
        conn.execute(
            "UPDATE customer_knowledge_import_runs SET status = 'running', work_items_json = ?, updated_at = ? WHERE import_run_id = ?",
            (json_dump(work_items), now_iso(), run_id),
        )
        customer = conn.execute("SELECT * FROM customers WHERE customer_id = ?", (customer_id,)).fetchone()
        document = conn.execute(
            "SELECT * FROM customer_source_documents WHERE customer_id = ? AND document_id = ?",
            (customer_id, target["document_id"]),
        ).fetchone()
        existing_index = knowledge_existing_index(conn, customer_id)

    if not document:
        step_error = "建档资料已不存在。"
        fatal = False
        additions = []
        step_warnings = []
        llm_result = {}
    else:
        chunk_blocks, chunk_text = knowledge_chunk_text(document, target)
        llm_config = llm_api_config(include_secret=True)
        try:
            prompt = build_knowledge_import_prompt(customer, document, chunk_text, existing_index)
            llm_result = call_llm_chat_completion(prompt, llm_config)
            result_obj = json.loads(extract_json_text(llm_result["content"]))
            additions, step_warnings = normalize_knowledge_draft_items(result_obj, document, chunk_blocks, existing_index)
            step_error = ""
            fatal = False
        except Exception as exc:
            step_error = truncate_text(mask_secret_text(str(exc)), 800)
            fatal = is_fatal_llm_configuration_error(step_error)
            additions = []
            step_warnings = []
            llm_result = {}

    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        row = conn.execute("SELECT * FROM customer_knowledge_import_runs WHERE import_run_id = ?", (run_id,)).fetchone()
        run = db_row_to_dict(row)
        work_items = run.get("work_items") or []
        current = next((item for item in work_items if item.get("work_item_id") == target.get("work_item_id")), None)
        if current:
            current["status"] = "failed" if step_error else "success"
            current["error"] = step_error
        drafts = merge_knowledge_drafts(run.get("draft_items") or [], additions)
        warnings = list(run.get("warnings") or []) + step_warnings
        conflicts = [item for item in drafts if item.get("conflict")]
        if fatal:
            for item in work_items:
                if item.get("status") == "pending":
                    item["status"] = "failed"
                    item["error"] = "因配置或鉴权错误停止。"
        status, completed, failed = knowledge_run_status_from_work(work_items)
        timestamp = now_iso()
        conn.execute(
            """
            UPDATE customer_knowledge_import_runs
            SET work_items_json = ?, draft_items_json = ?, conflicts_json = ?, warnings_json = ?,
                status = ?, completed_items = ?, failed_items = ?, llm_provider = ?, llm_model = ?,
                last_error = ?, completed_at = ?, updated_at = ?
            WHERE import_run_id = ?
            """,
            (
                json_dump(work_items), json_dump(drafts), json_dump(conflicts), json_dump(warnings), status,
                completed, failed, llm_result.get("provider", run.get("llm_provider", "")),
                llm_result.get("model", run.get("llm_model", "")), step_error,
                timestamp if status in {"ready", "partial_failed", "failed"} else "", timestamp, run_id,
            ),
        )
        updated = conn.execute("SELECT * FROM customer_knowledge_import_runs WHERE import_run_id = ?", (run_id,)).fetchone()
    return {
        "run": knowledge_run_public_payload(updated),
        "step": {"work_item_id": target.get("work_item_id"), "document_id": target.get("document_id"), "draft_count": len(additions), "error": step_error, "fatal": fatal},
    }


def db_apply_customer_knowledge_run(customer_id, run_id, payload):
    customer_id = unquote(str(customer_id or "").strip())
    run_id = unquote(str(run_id or "").strip())
    selected_ids = {str(item) for item in (payload.get("selected_draft_ids") or []) if str(item).strip()}
    timestamp = now_iso()
    with db_connect() as conn:
        ensure_customer_knowledge_import_tables(conn)
        run_row = conn.execute(
            "SELECT * FROM customer_knowledge_import_runs WHERE customer_id = ? AND import_run_id = ?",
            (customer_id, run_id),
        ).fetchone()
        if not run_row:
            return None
        run = db_row_to_dict(run_row)
        if run.get("status") == "applied":
            raise ValueError("该建档草稿已经入库。")
        if run.get("status") not in {"ready", "partial_failed"}:
            raise ValueError("建档任务尚未完成，暂不能入库。")
        drafts = run.get("draft_items") or []
        selected = [item for item in drafts if item.get("draft_id") in selected_ids]
        if not selected:
            raise ValueError("请至少勾选一条已核对的知识草稿。")
        customer_updates = {}
        fact_count = competitor_count = forbidden_count = 0
        for item in selected:
            fact_type = str(item.get("fact_type") or "custom")
            fact_key = str(item.get("fact_key") or make_id("fact"))
            fact_value = str(item.get("fact_value") or "").strip()
            if not fact_value:
                continue
            evidence_url = item.get("source_url") or f"source://{item.get('source_document_id')}#{quote(str(item.get('source_location') or '正文'))}"
            if fact_type == "competitor":
                competitor_id = f"comp_{safe_db_token(customer_id)}_{safe_db_token(fact_key)}"
                conn.execute(
                    """INSERT INTO competitors (competitor_id, customer_id, name, category, watch_reason, aliases_json, created_at, updated_at)
                    VALUES (?, ?, ?, 'AI 草稿审核入库', ?, '[]', ?, ?)
                    ON CONFLICT(competitor_id) DO UPDATE SET name=excluded.name, watch_reason=excluded.watch_reason, updated_at=excluded.updated_at""",
                    (competitor_id, customer_id, fact_value, item.get("notes") or item.get("evidence_quote") or "资料明确提及", timestamp, timestamp),
                )
                competitor_count += 1
                continue
            if fact_type == "forbidden_claim":
                claim_id = f"claim_{safe_db_token(customer_id)}_{safe_db_token(fact_key)}"
                conn.execute(
                    """INSERT INTO forbidden_claims (claim_id, customer_id, claim, severity, reason, created_at, updated_at)
                    VALUES (?, ?, ?, 'high', ?, ?, ?)
                    ON CONFLICT(claim_id) DO UPDATE SET claim=excluded.claim, reason=excluded.reason, updated_at=excluded.updated_at""",
                    (claim_id, customer_id, fact_value, item.get("notes") or "客户资料审核入库", timestamp, timestamp),
                )
                forbidden_count += 1
                continue
            fact_id = f"fact_{safe_db_token(customer_id)}_{safe_db_token(fact_type)}_{safe_db_token(fact_key)}"
            conn.execute(
                """INSERT INTO customer_facts (fact_id, customer_id, fact_type, fact_key, fact_value, visibility, evidence_url, confidence, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, 'public', ?, ?, ?, ?)
                ON CONFLICT(fact_id) DO UPDATE SET fact_value=excluded.fact_value, evidence_url=excluded.evidence_url, confidence=excluded.confidence, updated_at=excluded.updated_at""",
                (fact_id, customer_id, fact_type, fact_key, fact_value, evidence_url, f"confirmed_ai_{round(float(item.get('confidence') or 0.5), 2)}", timestamp, timestamp),
            )
            fact_count += 1
            if fact_type == "entity" and fact_key == "company_full_name":
                customer_updates["name"] = fact_value
            elif fact_type == "industry":
                customer_updates["industry"] = fact_value
            elif fact_type == "region":
                customer_updates["region"] = fact_value
            elif fact_type == "target_customer":
                customer_updates["target_customers"] = fact_value
            elif fact_type == "positioning" and fact_key in {"primary_positioning", "positioning"}:
                customer_updates["business_summary"] = fact_value
        if customer_updates:
            allowed = {key: value for key, value in customer_updates.items() if key in {"name", "industry", "region", "target_customers", "business_summary"}}
            assignments = ", ".join(f"{key} = ?" for key in allowed)
            conn.execute(
                f"UPDATE customers SET {assignments}, updated_at = ? WHERE customer_id = ?",
                (*allowed.values(), timestamp, customer_id),
            )
        version = create_fact_base_version(conn, customer_id, source="knowledge_import_v1", note=f"资料建档审核入库：{run_id}")
        conn.execute(
            "UPDATE customer_knowledge_import_runs SET status='applied', applied_fact_base_version_id=?, applied_at=?, updated_at=? WHERE import_run_id=?",
            (version["fact_base_version_id"], timestamp, timestamp, run_id),
        )
    return {
        "ok": True,
        "import_run_id": run_id,
        "fact_count": fact_count,
        "competitor_count": competitor_count,
        "forbidden_claim_count": forbidden_count,
        "fact_base_version": version,
    }


def validate_string_list(value, path, errors):
    if not isinstance(value, list):
        errors.append(f"{path} 必须是数组")
        return
    for index, item in enumerate(value):
        if not isinstance(item, str):
            errors.append(f"{path}[{index}] 必须是字符串")


def validate_llm_analysis_item(item, index, expected_questions, baseline_by_question, errors, warnings, conflicts):
    path = f"analyses[{index}]"
    required = [
        "question_id",
        "brand_mentioned",
        "brand_recommended",
        "risk_level",
        "competitors",
        "accurate_claims",
        "unverified_claims",
        "high_risk_hallucinations",
        "positioning_drift",
        "recommended_fix",
        "confidence",
        "evidence_quotes",
    ]
    if not isinstance(item, dict):
        errors.append(f"{path} 必须是对象")
        return ""
    for field in required:
        if field not in item:
            errors.append(f"{path}.{field} 缺失")

    question_id = str(item.get("question_id", "")).strip()
    if not question_id:
        errors.append(f"{path}.question_id 不能为空")
    elif expected_questions and question_id not in expected_questions:
        warnings.append(f"{path}.question_id={question_id} 不在当前 LLM 输入包样本中")

    for field in ("brand_mentioned", "brand_recommended"):
        if field in item and type(item[field]) is not bool:
            errors.append(f"{path}.{field} 必须是 true/false")

    risk_level = item.get("risk_level")
    if risk_level not in RISK_LEVEL_ORDER:
        errors.append(f"{path}.risk_level 必须是 低/中/高/极高")

    for field in (
        "competitors",
        "accurate_claims",
        "unverified_claims",
        "positioning_drift",
        "evidence_quotes",
    ):
        if field in item:
            validate_string_list(item[field], f"{path}.{field}", errors)

    high_risk = item.get("high_risk_hallucinations")
    if "high_risk_hallucinations" in item:
        if not isinstance(high_risk, list):
            errors.append(f"{path}.high_risk_hallucinations 必须是数组")
        else:
            for risk_index, risk_item in enumerate(high_risk):
                risk_path = f"{path}.high_risk_hallucinations[{risk_index}]"
                if not isinstance(risk_item, dict):
                    errors.append(f"{risk_path} 必须是对象")
                    continue
                for field in ("label", "severity", "reason"):
                    if not isinstance(risk_item.get(field), str) or not risk_item.get(field).strip():
                        errors.append(f"{risk_path}.{field} 必须是非空字符串")

    if "recommended_fix" in item and not isinstance(item.get("recommended_fix"), str):
        errors.append(f"{path}.recommended_fix 必须是字符串")

    confidence = item.get("confidence")
    if "confidence" in item:
        if not isinstance(confidence, (int, float)) or isinstance(confidence, bool):
            errors.append(f"{path}.confidence 必须是 0-1 的数字")
        elif confidence < 0 or confidence > 1:
            warnings.append(f"{path}.confidence 超出 0-1 范围")

    if question_id and question_id in baseline_by_question:
        baseline = baseline_by_question[question_id]
        for field in ("brand_mentioned", "brand_recommended"):
            if field in item and type(item[field]) is bool and item[field] != baseline.get(field):
                conflicts.append(
                    {
                        "question_id": question_id,
                        "field": field,
                        "rules_value": baseline.get(field),
                        "llm_value": item[field],
                        "message": f"{question_id} 的 {field} 与规则基线不一致",
                    }
                )
        if risk_level in RISK_LEVEL_ORDER and baseline.get("risk_level") in RISK_LEVEL_ORDER:
            delta = abs(RISK_LEVEL_ORDER[risk_level] - RISK_LEVEL_ORDER[baseline["risk_level"]])
            if delta >= 2:
                conflicts.append(
                    {
                        "question_id": question_id,
                        "field": "risk_level",
                        "rules_value": baseline["risk_level"],
                        "llm_value": risk_level,
                        "message": f"{question_id} 的风险等级与规则基线差异过大",
                    }
                )
            elif delta == 1:
                warnings.append(f"{question_id} 的风险等级与规则基线有轻微差异")

    if question_id and not item.get("evidence_quotes"):
        warnings.append(f"{question_id} 缺少 evidence_quotes，后续不建议自动落库")

    return question_id


def validate_llm_recommendation_item(item, index, expected_questions, errors, warnings):
    path = f"recommendations[{index}]"
    required = ["category", "title", "priority", "reason", "action", "evidence", "expected_impact"]
    if not isinstance(item, dict):
        errors.append(f"{path} 必须是对象")
        return
    for field in required:
        if field not in item:
            errors.append(f"{path}.{field} 缺失")
    for field in ("category", "title", "reason", "action", "expected_impact", "content_brief", "owner", "asset_type", "retest_plan"):
        if field in item and not isinstance(item.get(field), str):
            errors.append(f"{path}.{field} 必须是字符串")
    if item.get("priority") not in {"P0", "P1", "P2"}:
        errors.append(f"{path}.priority 必须是 P0/P1/P2")
    if "evidence" in item:
        validate_string_list(item["evidence"], f"{path}.evidence", errors)
    if "target_questions" in item:
        validate_string_list(item["target_questions"], f"{path}.target_questions", errors)
        for question_id in item.get("target_questions", []) or []:
            question_id = str(question_id).strip()
            if question_id and expected_questions and question_id not in expected_questions:
                warnings.append(f"{path}.target_questions 包含非输入包问题：{question_id}")
    else:
        warnings.append(f"{path}.target_questions 缺失，建议需绑定本次样本问题")
    if not item.get("target_questions"):
        warnings.append(f"{path}.target_questions 为空，建议难以进入复测闭环")
    if not str(item.get("content_brief", "")).strip():
        warnings.append(f"{path}.content_brief 为空，建议缺少可执行内容 brief")
    if "required_facts_to_confirm" in item:
        validate_string_list(item["required_facts_to_confirm"], f"{path}.required_facts_to_confirm", errors)
    else:
        warnings.append(f"{path}.required_facts_to_confirm 缺失，建议无法区分已确认事实和待确认事实")
    for field in ("impacted_scenes", "deliverables", "content_outline", "source_strategy", "acceptance_criteria", "limitations"):
        if field in item:
            validate_string_list(item[field], f"{path}.{field}", errors)
        else:
            warnings.append(f"{path}.{field} 缺失，客户行动方案信息不完整")
    if not str(item.get("asset_type", "")).strip():
        warnings.append(f"{path}.asset_type 缺失，无法按内容资产分类展示")
    if not str(item.get("retest_plan", "")).strip():
        warnings.append(f"{path}.retest_plan 缺失，建议无法形成验收闭环")


def db_validate_project_llm_analysis_payload(
    project_id,
    payload,
    *,
    sample_ids=None,
):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    limit = parse_bounded_int(
        payload.get("limit"),
        default=ANALYSIS_REVIEW_MAX_SAMPLES,
        minimum=1,
        maximum=ANALYSIS_REVIEW_MAX_SAMPLES,
    )
    result_obj = payload.get("result_json")
    raw_text = payload.get("result_text", "")
    parse_errors = []
    if isinstance(result_obj, str):
        raw_text = result_obj
        result_obj = None
    if result_obj is None:
        json_text = extract_json_text(raw_text)
        if not json_text:
            parse_errors.append("请先粘贴 LLM 返回的 JSON")
            result_obj = {}
        else:
            try:
                result_obj = json.loads(json_text)
            except json.JSONDecodeError as exc:
                parse_errors.append(f"JSON 解析失败：第 {exc.lineno} 行第 {exc.colno} 列，{exc.msg}")
                result_obj = {}

    brief = db_project_analysis_brief_payload(
        project_id,
        limit=limit,
        sample_ids=sample_ids,
    )
    if brief is None:
        return None

    input_samples = brief.get("input_package", {}).get("samples", [])
    expected_questions = {sample.get("question_id", "") for sample in input_samples if sample.get("question_id")}
    baseline_by_question = {
        sample.get("question_id"): sample.get("rules_baseline")
        for sample in input_samples
        if sample.get("question_id") and sample.get("rules_baseline")
    }

    errors = []
    warnings = []
    conflicts = []
    seen_questions = set()

    if parse_errors:
        errors.extend(parse_errors)
    elif not isinstance(result_obj, dict):
        errors.append("LLM 返回结果顶层必须是对象")
    else:
        analyses = result_obj.get("analyses")
        recommendations = result_obj.get("recommendations")
        quality_checks = result_obj.get("quality_checks")

        if not isinstance(analyses, list):
            errors.append("analyses 必须是数组")
            analyses = []
        if not isinstance(recommendations, list):
            errors.append("recommendations 必须是数组")
            recommendations = []
        if not isinstance(quality_checks, dict):
            errors.append("quality_checks 必须是对象")
            quality_checks = {}

        for index, item in enumerate(analyses):
            question_id = validate_llm_analysis_item(
                item,
                index,
                expected_questions,
                baseline_by_question,
                errors,
                warnings,
                conflicts,
            )
            if question_id:
                if question_id in seen_questions:
                    warnings.append(f"{question_id} 在 analyses 中重复出现")
                seen_questions.add(question_id)

        missing_questions = sorted(expected_questions - seen_questions)
        if missing_questions:
            warnings.append("缺少输入包中的问题分析：" + "、".join(missing_questions))

        if not recommendations:
            warnings.append("recommendations 为空，无法生成优化任务")
        elif len(recommendations) < 2:
            warnings.append("recommendations 少于 2 条，建议覆盖可能不足")
        elif len(recommendations) > 5:
            warnings.append("recommendations 超过 5 条，建议合并为更聚焦的执行项")

        for index, item in enumerate(recommendations):
            validate_llm_recommendation_item(item, index, expected_questions, errors, warnings)

        if isinstance(quality_checks, dict):
            for field in ("missing_inputs", "conflicts_with_rules"):
                if field in quality_checks:
                    validate_string_list(quality_checks[field], f"quality_checks.{field}", errors)
                else:
                    errors.append(f"quality_checks.{field} 缺失")
            if type(quality_checks.get("needs_human_review")) is not bool:
                errors.append("quality_checks.needs_human_review 必须是 true/false")
            for item in quality_checks.get("conflicts_with_rules", []) or []:
                if isinstance(item, str) and item.strip():
                    conflicts.append(
                        {
                            "question_id": "",
                            "field": "quality_checks.conflicts_with_rules",
                            "rules_value": "",
                            "llm_value": item,
                            "message": item,
                        }
                    )

    status = "invalid" if errors else "review" if conflicts or warnings else "pass"
    accepted_for_review = not errors
    can_auto_save_later = accepted_for_review and status == "pass"
    return {
        "ok": True,
        "project": brief.get("project"),
        "accepted_for_review": accepted_for_review,
        "can_auto_save_later": can_auto_save_later,
        "summary": {
            "status": status,
            "expected_questions": len(expected_questions),
            "analysis_count": len(seen_questions),
            "format_error_count": len(errors),
            "warning_count": len(warnings),
            "conflict_count": len(conflicts),
        },
        "checks": {
            "errors": errors,
            "warnings": warnings,
            "conflicts": conflicts,
            "expected_questions": sorted(expected_questions),
            "seen_questions": sorted(seen_questions),
        },
        "source": "sqlite",
    }


def parse_project_llm_result_text(raw_text, context_label="LLM 返回"):
    json_text = extract_json_text(raw_text)
    if not json_text:
        raise ValueError(f"{context_label}没有可解析的 JSON")
    try:
        result_obj = json.loads(json_text)
    except json.JSONDecodeError as exc:
        raise ValueError(
            f"{context_label} JSON 解析失败：第 {exc.lineno} 行第 {exc.colno} 列，{exc.msg}"
        ) from exc
    if not isinstance(result_obj, dict):
        raise ValueError(f"{context_label}顶层必须是 JSON 对象")
    return result_obj


def validate_project_llm_batch_result(result_obj, input_package, batch_index, batch_count):
    expected_order = project_llm_question_ids(input_package)
    expected_questions = set(expected_order)
    baseline_by_question = {
        str(sample.get("question_id") or "").strip(): sample.get("rules_baseline")
        for sample in (input_package or {}).get("samples", []) or []
        if str(sample.get("question_id") or "").strip() and sample.get("rules_baseline")
    }
    errors = []
    warnings = []
    conflicts = []
    seen_questions = set()

    analyses = result_obj.get("analyses")
    recommendations = result_obj.get("recommendations")
    quality_checks = result_obj.get("quality_checks")
    if not isinstance(analyses, list):
        errors.append("analyses 必须是数组")
        analyses = []
    if not isinstance(recommendations, list):
        errors.append("recommendations 必须是数组")
        recommendations = []
    if not isinstance(quality_checks, dict):
        errors.append("quality_checks 必须是对象")
        quality_checks = {}

    for index, item in enumerate(analyses):
        question_id = validate_llm_analysis_item(
            item,
            index,
            expected_questions,
            baseline_by_question,
            errors,
            warnings,
            conflicts,
        )
        if not question_id:
            continue
        if question_id in seen_questions:
            errors.append(f"{question_id} 在 analyses 中重复出现")
        seen_questions.add(question_id)
        if question_id not in expected_questions:
            errors.append(f"{question_id} 不属于第 {batch_index}/{batch_count} 批输入")

    missing_questions = [
        question_id
        for question_id in expected_order
        if question_id not in seen_questions
    ]
    if missing_questions:
        errors.append("缺少本批问题分析：" + "、".join(missing_questions))

    for index, item in enumerate(recommendations):
        validate_llm_recommendation_item(
            item,
            index,
            expected_questions,
            errors,
            warnings,
        )

    if isinstance(quality_checks, dict):
        for field in ("missing_inputs", "conflicts_with_rules"):
            if field in quality_checks:
                validate_string_list(
                    quality_checks[field],
                    f"quality_checks.{field}",
                    errors,
                )
            else:
                errors.append(f"quality_checks.{field} 缺失")
        if type(quality_checks.get("needs_human_review")) is not bool:
            errors.append("quality_checks.needs_human_review 必须是 true/false")

    if errors:
        detail = "；".join(errors[:8])
        if len(errors) > 8:
            detail += f"；另有 {len(errors) - 8} 项格式错误"
        raise ValueError(
            f"第 {batch_index}/{batch_count} 批返回结构不完整：{detail}"
        )
    return result_obj


def parse_project_llm_batch_response(llm_response, input_package, batch_index, batch_count):
    finish_reason = str(llm_response.get("finish_reason") or "").strip()
    if finish_reason.casefold() in ANALYSIS_LLM_TRUNCATION_FINISH_REASONS:
        raise ValueError(
            f"第 {batch_index}/{batch_count} 批输出被模型截断"
            f"（finish_reason={finish_reason}）。系统未自动重试；"
            "请从已完成批次继续，或在模型配置中提高输出上限。"
        )
    context_label = f"第 {batch_index}/{batch_count} 批"
    result_obj = parse_project_llm_result_text(
        llm_response.get("content", ""),
        context_label=context_label,
    )
    return validate_project_llm_batch_result(
        result_obj,
        input_package,
        batch_index,
        batch_count,
    )


def stable_unique_strings(values, limit=0):
    rows = []
    seen = set()
    for value in values or []:
        text = str(value or "").strip()
        if not text:
            continue
        key = text.casefold()
        if key in seen:
            continue
        seen.add(key)
        rows.append(text)
        if limit and len(rows) >= limit:
            break
    return rows


def recommendation_merge_key(item):
    def normalized(value):
        return re.sub(r"[\s\W_]+", "", str(value or ""), flags=re.UNICODE).casefold()

    parts = [
        normalized(item.get("title")),
        normalized(item.get("action")),
        normalized(item.get("asset_type") or item.get("category")),
    ]
    key = "|".join(parts)
    if key.replace("|", ""):
        return key
    return json.dumps(item, ensure_ascii=False, sort_keys=True, default=str)


def merge_project_llm_recommendations(batch_results):
    list_fields = (
        "evidence",
        "target_questions",
        "required_facts_to_confirm",
        "impacted_scenes",
        "deliverables",
        "content_outline",
        "source_strategy",
        "acceptance_criteria",
        "limitations",
    )
    priority_order = {"P0": 0, "P1": 1, "P2": 2}
    merged = []
    by_key = {}
    sequence = 0
    for batch_index, result_obj in enumerate(batch_results, start=1):
        for item in result_obj.get("recommendations", []) or []:
            if not isinstance(item, dict):
                continue
            key = recommendation_merge_key(item)
            current = by_key.get(key)
            if current is None:
                current = {
                    "item": copy.deepcopy(item),
                    "batch_index": batch_index,
                    "sequence": sequence,
                }
                sequence += 1
                by_key[key] = current
                merged.append(current)
                continue
            existing = current["item"]
            for field in list_fields:
                limit = 5 if field == "target_questions" else 20
                existing[field] = stable_unique_strings(
                    list(existing.get(field) or []) + list(item.get(field) or []),
                    limit=limit,
                )
            existing_priority = priority_order.get(existing.get("priority"), 9)
            item_priority = priority_order.get(item.get("priority"), 9)
            if item_priority < existing_priority:
                existing["priority"] = item.get("priority")
            for field, value in item.items():
                if field not in existing or existing.get(field) in ("", None, []):
                    existing[field] = copy.deepcopy(value)

    selected = []
    used_assets = set()
    used_scenes = set()
    used_batches = set()
    candidates = list(merged)
    while candidates and len(selected) < ANALYSIS_LLM_MAX_RECOMMENDATIONS:
        def score(candidate):
            item = candidate["item"]
            asset = str(item.get("asset_type") or item.get("category") or "").strip().casefold()
            scenes = {
                str(value or "").strip().casefold()
                for value in item.get("impacted_scenes", []) or []
                if str(value or "").strip()
            }
            priority_score = 300 - 100 * priority_order.get(item.get("priority"), 3)
            coverage_score = 30 if asset and asset not in used_assets else 0
            coverage_score += 8 * len(scenes - used_scenes)
            coverage_score += 5 if candidate["batch_index"] not in used_batches else 0
            return (
                priority_score + coverage_score,
                -candidate["sequence"],
            )

        best = max(candidates, key=score)
        candidates.remove(best)
        item = best["item"]
        selected.append(item)
        asset = str(item.get("asset_type") or item.get("category") or "").strip().casefold()
        if asset:
            used_assets.add(asset)
        used_scenes.update(
            str(value or "").strip().casefold()
            for value in item.get("impacted_scenes", []) or []
            if str(value or "").strip()
        )
        used_batches.add(best["batch_index"])
    return selected


def merge_project_llm_batch_results(batch_results, input_package):
    analyses_by_question = {}
    for result_obj in batch_results:
        for item in result_obj.get("analyses", []) or []:
            if not isinstance(item, dict):
                continue
            question_id = str(item.get("question_id") or "").strip()
            if question_id and question_id not in analyses_by_question:
                analyses_by_question[question_id] = copy.deepcopy(item)

    quality_missing = []
    quality_conflicts = []
    needs_human_review = False
    for result_obj in batch_results:
        quality_checks = result_obj.get("quality_checks")
        if not isinstance(quality_checks, dict):
            continue
        quality_missing.extend(quality_checks.get("missing_inputs") or [])
        quality_conflicts.extend(quality_checks.get("conflicts_with_rules") or [])
        needs_human_review = needs_human_review or bool(
            quality_checks.get("needs_human_review")
        )

    return {
        "analyses": [
            analyses_by_question[question_id]
            for question_id in project_llm_question_ids(input_package)
            if question_id in analyses_by_question
        ],
        "recommendations": merge_project_llm_recommendations(batch_results),
        "quality_checks": {
            "missing_inputs": stable_unique_strings(quality_missing),
            "conflicts_with_rules": stable_unique_strings(quality_conflicts),
            "needs_human_review": needs_human_review,
        },
    }


def merge_llm_usage(*usage_values):
    merged = {}
    for usage in usage_values:
        if not isinstance(usage, dict):
            continue
        for key, value in usage.items():
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                merged[key] = merged.get(key, 0) + value
            elif key not in merged:
                merged[key] = copy.deepcopy(value)
    return merged


def validation_with_execution_error(validation, error_message):
    validation = copy.deepcopy(validation or {})
    validation["accepted_for_review"] = False
    validation["can_auto_save_later"] = False
    summary = validation.setdefault("summary", {})
    previous_errors = int(summary.get("format_error_count") or 0)
    summary["status"] = "invalid"
    summary["format_error_count"] = previous_errors + 1
    checks = validation.setdefault("checks", {})
    errors = list(checks.get("errors") or [])
    errors.append(error_message)
    checks["errors"] = errors
    return validation


def db_run_project_llm_analysis_payload(
    project_id,
    payload,
    *,
    sample_ids=None,
):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    limit = parse_bounded_int(
        payload.get("limit"),
        default=ANALYSIS_REVIEW_MAX_SAMPLES,
        minimum=1,
        maximum=ANALYSIS_REVIEW_MAX_SAMPLES,
    )
    brief = db_project_analysis_brief_payload(
        project_id,
        limit=limit,
        sample_ids=sample_ids,
    )
    if brief is None:
        return None
    prompt = brief.get("prompt", "")
    if not prompt:
        raise ValueError("当前项目还不能调用大模型：请先补事实库并完成真实采样")
    llm_config = llm_api_config(include_secret=True)
    if not llm_config.get("configured"):
        missing = "、".join(llm_config.get("missing") or ["LLM API 配置"])
        raise ValueError(f"LLM API 尚未配置完整：缺少 {missing}")

    input_package = brief.get("input_package") or {}
    output_schema = brief.get("output_schema") or project_llm_output_schema()
    batch_packages = split_project_llm_input_package(input_package)
    batch_count = len(batch_packages)
    if not batch_packages:
        raise ValueError("当前项目没有可进入大模型复核的问题")

    batch_results = []
    completed_batch_indices = set()
    resume_result_text = str(payload.get("resume_result_text") or "").strip()
    resume_llm_meta = (
        payload.get("resume_llm_meta")
        if isinstance(payload.get("resume_llm_meta"), dict)
        else {}
    )
    if resume_result_text:
        resume_execution = (
            payload.get("resume_execution")
            if isinstance(payload.get("resume_execution"), dict)
            else {}
        )
        expected_fingerprint = project_llm_input_fingerprint(input_package)
        resume_fingerprint = str(
            resume_execution.get("input_fingerprint") or ""
        ).strip()
        if not resume_fingerprint or not hmac.compare_digest(
            resume_fingerprint,
            expected_fingerprint,
        ):
            raise ValueError(
                "复核范围或样本已变化，旧草稿不能继续跳过批次；"
                "请重新生成复核包并从头调用"
            )
        resume_result = parse_project_llm_result_text(
            resume_result_text,
            context_label="续跑草稿",
        )
        resume_analyses = resume_result.get("analyses")
        if not isinstance(resume_analyses, list):
            raise ValueError("续跑草稿的 analyses 必须是数组")
        expected_questions = set(project_llm_question_ids(input_package))
        resume_question_ids = {
            str(item.get("question_id") or "").strip()
            for item in resume_analyses
            if isinstance(item, dict) and str(item.get("question_id") or "").strip()
        }
        unexpected_questions = sorted(resume_question_ids - expected_questions)
        if unexpected_questions:
            raise ValueError(
                "续跑草稿包含当前复核范围之外的问题："
                + "、".join(unexpected_questions[:20])
            )
        for batch_index, package in enumerate(batch_packages, start=1):
            package_questions = set(project_llm_question_ids(package))
            if package_questions and package_questions.issubset(resume_question_ids):
                completed_batch_indices.add(batch_index)
        if not completed_batch_indices:
            raise ValueError("续跑草稿中没有完整的已完成批次，请重新开始调用")
        batch_results.append(resume_result)

    llm_responses = []
    attempted_calls = 0
    failed_batch_index = 0
    failed_error = ""
    resumed_batch_count = len(completed_batch_indices)
    for batch_index, package in enumerate(batch_packages, start=1):
        if batch_index in completed_batch_indices:
            continue
        batch_prompt = build_project_llm_prompt(
            package,
            output_schema,
            {
                "batch_index": batch_index,
                "batch_count": batch_count,
            },
        )
        attempted_calls += 1
        try:
            llm_response = call_llm_chat_completion(batch_prompt, llm_config)
            llm_responses.append(llm_response)
            batch_result = parse_project_llm_batch_response(
                llm_response,
                package,
                batch_index,
                batch_count,
            )
        except ValueError as exc:
            failed_batch_index = batch_index
            failed_error = truncate_text(mask_secret_text(str(exc)), 1200)
            if not completed_batch_indices:
                raise ValueError(
                    f"第 {batch_index}/{batch_count} 批执行失败：{failed_error}"
                    "；系统未自动重试。"
                ) from exc
            break
        batch_results.append(batch_result)
        completed_batch_indices.add(batch_index)

    merged_result = merge_project_llm_batch_results(batch_results, input_package)
    result_text = json.dumps(merged_result, ensure_ascii=False, indent=2)
    validation = db_validate_project_llm_analysis_payload(
        project_id,
        {
            "result_text": result_text,
            "limit": limit,
        },
        sample_ids=sample_ids,
    )

    prior_usage = resume_llm_meta.get("usage") if resume_llm_meta else {}
    usage = merge_llm_usage(
        prior_usage,
        *(response.get("usage") for response in llm_responses),
    )
    prior_finish_reasons = resume_llm_meta.get("finish_reasons") or []
    if isinstance(prior_finish_reasons, str):
        prior_finish_reasons = [prior_finish_reasons]
    finish_reasons = [
        str(value).strip()
        for value in list(prior_finish_reasons)
        + [response.get("finish_reason", "") for response in llm_responses]
        if str(value or "").strip()
    ]
    provider = next(
        (
            response.get("provider", "")
            for response in reversed(llm_responses)
            if response.get("provider")
        ),
        resume_llm_meta.get("provider", ""),
    )
    model = next(
        (
            response.get("model", "")
            for response in reversed(llm_responses)
            if response.get("model")
        ),
        resume_llm_meta.get("model", ""),
    )
    completed_question_ids = set()
    for batch_index in completed_batch_indices:
        completed_question_ids.update(
            project_llm_question_ids(batch_packages[batch_index - 1])
        )
    execution_status = "partial_failed" if failed_error else "completed"
    execution = {
        **project_llm_execution_metadata(input_package),
        "status": execution_status,
        "completed_batches": len(completed_batch_indices),
        "completed_question_count": len(completed_question_ids),
        "remaining_batch_count": batch_count - len(completed_batch_indices),
        "failed_batch": failed_batch_index,
        "last_error": failed_error,
        "calls_this_request": attempted_calls,
        "resumed_batches": resumed_batch_count,
        "can_resume": bool(failed_error and completed_batch_indices),
    }
    if failed_error:
        validation = validation_with_execution_error(
            validation,
            failed_error,
        )

    return {
        "ok": True,
        "project": brief.get("project"),
        "result_text": result_text,
        "validation": validation,
        "summary": validation.get("summary") if validation else {},
        "checks": validation.get("checks") if validation else {},
        "llm": {
            "provider": provider,
            "model": model,
            "usage": usage,
            "result_chars": len(result_text),
            "batch_count": batch_count,
            "completed_batches": len(completed_batch_indices),
            "finish_reasons": finish_reasons,
            "automatic_retry": False,
        },
        "execution": execution,
        "source": "llm_api",
    }


def validate_report_polish_result(result_obj):
    errors = []
    if not isinstance(result_obj, dict):
        raise ValueError("报告润色结果必须是 JSON 对象")

    def normalized_string(key, max_chars=800):
        value = result_obj.get(key)
        if not isinstance(value, str) or not value.strip():
            errors.append(f"{key} 必须是非空字符串")
            return ""
        return truncate_for_llm(value.strip(), max_chars)

    def normalized_list(key, max_items=5, max_chars=180):
        value = result_obj.get(key)
        if not isinstance(value, list):
            errors.append(f"{key} 必须是数组")
            return []
        rows = []
        for item in value[:max_items]:
            text = str(item or "").strip()
            if text:
                rows.append(truncate_for_llm(text, max_chars))
        if not rows:
            errors.append(f"{key} 至少需要 1 条内容")
        return rows

    normalized = {
        "executive_summary": normalized_string("executive_summary", 520),
        "key_findings": normalized_list("key_findings", 5, 220),
        "recommendation_summary": normalized_string("recommendation_summary", 700),
        "next_actions": normalized_list("next_actions", 5, 220),
        "caveats": normalized_list("caveats", 3, 220),
    }
    if errors:
        raise ValueError("报告润色结果格式错误：" + "；".join(errors))
    return normalized


def identify_report_section_id(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    normalized = raw.casefold()
    matches = set()
    for index, (section_id, section_title) in enumerate(REPORT_SECTION_LABELS.items(), start=1):
        if normalized == section_id.casefold() or raw == section_title:
            matches.add(section_id)
            continue
        if re.search(rf"(?<![a-z0-9_]){re.escape(section_id.casefold())}(?![a-z0-9_])", normalized):
            matches.add(section_id)
        if section_title in raw:
            matches.add(section_id)
        number_match = re.match(r"^\s*(?:#+\s*)?(\d+)\s*(?:[.、:：\-]|$)", raw)
        if number_match and int(number_match.group(1)) == index:
            matches.add(section_id)
    return next(iter(matches)) if len(matches) == 1 else ""


def validate_report_section_polish_result(result_obj, expected_section_id):
    if not isinstance(result_obj, dict):
        raise ValueError("章节润色结果必须是 JSON 对象")
    if expected_section_id not in REPORT_SECTION_LABELS:
        raise ValueError("请求的报告章节无效")
    # section_id is transport metadata, not model-authored business content. The
    # requested section remains authoritative so an otherwise valid response is
    # not rejected when a model echoes a translated title or a stale identifier.
    returned_section_id = identify_report_section_id(result_obj.get("section_id"))
    section_markdown = str(result_obj.get("section_markdown") or "").strip()
    if not section_markdown:
        raise ValueError("章节润色结果缺少 section_markdown")
    caveats = result_obj.get("caveats")
    if not isinstance(caveats, list):
        raise ValueError("章节润色结果的 caveats 必须是数组")
    return {
        "section_id": expected_section_id,
        "section_title": REPORT_SECTION_LABELS[expected_section_id],
        "section_markdown": truncate_for_llm(section_markdown, 10000),
        "change_summary": truncate_for_llm(str(result_obj.get("change_summary") or "已优化章节表达").strip(), 400),
        "caveats": [truncate_for_llm(str(item).strip(), 220) for item in caveats[:3] if str(item).strip()],
        "section_id_normalized": bool(returned_section_id and returned_section_id != expected_section_id),
    }


def db_run_project_report_polish_payload(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    report_type = str(payload.get("report_type", "internal") or "internal").strip()
    if report_type not in {"internal", "client", "weekly"}:
        report_type = "internal"
    section_id = str(payload.get("section_id") or "").strip()
    if section_id and section_id not in REPORT_SECTION_LABELS:
        raise ValueError("Unknown report section_id")
    report_markdown = str(
        (payload.get("section_markdown") if section_id else payload.get("report_markdown", ""))
        or ""
    ).strip()
    if not report_markdown:
        raise ValueError("当前报告章节内容为空，无法润色" if section_id else "当前报告内容为空，无法润色")

    with db_connect() as conn:
        project = db_project_detail(conn, project_id)
    if not project:
        return None

    llm_config = llm_api_config(include_secret=True)
    if not llm_config.get("configured"):
        missing = "、".join(llm_config.get("missing") or ["LLM API 配置"])
        raise ValueError(f"LLM API 尚未配置完整：缺少 {missing}")

    prompt = (
        build_report_section_polish_prompt(
            project,
            report_type,
            section_id,
            report_markdown,
            payload.get("evidence_context") or {},
        )
        if section_id
        else build_report_polish_prompt(project, report_type, report_markdown)
    )
    llm_response = call_llm_chat_completion(prompt, llm_config)
    result_text = llm_response["content"]
    try:
        result_obj = json.loads(extract_json_text(result_text))
    except json.JSONDecodeError as exc:
        raise ValueError(f"报告润色结果不是合法 JSON：{exc}") from exc
    normalized = (
        validate_report_section_polish_result(result_obj, section_id)
        if section_id
        else validate_report_polish_result(result_obj)
    )
    return {
        "ok": True,
        "project": project,
        "report_type": report_type,
        "section_id": section_id,
        "result": normalized,
        "result_text": json.dumps(normalized, ensure_ascii=False, indent=2),
        "llm": {
            "provider": llm_response.get("provider", ""),
            "model": llm_response.get("model", ""),
            "usage": llm_response.get("usage", {}),
            "result_chars": len(result_text),
        },
        "source": "llm_api",
    }


def safe_filename_segment(value, fallback="report"):
    text = str(value or "").strip() or fallback
    text = re.sub(r'[\\/:*?"<>|\r\n\t]+', "-", text)
    text = re.sub(r"\s+", "-", text).strip("-")
    return (text or fallback)[:80]


def clean_pdf_text(value, max_chars=12000):
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    text = re.sub(r"\n{4,}", "\n\n\n", text)
    return text[:max_chars]


def markdown_table_cells(line):
    text = str(line or "").strip()
    if not (text.startswith("|") and text.endswith("|")):
        return None
    if re.fullmatch(r"\|[\s:\-|]+\|", text):
        return []
    cells = [cell.strip() for cell in text.strip("|").split("|")]
    return cells if any(cells) else []


def markdown_to_pdf_blocks(markdown_text):
    blocks = []
    table_rows = []

    def flush_table():
        nonlocal table_rows
        if table_rows:
            blocks.append({"type": "table", "rows": table_rows})
            table_rows = []

    for raw_line in clean_pdf_text(markdown_text, max_chars=60000).split("\n"):
        line = raw_line.strip()
        cells = markdown_table_cells(line)
        if cells is not None:
            if cells:
                table_rows.append(cells)
            continue
        flush_table()
        if not line:
            blocks.append({"type": "space"})
            continue
        heading = re.match(r"^(#{1,4})\s+(.+)$", line)
        if heading:
            blocks.append({
                "type": "heading",
                "level": len(heading.group(1)),
                "text": heading.group(2).strip(),
            })
            continue
        bullet = re.match(r"^[-*]\s+(.+)$", line)
        numbered = re.match(r"^\d+\.\s+(.+)$", line)
        if bullet or numbered:
            blocks.append({"type": "bullet", "text": (bullet or numbered).group(1).strip()})
            continue
        blocks.append({"type": "paragraph", "text": line})
    flush_table()
    return blocks


def pdf_font_candidates():
    windows_fonts = Path(os.environ.get("WINDIR", r"C:\Windows")) / "Fonts"
    return [
        windows_fonts / "msyh.ttc",
        windows_fonts / "msyh.ttf",
        windows_fonts / "msyhbd.ttc",
        windows_fonts / "simhei.ttf",
        windows_fonts / "simsun.ttc",
        windows_fonts / "simkai.ttf",
    ]


def register_reportlab_font():
    try:
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
    except Exception:
        return "Helvetica"
    for path in pdf_font_candidates():
        if not path.exists():
            continue
        try:
            pdfmetrics.registerFont(TTFont("GeoAgentCJK", str(path)))
            return "GeoAgentCJK"
        except Exception:
            continue
    # A standard CJK CID font works on Linux without bundling proprietary fonts.
    try:
        from reportlab.pdfbase.cidfonts import UnicodeCIDFont
        pdfmetrics.registerFont(UnicodeCIDFont("STSong-Light"))
        return "STSong-Light"
    except Exception:
        return "Helvetica"


def reportlab_available():
    try:
        import reportlab  # noqa: F401
        return True
    except Exception:
        return False


def report_branding_context(project):
    project = project or {}
    cached = project.get("_report_branding")
    if isinstance(cached, dict):
        return cached
    customer_id = str(project.get("customer_id") or "").strip()
    display_name = str(project.get("customer_name") or project.get("customer") or "当前客户").strip()
    context = {
        "display_name": display_name,
        "logo_path": "",
        "logo_mime": "",
    }
    if not customer_id:
        return context
    with db_connect() as conn:
        ensure_report_center_tables(conn)
        row = conn.execute(
            "SELECT * FROM customer_brand_assets WHERE customer_id = ?",
            (customer_id,),
        ).fetchone()
    if not row:
        return context
    brand = db_row_to_dict(row)
    context["display_name"] = str(brand.get("display_name") or display_name).strip()
    relative_path = str(brand.get("logo_path") or "").strip()
    if not relative_path:
        return context
    path = (ROOT / relative_path).resolve()
    try:
        path.relative_to(CUSTOMER_BRAND_ROOT.resolve())
    except ValueError:
        return context
    if path.exists() and path.is_file():
        context["logo_path"] = str(path)
        context["logo_mime"] = str(brand.get("logo_mime") or mimetypes.guess_type(path.name)[0] or "image/png")
    return context


def report_logo_data_uri(branding):
    logo_path = str((branding or {}).get("logo_path") or "").strip()
    if not logo_path:
        return ""
    path = Path(logo_path)
    if not path.exists() or not path.is_file():
        return ""
    mime_type = str((branding or {}).get("logo_mime") or mimetypes.guess_type(path.name)[0] or "image/png")
    return f"data:{mime_type};base64,{base64.b64encode(path.read_bytes()).decode('ascii')}"


def generate_report_pdf_with_reportlab(payload, project):
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_CENTER, TA_LEFT
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import cm
    from reportlab.lib.utils import ImageReader
    from reportlab.platypus import Image, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle

    title = str(payload.get("title") or "GEO 可见度诊断报告").strip()
    executive_summary = str(payload.get("executive_summary") or "").strip()
    markdown_text = str(payload.get("markdown_text") or "").strip()
    report_type = normalize_report_type(payload.get("report_type"))
    customer_name = project.get("customer_name") or project.get("customer") or "当前客户"
    project_name = project.get("name") or "GEO 监测项目"
    branding = report_branding_context(project)
    brand_name = branding.get("display_name") or customer_name
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M")
    font_name = register_reportlab_font()
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=1.55 * cm,
        leftMargin=1.55 * cm,
        topMargin=1.45 * cm,
        bottomMargin=1.35 * cm,
        title=title,
        author="GEO Agent",
    )
    base_styles = getSampleStyleSheet()

    def style(name, size, leading, color="#172033", bold=False, alignment=TA_LEFT, space_after=5):
        return ParagraphStyle(
            name,
            parent=base_styles["Normal"],
            fontName=font_name,
            fontSize=size,
            leading=leading,
            textColor=colors.HexColor(color),
            alignment=alignment,
            spaceAfter=space_after,
        )

    styles = {
        "title": style("GeoTitle", 22, 29, "#0f172a", alignment=TA_CENTER, space_after=10),
        "meta": style("GeoMeta", 8.5, 12, "#64748b", alignment=TA_CENTER, space_after=8),
        "summary": style("GeoSummary", 10.5, 17, "#334155", space_after=8),
        "h1": style("GeoH1", 15, 21, "#0f172a", space_after=7),
        "h2": style("GeoH2", 12.5, 18, "#153e75", space_after=5),
        "body": style("GeoBody", 9.8, 15, "#1f2937", space_after=5),
        "bullet": style("GeoBullet", 9.5, 14, "#1f2937", space_after=4),
        "cell": style("GeoCell", 8.1, 11, "#1f2937", space_after=0),
        "cell_head": style("GeoCellHead", 8.2, 11, "#0f172a", space_after=0),
        "brand": style("GeoBrand", 11, 15, "#0f172a", space_after=0),
        "delivery": style("GeoDelivery", 8, 11, "#15803d", alignment=TA_CENTER, space_after=0),
    }

    brand_flowable = Paragraph(html_lib.escape(brand_name), styles["brand"])
    logo_path = str(branding.get("logo_path") or "")
    if logo_path:
        try:
            brand_flowable = Image(logo_path)
            max_width, max_height = 5.2 * cm, 1.25 * cm
            scale = min(max_width / brand_flowable.imageWidth, max_height / brand_flowable.imageHeight)
            brand_flowable.drawWidth = brand_flowable.imageWidth * scale
            brand_flowable.drawHeight = brand_flowable.imageHeight * scale
        except Exception:
            brand_flowable = Paragraph(html_lib.escape(brand_name), styles["brand"])

    brand_header = Table(
        [[brand_flowable, Paragraph("正式交付", styles["delivery"])]],
        colWidths=[14.8 * cm, 2.8 * cm],
        style=[
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ALIGN", (1, 0), (1, 0), "RIGHT"),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 12),
        ],
    )

    story = [
        brand_header,
        Paragraph(html_lib.escape(title), styles["title"]),
        Paragraph(
            html_lib.escape(f"{customer_name} · {project_name} · {report_type} · {timestamp}"),
            styles["meta"],
        ),
    ]
    if executive_summary:
        story.extend([
            Table(
                [[Paragraph(html_lib.escape(executive_summary), styles["summary"])]],
                colWidths=[17.6 * cm],
                style=[
                    ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#f8fafc")),
                    ("BOX", (0, 0), (-1, -1), 0.8, colors.HexColor("#dbe7f4")),
                    ("LEFTPADDING", (0, 0), (-1, -1), 10),
                    ("RIGHTPADDING", (0, 0), (-1, -1), 10),
                    ("TOPPADDING", (0, 0), (-1, -1), 8),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 8),
                ],
            ),
            Spacer(1, 8),
        ])

    for block in markdown_to_pdf_blocks(markdown_text):
        block_type = block["type"]
        if block_type == "space":
            story.append(Spacer(1, 4))
        elif block_type == "heading":
            level = int(block.get("level") or 2)
            story.append(Paragraph(html_lib.escape(block.get("text", "")), styles["h1" if level <= 2 else "h2"]))
        elif block_type == "bullet":
            story.append(Paragraph("• " + html_lib.escape(block.get("text", "")), styles["bullet"]))
        elif block_type == "table":
            rows = block.get("rows") or []
            if not rows:
                continue
            max_cols = max(len(row) for row in rows)
            normalized_rows = [
                row + [""] * (max_cols - len(row))
                for row in rows[:24]
            ]
            table_data = []
            for row_index, row in enumerate(normalized_rows):
                row_style = styles["cell_head"] if row_index == 0 else styles["cell"]
                table_data.append([Paragraph(html_lib.escape(cell), row_style) for cell in row])
            available_width = 17.6 * cm
            col_widths = [available_width / max_cols] * max_cols
            table = Table(table_data, colWidths=col_widths, repeatRows=1 if len(table_data) > 1 else 0)
            table.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#eaf3ff")),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#0f172a")),
                ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#d6e2ef")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("LEFTPADDING", (0, 0), (-1, -1), 5),
                ("RIGHTPADDING", (0, 0), (-1, -1), 5),
                ("TOPPADDING", (0, 0), (-1, -1), 4),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ]))
            story.extend([table, Spacer(1, 7)])
        else:
            story.append(Paragraph(html_lib.escape(block.get("text", "")), styles["body"]))

    story.append(Spacer(1, 8))
    story.append(Paragraph("报告结论基于已锁定的真实样本、题库、事实库和公开引用。", styles["meta"]))

    def draw_service_footer(canvas, document):
        canvas.saveState()
        canvas.setFont(font_name, 7.5)
        canvas.setFillColor(colors.HexColor("#64748b"))
        text_x = 1.55 * cm
        if FICTIONAL_SERVICE_LOGO.is_file():
            try:
                logo = ImageReader(str(FICTIONAL_SERVICE_LOGO))
                logo_width = 2.5 * cm
                logo_height = logo_width / (1006 / 216)
                canvas.drawImage(logo, 1.55 * cm, 0.48 * cm, width=logo_width, height=logo_height, preserveAspectRatio=True, mask="auto")
                text_x = 4.25 * cm
            except Exception:
                text_x = 1.55 * cm
        canvas.drawString(text_x, 0.72 * cm, "提供 GEO 可见度监测与诊断服务")
        canvas.drawRightString(A4[0] - 1.55 * cm, 0.72 * cm, f"第 {document.page} 页")
        canvas.restoreState()

    doc.build(story, onFirstPage=draw_service_footer, onLaterPages=draw_service_footer)
    return buffer.getvalue()


def markdown_to_delivery_html(payload, project):
    title = str(payload.get("title") or "GEO 可见度诊断报告").strip()
    executive_summary = str(payload.get("executive_summary") or "").strip()
    markdown_text = str(payload.get("markdown_text") or "").strip()
    report_type = normalize_report_type(payload.get("report_type"))
    customer_name = project.get("customer_name") or "当前客户"
    project_name = project.get("name") or "GEO 监测项目"
    branding = report_branding_context(project)
    brand_name = branding.get("display_name") or customer_name
    logo_data_uri = report_logo_data_uri(branding)
    service_logo_data_uri = (
        f"data:image/png;base64,{base64.b64encode(FICTIONAL_SERVICE_LOGO.read_bytes()).decode('ascii')}"
        if FICTIONAL_SERVICE_LOGO.is_file() else ""
    )
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M")
    brand_html = (
        f"<img src='{logo_data_uri}' alt='{html_lib.escape(brand_name)}'>"
        if logo_data_uri
        else f"<strong>{html_lib.escape(brand_name)}</strong>"
    )
    html_parts = [
        "<!doctype html><html><head><meta charset='utf-8'>",
        "<style>",
        "@page{size:A4;margin:18mm 16mm 20mm;}body{font-family:'Microsoft YaHei UI','Microsoft YaHei','PingFang SC',Arial,sans-serif;color:#172033;line-height:1.62;font-size:13px;}h1{font-size:28px;text-align:center;margin:0 0 8px;}h2{font-size:19px;margin:22px 0 8px;color:#0f172a;}h3{font-size:16px;margin:16px 0 6px;color:#153e75;}p{margin:6px 0;}ul{padding-left:20px;}li{margin:4px 0;}table{width:100%;border-collapse:collapse;margin:10px 0 14px;}th,td{border:1px solid #d6e2ef;padding:7px 8px;vertical-align:top;}tr:first-child{background:#eaf3ff;font-weight:700}.brand{display:flex;align-items:center;justify-content:space-between;min-height:44px;margin-bottom:18px}.brand img{max-width:190px;max-height:44px;object-fit:contain}.brand strong{font-size:16px}.delivery{color:#15803d;font-size:11px;font-weight:700}.meta{text-align:center;color:#64748b;font-size:12px}.summary{background:#f8fafc;border:1px solid #dbe7f4;border-radius:8px;padding:12px 14px;margin:14px 0 18px}.footer{position:fixed;left:0;right:0;bottom:-14mm;height:10mm;display:flex;align-items:center;justify-content:center;gap:9px;color:#64748b;text-align:center;font-size:10px}.footer img{width:78px;height:18px;object-fit:contain}",
        "</style></head><body>",
        f"<div class='brand'><div>{brand_html}</div><span class='delivery'>正式交付</span></div>",
        f"<h1>{html_lib.escape(title)}</h1>",
        f"<p class='meta'>{html_lib.escape(customer_name)} · {html_lib.escape(project_name)} · {html_lib.escape(report_type)} · {html_lib.escape(timestamp)}</p>",
    ]
    if executive_summary:
        html_parts.append(f"<div class='summary'>{html_lib.escape(executive_summary)}</div>")
    table_rows = []

    def flush_table():
        nonlocal table_rows
        if not table_rows:
            return
        html_parts.append("<table>")
        for row in table_rows:
            html_parts.append("<tr>" + "".join(f"<td>{html_lib.escape(cell)}</td>" for cell in row) + "</tr>")
        html_parts.append("</table>")
        table_rows = []

    for block in markdown_to_pdf_blocks(markdown_text):
        if block["type"] != "table":
            flush_table()
        if block["type"] == "heading":
            level = "h2" if int(block.get("level") or 2) <= 2 else "h3"
            html_parts.append(f"<{level}>{html_lib.escape(block.get('text', ''))}</{level}>")
        elif block["type"] == "paragraph":
            html_parts.append(f"<p>{html_lib.escape(block.get('text', ''))}</p>")
        elif block["type"] == "bullet":
            html_parts.append(f"<ul><li>{html_lib.escape(block.get('text', ''))}</li></ul>")
        elif block["type"] == "table":
            table_rows.extend(block.get("rows") or [])
        elif block["type"] == "space":
            html_parts.append("<br>")
    flush_table()
    service_logo_html = f"<img src='{service_logo_data_uri}' alt='星舟创意（虚构）'>" if service_logo_data_uri else "<strong>星舟创意（虚构）</strong>"
    html_parts.append(f"<div class='footer'>{service_logo_html}<span>提供 GEO 可见度监测与诊断服务</span></div></body></html>")
    return "\n".join(html_parts)


def find_chrome_executable():
    candidates = [
        os.environ.get("CHROME_PATH", ""),
        r"C:\Program Files\Google\Chrome\Application\chrome.exe",
        r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
        r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
        r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
    ]
    for candidate in candidates:
        if candidate and Path(candidate).exists():
            return str(candidate)
    return shutil.which("chrome") or shutil.which("msedge") or ""


def generate_report_pdf_with_chrome(payload, project):
    chrome = find_chrome_executable()
    if not chrome:
        raise ValueError("当前环境缺少 reportlab，也未找到 Chrome/Edge，无法生成 PDF")
    html = markdown_to_delivery_html(payload, project)
    with tempfile.TemporaryDirectory(prefix="geo-report-pdf-") as temp_dir:
        temp_path = Path(temp_dir)
        html_file = temp_path / "report.html"
        pdf_file = temp_path / "report.pdf"
        html_file.write_text(html, encoding="utf-8")
        command = [
            chrome,
            "--headless=new",
            "--disable-gpu",
            "--no-first-run",
            "--no-default-browser-check",
            "--no-pdf-header-footer",
            f"--print-to-pdf={pdf_file}",
            f"file:///{html_file.as_posix()}",
        ]
        subprocess.run(command, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=60)
        if not pdf_file.exists() or pdf_file.stat().st_size < 100:
            raise ValueError("PDF 生成失败：未输出有效文件")
        return pdf_file.read_bytes()


def generate_report_pdf_bytes(payload, project):
    if reportlab_available():
        try:
            return generate_report_pdf_with_reportlab(payload, project), "reportlab"
        except Exception:
            # Fall back to browser PDF when ReportLab is installed but font/layout fails.
            return generate_report_pdf_with_chrome(payload, project), "chrome"
    return generate_report_pdf_with_chrome(payload, project), "chrome"


def db_project_report_pdf_payload(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    markdown_text = str(payload.get("markdown_text") or "").strip()
    if not markdown_text:
        raise ValueError("当前报告内容为空，无法生成 PDF")
    with db_connect() as conn:
        project = db_project_detail(conn, project_id)
    if not project:
        return None
    pdf_bytes, engine = generate_report_pdf_bytes(payload, project)
    report_type = normalize_report_type(payload.get("report_type"))
    customer_name = project.get("customer_name") or payload.get("customer_name") or "客户"
    platform = project.get("platform") or "GEO"
    filename = "-".join([
        safe_filename_segment(customer_name, "客户"),
        safe_filename_segment(platform, "GEO"),
        safe_filename_segment(report_type, "report"),
        datetime.now().strftime("%Y%m%d-%H%M"),
    ]) + ".pdf"
    return {
        "project": project,
        "filename": filename,
        "pdf_bytes": pdf_bytes,
        "engine": engine,
    }


def parse_llm_result_object(payload):
    payload = payload or {}
    result_obj = payload.get("result_json")
    raw_text = payload.get("result_text", "")
    if isinstance(result_obj, str):
        raw_text = result_obj
        result_obj = None
    if result_obj is not None:
        return result_obj
    json_text = extract_json_text(raw_text)
    if not json_text:
        raise ValueError("请先粘贴 LLM 返回的 JSON")
    return json.loads(json_text)


def llm_conflict_decision_key(question_id, field, rules_value, llm_value):
    return (
        str(question_id or ""),
        str(field or ""),
        json.dumps(rules_value, ensure_ascii=False, sort_keys=True),
        json.dumps(llm_value, ensure_ascii=False, sort_keys=True),
    )


def llm_review_decision_items(payload):
    raw_decisions = payload.get("review_decisions", []) if isinstance(payload, dict) else []
    if isinstance(raw_decisions, dict):
        raw_decisions = raw_decisions.values()
    return [item for item in (raw_decisions or []) if isinstance(item, dict)]


def normalize_llm_review_decisions(payload):
    decision_by_key = {}
    for item in llm_review_decision_items(payload):
        action = str(item.get("action", "")).strip()
        if action not in {"adopt_llm", "keep_rules"}:
            continue
        key = llm_conflict_decision_key(
            item.get("question_id", ""),
            item.get("field", ""),
            item.get("rules_value"),
            item.get("llm_value"),
        )
        decision_by_key[key] = action
    return decision_by_key


def normalize_llm_question_review_actions(payload):
    """Read question-level choices from the existing review_decisions envelope."""

    actions = {}
    rejected = set()
    audit_rows = []
    for item in llm_review_decision_items(payload):
        question_id = str(item.get("question_id", "")).strip()
        field = str(item.get("field", "")).strip()
        action = str(item.get("action", "")).strip()
        if not question_id:
            continue
        if field == LLM_REVIEW_REJECTED_FIELD and action == "keep_rules":
            rejected.add(question_id)
            audit_rows.append(
                {
                    "question_id": question_id,
                    "field": LLM_REVIEW_REJECTED_FIELD,
                    "rules_value": item.get("rules_value"),
                    "llm_value": item.get("llm_value"),
                    "message": "本题已由人工打回，不进入本次确认",
                    "action": "keep_rules",
                }
            )
        elif (
            field == LLM_REVIEW_QUESTION_CHOICE_FIELD
            and action in {"adopt_llm", "keep_rules"}
        ):
            actions[question_id] = action
            audit_rows.append(
                {
                    "question_id": question_id,
                    "field": LLM_REVIEW_QUESTION_CHOICE_FIELD,
                    "rules_value": item.get("rules_value"),
                    "llm_value": item.get("llm_value"),
                    "message": "逐题复核人工裁决",
                    "action": action,
                }
            )
    for question_id in rejected:
        actions.pop(question_id, None)
    return actions, rejected, audit_rows


def apply_llm_review_decisions(analyses, conflicts, baseline_by_question, decision_by_key):
    analysis_by_question = {
        str(item.get("question_id", "")).strip(): item
        for item in analyses
        if isinstance(item, dict) and str(item.get("question_id", "")).strip()
    }
    unresolved = []
    applied = []
    for conflict in conflicts:
        key = llm_conflict_decision_key(
            conflict.get("question_id", ""),
            conflict.get("field", ""),
            conflict.get("rules_value"),
            conflict.get("llm_value"),
        )
        action = decision_by_key.get(key)
        if action not in {"adopt_llm", "keep_rules"}:
            unresolved.append(conflict)
            continue
        question_id = str(conflict.get("question_id", "")).strip()
        field = str(conflict.get("field", "")).strip()
        if action == "keep_rules" and question_id in analysis_by_question:
            baseline = baseline_by_question.get(question_id) or {}
            if field in {"brand_mentioned", "brand_recommended", "risk_level"} and field in baseline:
                analysis_by_question[question_id][field] = baseline[field]
        applied.append({**conflict, "action": action})
    return unresolved, applied


def apply_llm_question_review_actions(
    analyses,
    baseline_by_question,
    question_actions,
):
    analysis_by_question = {
        str(item.get("question_id", "")).strip(): item
        for item in analyses
        if isinstance(item, dict) and str(item.get("question_id", "")).strip()
    }
    baseline_fields = (
        "brand_mentioned",
        "brand_recommended",
        "risk_level",
        "competitors",
        "accurate_claims",
        "unverified_claims",
        "high_risk_hallucinations",
        "positioning_drift",
        "recommended_fix",
    )
    for question_id, action in question_actions.items():
        if action != "keep_rules" or question_id not in analysis_by_question:
            continue
        baseline = baseline_by_question.get(question_id) or {}
        for field in baseline_fields:
            if field in baseline:
                analysis_by_question[question_id][field] = copy.deepcopy(baseline[field])


def filter_llm_recommendations_for_rejected_questions(recommendations, rejected):
    if not rejected:
        return recommendations
    filtered = []
    for item in recommendations:
        if not isinstance(item, dict):
            filtered.append(item)
            continue
        candidate = copy.deepcopy(item)
        raw_targets = candidate.get("target_questions")
        if isinstance(raw_targets, list):
            remaining = [
                str(question_id).strip()
                for question_id in raw_targets
                if str(question_id).strip()
                and str(question_id).strip() not in rejected
            ]
            if raw_targets and not remaining:
                continue
            candidate["target_questions"] = remaining
        evidence = candidate.get("evidence")
        if isinstance(evidence, list):
            candidate["evidence"] = [
                value
                for value in evidence
                if str(value or "").strip() not in rejected
            ]
        filtered.append(candidate)
    return filtered


def llm_recommendation_target_questions(item, sample_by_question=None):
    sample_by_question = sample_by_question or {}
    values = []
    for value in item.get("target_questions", []) or []:
        question_id = str(value).strip()
        if not question_id:
            continue
        if sample_by_question and question_id not in sample_by_question:
            continue
        if question_id not in values:
            values.append(question_id)
    return values[:5]


def llm_recommendation_required_facts(item):
    return [
        str(value).strip()
        for value in (item.get("required_facts_to_confirm", []) or [])
        if str(value).strip()
    ][:8]


def llm_recommendation_content_brief(item):
    return str(item.get("content_brief", "") or "").strip()


def llm_recommendation_implementation_plan(item):
    def string_list(name, limit=10):
        value = item.get(name) or []
        if not isinstance(value, list):
            value = [value]
        return [str(entry).strip() for entry in value if str(entry).strip()][:limit]

    return {
        "asset_type": str(item.get("asset_type") or item.get("category") or "内容资产").strip(),
        "impacted_scenes": string_list("impacted_scenes", 4),
        "deliverables": string_list("deliverables"),
        "content_outline": string_list("content_outline"),
        "required_facts": llm_recommendation_required_facts(item),
        "source_strategy": string_list("source_strategy"),
        "acceptance_criteria": string_list("acceptance_criteria"),
        "target_questions": [str(value).strip() for value in (item.get("target_questions") or []) if str(value).strip()][:8],
        "retest_plan": str(item.get("retest_plan") or "").strip(),
        "limitations": string_list("limitations"),
    }


def llm_recommendation_action_text(item, include_details=True):
    action = str(item.get("action", "")).strip()
    if not include_details:
        return action
    content_brief = llm_recommendation_content_brief(item)
    required_facts = llm_recommendation_required_facts(item)
    parts = [action] if action else []
    if content_brief:
        parts.append(f"内容 brief：{content_brief}")
    if required_facts:
        parts.append("需客户确认：" + "；".join(required_facts[:5]))
    return "\n".join(parts).strip()


def db_confirm_project_llm_analysis_payload(
    project_id,
    payload,
    *,
    sample_ids=None,
    confirmation_mode="human",
):
    project_id = unquote(str(project_id or "").strip())
    payload = payload or {}
    confirmation_mode = str(confirmation_mode or "human").strip()
    automation_confirmation = confirmation_mode == "automation_llm_first"
    recommendation_generator = (
        LLM_AUTOMATION_RECOMMENDATION_GENERATOR
        if automation_confirmation
        else LLM_CONFIRMED_RECOMMENDATION_GENERATOR
    )
    recommendation_validation_status = (
        "auto_confirmed_llm_first"
        if automation_confirmation
        else "human_confirmed"
    )
    limit = parse_bounded_int(
        payload.get("limit"),
        default=ANALYSIS_REVIEW_MAX_SAMPLES,
        minimum=1,
        maximum=ANALYSIS_REVIEW_MAX_SAMPLES,
    )
    validation = db_validate_project_llm_analysis_payload(
        project_id,
        payload,
        sample_ids=sample_ids,
    )
    if validation is None:
        return None
    if not validation.get("accepted_for_review"):
        raise ValueError("LLM 结果仍有格式错误，不能确认落库")

    question_actions, requested_rejected, question_audit_rows = (
        normalize_llm_question_review_actions(payload)
    )
    summary = validation.get("summary", {})
    expected_count = int(summary.get("expected_questions") or 0)
    analysis_count = int(summary.get("analysis_count") or 0)
    validation_checks = validation.get("checks", {})
    expected_questions = {
        str(value or "").strip()
        for value in (validation_checks.get("expected_questions") or [])
        if str(value or "").strip()
    }
    seen_questions = {
        str(value or "").strip()
        for value in (validation_checks.get("seen_questions") or [])
        if str(value or "").strip()
    }
    rejected_questions = (
        requested_rejected & expected_questions
        if expected_questions
        else set(requested_rejected)
    )
    if expected_questions:
        accepted_expected = expected_questions - rejected_questions
        accepted_seen = seen_questions - rejected_questions
        if not accepted_expected:
            raise ValueError("本次所有题目均已打回，没有可确认的分析结果")
        missing_accepted = sorted(accepted_expected - accepted_seen)
        if missing_accepted:
            raise ValueError(
                "LLM 结果覆盖不完整：以下未打回题目没有分析结果："
                + "、".join(missing_accepted)
            )
    else:
        if expected_count <= 0:
            raise ValueError("当前输入包没有可确认的采样问题")
        if analysis_count < expected_count:
            raise ValueError(
                f"LLM 结果覆盖不完整：当前 {analysis_count}/{expected_count}，"
                "请让 LLM 返回完整输入包问题后再确认落库"
            )

    result_obj = parse_llm_result_object(payload)
    if not isinstance(result_obj, dict):
        raise ValueError("LLM 返回结果顶层必须是对象")
    confirmed_result_obj = copy.deepcopy(result_obj)
    analyses = confirmed_result_obj.get("analyses") or []
    recommendations = confirmed_result_obj.get("recommendations") or []
    if not isinstance(analyses, list) or not isinstance(recommendations, list):
        raise ValueError("LLM 返回结果必须包含 analyses 和 recommendations 数组")

    brief = db_project_analysis_brief_payload(
        project_id,
        limit=limit,
        sample_ids=sample_ids,
    )
    if brief is None:
        return None
    samples = brief.get("input_package", {}).get("samples", [])
    sample_by_question = {
        sample.get("question_id"): sample
        for sample in samples
        if sample.get("question_id")
    }
    baseline_by_question = {
        sample.get("question_id"): sample.get("rules_baseline") or {}
        for sample in samples
        if sample.get("question_id")
    }
    rejected_questions &= set(sample_by_question)
    decision_by_key = normalize_llm_review_decisions(payload)
    conflicts = validation.get("checks", {}).get("conflicts", [])
    conflicts = [
        conflict
        for conflict in conflicts
        if str(conflict.get("question_id", "") or "").strip()
        not in rejected_questions
    ]
    unresolved, applied_decisions = apply_llm_review_decisions(
        analyses,
        conflicts,
        baseline_by_question,
        decision_by_key,
    )
    if unresolved:
        raise ValueError(f"还有 {len(unresolved)} 条 LLM/规则冲突没有最终选择，请先选择“采用 LLM”或“保留规则”")
    apply_llm_question_review_actions(
        analyses,
        baseline_by_question,
        question_actions,
    )
    accepted_analyses = [
        item
        for item in analyses
        if isinstance(item, dict)
        and str(item.get("question_id", "") or "").strip()
        not in rejected_questions
    ]
    if not accepted_analyses:
        raise ValueError("本次没有可确认的分析结果")
    recommendations = filter_llm_recommendations_for_rejected_questions(
        recommendations,
        rejected_questions,
    )
    confirmed_result_obj["analyses"] = accepted_analyses
    confirmed_result_obj["recommendations"] = recommendations
    accepted_sample_by_question = {
        question_id: sample
        for question_id, sample in sample_by_question.items()
        if question_id not in rejected_questions
    }
    applied_decisions.extend(
        row
        for row in question_audit_rows
        if row["question_id"] in sample_by_question
    )

    timestamp = now_iso()
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        ensure_recommendation_detail_fields(conn)
        ensure_retest_question_match_fields(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None

        saved_analyses = []
        for item in accepted_analyses:
            if not isinstance(item, dict):
                continue
            question_id = str(item.get("question_id", "")).strip()
            sample = sample_by_question.get(question_id)
            if not sample:
                continue
            analysis_id = f"analysis_{safe_db_token(project_id)}_{safe_db_token(question_id)}"
            conn.execute(
                """
                INSERT INTO analysis_results (
                  analysis_id, sample_id, project_id, question_id, brand_mentioned,
                  brand_recommended, risk_level, competitors_json, accurate_claims_json,
                  unverified_claims_json, high_risk_json, positioning_drift_json,
                  recommended_fix, analyzed_at, analyzer_version
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(analysis_id) DO UPDATE SET
                  sample_id = excluded.sample_id,
                  brand_mentioned = excluded.brand_mentioned,
                  brand_recommended = excluded.brand_recommended,
                  risk_level = excluded.risk_level,
                  competitors_json = excluded.competitors_json,
                  accurate_claims_json = excluded.accurate_claims_json,
                  unverified_claims_json = excluded.unverified_claims_json,
                  high_risk_json = excluded.high_risk_json,
                  positioning_drift_json = excluded.positioning_drift_json,
                  recommended_fix = excluded.recommended_fix,
                  analyzed_at = excluded.analyzed_at,
                  analyzer_version = excluded.analyzer_version
                """,
                (
                    analysis_id,
                    sample["sample_id"],
                    project_id,
                    question_id,
                    1 if item.get("brand_mentioned") else 0,
                    1 if item.get("brand_recommended") else 0,
                    item.get("risk_level", "中"),
                    json_dump(item.get("competitors", [])),
                    json_dump(item.get("accurate_claims", [])),
                    json_dump(item.get("unverified_claims", [])),
                    json_dump(item.get("high_risk_hallucinations", [])),
                    json_dump(item.get("positioning_drift", [])),
                    str(item.get("recommended_fix", "")),
                    timestamp,
                    LLM_CONFIRMED_ANALYZER_VERSION,
                ),
            )
            saved_analyses.append(
                {
                    "analysis_id": analysis_id,
                    "sample_id": sample["sample_id"],
                    "question_id": question_id,
                    "brand_mentioned": bool(item.get("brand_mentioned")),
                    "brand_recommended": bool(item.get("brand_recommended")),
                    "risk_level": item.get("risk_level", "中"),
                }
            )

        recommendation_ids = []
        for index, item in enumerate(recommendations, start=1):
            if not isinstance(item, dict):
                continue
            recommendation_id = f"rec_{safe_db_token(project_id)}_llm_{index:03d}"
            recommendation_ids.append(recommendation_id)
            target_questions = llm_recommendation_target_questions(
                item,
                accepted_sample_by_question,
            )
            required_facts = llm_recommendation_required_facts(item)
            content_brief = llm_recommendation_content_brief(item)
            generated_plan = llm_recommendation_implementation_plan(item)
            source_evidence = []
            for question_id in target_questions:
                sample = accepted_sample_by_question.get(question_id, {})
                for citation in sample.get("citations", []) or []:
                    if isinstance(citation, dict):
                        source_evidence.append({"question_id": question_id, **citation})
            action_text = llm_recommendation_action_text(item, include_details=False) or str(item.get("action", ""))
            existing_row = conn.execute(
                "SELECT * FROM recommendations WHERE project_id = ? AND recommendation_id = ?",
                (project_id, recommendation_id),
            ).fetchone()
            existing = db_row_to_dict(existing_row) or {}
            deliverables = task_draft_string_list(generated_plan.get("deliverables"), 10) or [""]
            generated_drafts = []
            for draft_index, deliverable in enumerate(deliverables, start=1):
                draft_title = str(item.get("title", "")).strip()
                if len(deliverables) > 1 and deliverable:
                    draft_title = f"{draft_title} · {deliverable}" if draft_title else deliverable
                generated_drafts.append(
                    generated_task_draft(
                        recommendation_id,
                        draft_index,
                        title=draft_title,
                        priority=item.get("priority", "P2"),
                        priority_reason=item.get("reason", ""),
                        target_question_ids=target_questions,
                        impacted_scenes=generated_plan.get("impacted_scenes"),
                        deliverable=deliverable,
                        execution_steps=generated_plan.get("content_outline") or [action_text],
                        required_materials_and_facts=required_facts,
                        content_requirements=generated_plan.get("content_outline") or [content_brief],
                        acceptance_criteria=generated_plan.get("acceptance_criteria"),
                        retest_plan=generated_plan.get("retest_plan", ""),
                        retest_question_ids=target_questions,
                        requires_confirmed_sources=bool(required_facts or generated_plan.get("source_strategy")),
                        confirmed_source_ids=item.get("confirmed_source_ids") or [],
                    )
                )
            implementation_plan = merge_generated_task_drafts(
                existing.get("implementation_plan"),
                generated_plan,
                generated_drafts,
            )
            conn.execute(
                """
                INSERT INTO recommendations (
                  recommendation_id, project_id, category, title, priority, reason,
                  action, owner, expected_impact, generator, validation_status,
                  approval_status, execution_status, content_brief,
                  target_questions_json, required_facts_json, implementation_plan_json,
                  source_evidence_json, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(recommendation_id) DO UPDATE SET
                  category = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.category ELSE excluded.category END,
                  title = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.title ELSE excluded.title END,
                  priority = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.priority ELSE excluded.priority END,
                  reason = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.reason ELSE excluded.reason END,
                  action = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.action ELSE excluded.action END,
                  owner = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.owner ELSE excluded.owner END,
                  expected_impact = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.expected_impact ELSE excluded.expected_impact END,
                  generator = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.generator ELSE excluded.generator END,
                  validation_status = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.validation_status ELSE excluded.validation_status END,
                  content_brief = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.content_brief ELSE excluded.content_brief END,
                  target_questions_json = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.target_questions_json ELSE excluded.target_questions_json END,
                  required_facts_json = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.required_facts_json ELSE excluded.required_facts_json END,
                  implementation_plan_json = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.implementation_plan_json ELSE excluded.implementation_plan_json END,
                  source_evidence_json = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.source_evidence_json ELSE excluded.source_evidence_json END,
                  updated_at = CASE WHEN recommendations.approval_status = 'approved' THEN recommendations.updated_at ELSE excluded.updated_at END
                """,
                (
                    recommendation_id,
                    project_id,
                    str(item.get("category", "LLM优化建议")),
                    str(item.get("title", "")),
                    str(item.get("priority", "P2")),
                    str(item.get("reason", "")),
                    action_text,
                    str(item.get("owner", "")),
                    str(item.get("expected_impact", "")),
                    recommendation_generator,
                    recommendation_validation_status,
                    "pending",
                    "not_started",
                    content_brief,
                    json_dump(target_questions),
                    json_dump(required_facts),
                    json.dumps(implementation_plan, ensure_ascii=False),
                    json_dump(source_evidence[:30]),
                    timestamp,
                    timestamp,
                ),
            )
            if str(existing.get("approval_status") or "") == "approved":
                continue
            conn.execute(
                "DELETE FROM recommendation_evidence WHERE recommendation_id = ?",
                (recommendation_id,),
            )
            evidence_values = [str(value) for value in (item.get("evidence", []) or [])]
            for question_id in target_questions:
                if question_id and question_id not in evidence_values:
                    evidence_values.append(question_id)
            for evidence_index, evidence in enumerate(evidence_values, start=1):
                evidence_text = str(evidence)
                question_id = evidence_text if re.fullmatch(r"Q\d+", evidence_text) else ""
                conn.execute(
                    """
                    INSERT INTO recommendation_evidence (
                      evidence_id, recommendation_id, sample_id, question_id,
                      evidence_text, created_at
                    ) VALUES (?, ?, ?, ?, ?, ?)
                    """,
                    (
                        f"evi_{safe_db_token(project_id)}_llm_{index:03d}_{evidence_index:03d}",
                        recommendation_id,
                        accepted_sample_by_question.get(question_id, {}).get("sample_id", ""),
                        question_id,
                        evidence_text,
                        timestamp,
                    ),
                )

        saved_action_task_count = 0
        llm_meta = payload.get("llm_meta") if isinstance(payload.get("llm_meta"), dict) else {}
        analysis_version = create_analysis_result_version(
            conn,
            project_id,
            brief,
            confirmed_result_obj,
            validation,
            applied_decisions,
            llm_meta,
            len(saved_analyses),
            len(recommendation_ids),
            saved_action_task_count,
            note=str(payload.get("note", "") or "LLM 分析确认写入"),
            source=(
                "automation_llm_first"
                if automation_confirmation
                else "llm_confirm"
            ),
        )
        conn.commit()

    return {
        "ok": True,
        "project": brief.get("project"),
        "summary": {
            "status": "saved",
            "saved_analysis_count": len(saved_analyses),
            "saved_recommendation_count": len(recommendation_ids),
            "saved_action_task_count": saved_action_task_count,
            "applied_decision_count": len(applied_decisions),
            "analyzer_version": LLM_CONFIRMED_ANALYZER_VERSION,
            "analysis_version_no": analysis_version.get("version_no") if analysis_version else 0,
        },
        "analysis_version": analysis_version,
        "validation": validation,
        "applied_decisions": applied_decisions,
        "results": saved_analyses,
        "source": "sqlite",
    }


TASK_DRAFT_LIST_FIELDS = (
    "target_question_ids",
    "impacted_scenes",
    "execution_steps",
    "required_materials_and_facts",
    "content_requirements",
    "acceptance_criteria",
    "retest_question_ids",
    "confirmed_source_ids",
)


def normalize_task_draft_payload(existing, payload, draft_id):
    existing = existing if isinstance(existing, dict) else {}
    payload = payload if isinstance(payload, dict) else {}

    def value(name, default=""):
        return payload[name] if name in payload else existing.get(name, default)

    priority = str(value("priority", "P2") or "P2").strip().upper()
    if priority not in {"P0", "P1", "P2"}:
        priority = "P2"
    draft = {
        **existing,
        "draft_id": draft_id,
        "status": str(existing.get("status") or "draft"),
        "title": str(value("title") or "").strip()[:200],
        "priority": priority,
        "priority_reason": str(value("priority_reason") or "").strip()[:1000],
        "deliverable": str(value("deliverable") or "").strip()[:1000],
        "retest_plan": str(value("retest_plan") or "").strip()[:1000],
        "owner": str(value("owner") or "").strip()[:100],
        "due_date": str(value("due_date") or "").strip()[:30],
        "requires_confirmed_sources": bool(value("requires_confirmed_sources", False)),
        "edited_by_human": True,
        "created_at": str(existing.get("created_at") or now_iso()),
        "updated_at": now_iso(),
    }
    for name in TASK_DRAFT_LIST_FIELDS:
        raw = value(name, [])
        if name in {"target_question_ids", "retest_question_ids"}:
            draft[name] = normalize_question_id_list(raw)
        else:
            draft[name] = task_draft_string_list(raw, 30)
    draft.setdefault("linked_action_task_id", "")
    return draft


def eligible_confirmed_source_ids(conn, project_id, source_ids):
    requested = task_draft_string_list(source_ids, 30)
    if not requested:
        return []
    placeholders = ",".join("?" for _ in requested)
    rows = conn.execute(
        f"""
        SELECT source_evidence_id, domain, verification_status, fetch_status
        FROM source_evidence
        WHERE project_id = ? AND source_evidence_id IN ({placeholders})
        """,
        [project_id, *requested],
    ).fetchall()
    eligible = []
    for row in rows:
        domain = str(row["domain"] or "").lower().strip()
        access_barrier = domain.startswith(("wappass.", "passport.", "captcha.", "accounts."))
        if (
            row["verification_status"] == "confirmed"
            and row["fetch_status"] == "accessible"
            and not access_barrier
        ):
            eligible.append(row["source_evidence_id"])
    return eligible


def task_draft_quality_check(conn, project_id, draft):
    missing = []
    if not str(draft.get("title") or "").strip():
        missing.append("清晰、易懂的任务标题")
    if not str(draft.get("priority_reason") or "").strip():
        missing.append("具体的优先级理由")
    target_ids = normalize_question_id_list(draft.get("target_question_ids"))
    impacted_scenes = task_draft_string_list(draft.get("impacted_scenes"), 10)
    if not target_ids and not impacted_scenes:
        missing.append("对应目标问题或适用场景")
    if not str(draft.get("deliverable") or "").strip():
        missing.append("一个独立可验收的交付物")
    if not task_draft_string_list(draft.get("execution_steps"), 20):
        missing.append("明确的执行步骤")
    if not task_draft_string_list(draft.get("required_materials_and_facts"), 20):
        missing.append("必须准备或人工确认的材料与事实")
    if not task_draft_string_list(draft.get("content_requirements"), 30):
        missing.append("内容结构或交付要求")
    if not task_draft_string_list(draft.get("acceptance_criteria"), 20):
        missing.append("人工验收标准")
    retest_ids = normalize_question_id_list(draft.get("retest_question_ids"))
    if not str(draft.get("retest_plan") or "").strip() or not retest_ids:
        missing.append("同题复测计划")

    invalid_question_ids = []
    if target_ids or retest_ids:
        all_question_ids = list(dict.fromkeys([*target_ids, *retest_ids]))
        placeholders = ",".join("?" for _ in all_question_ids)
        rows = conn.execute(
            f"""
            SELECT question_id
            FROM project_questions
            WHERE project_id = ?
              AND status = 'active'
              AND COALESCE(review_status, 'pending') = 'approved'
              AND question_id IN ({placeholders})
            """,
            [project_id, *all_question_ids],
        ).fetchall()
        known = {row["question_id"] for row in rows}
        invalid_question_ids = [question_id for question_id in all_question_ids if question_id not in known]
        if invalid_question_ids:
            missing.append("目标问题必须属于当前项目已审核启用题库")

    baseline_run_id = ""
    if retest_ids and not invalid_question_ids:
        baseline_run_id = best_retest_source_run_id(conn, project_id, retest_ids)
        if not baseline_run_id:
            missing.append("全部复测题在同一前序批次中的精确样本")

    confirmed_source_ids = eligible_confirmed_source_ids(
        conn,
        project_id,
        draft.get("confirmed_source_ids"),
    )
    if draft.get("requires_confirmed_sources") and not confirmed_source_ids:
        missing.append("涉及外部事实时所需的已确认信源")

    missing = list(dict.fromkeys(missing))
    return {
        "passed": not missing,
        "missing_fields": missing,
        "blocking_reasons": [f"缺少：{label}" for label in missing],
        "baseline_run_id": baseline_run_id,
        "eligible_confirmed_source_ids": confirmed_source_ids,
        "invalid_question_ids": invalid_question_ids,
    }


def recommendation_task_drafts(plan):
    if not isinstance(plan, dict) or not isinstance(plan.get("tasks"), list):
        return []
    return [item for item in plan["tasks"] if isinstance(item, dict)]


def deterministic_action_task_id(project_id, recommendation_id, draft_id):
    digest = hashlib.sha256(
        f"{project_id}|{recommendation_id}|{draft_id}".encode("utf-8")
    ).hexdigest()[:16]
    return f"act_{safe_db_token(project_id)}_{digest}"


def replace_recommendation_task_draft(plan, draft):
    plan = dict(plan) if isinstance(plan, dict) else {}
    tasks = recommendation_task_drafts(plan)
    replaced = False
    updated = []
    for item in tasks:
        if str(item.get("draft_id") or "") == str(draft.get("draft_id") or ""):
            updated.append(draft)
            replaced = True
        else:
            updated.append(item)
    if not replaced:
        updated.append(draft)
    plan["tasks"] = updated
    plan["task_center_version"] = 1
    return plan


def next_task_draft_id(recommendation_id, tasks):
    existing = {str(item.get("draft_id") or "") for item in tasks}
    index = 1
    while True:
        candidate = f"td_{safe_db_token(recommendation_id)}_{index:03d}"
        if candidate not in existing:
            return candidate
        index += 1


def db_save_recommendation_task_draft_payload(project_id, recommendation_id, payload):
    project_id = unquote(str(project_id or "").strip())
    recommendation_id = unquote(str(recommendation_id or "").strip())
    payload = payload if isinstance(payload, dict) else {}
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        row = conn.execute(
            "SELECT * FROM recommendations WHERE project_id = ? AND recommendation_id = ?",
            (project_id, recommendation_id),
        ).fetchone()
        if not row:
            raise ValueError(f"Unknown recommendation_id: {recommendation_id}")
        recommendation = db_row_to_dict(row)
        plan = recommendation.get("implementation_plan")
        plan = plan if isinstance(plan, dict) else {}
        tasks = recommendation_task_drafts(plan)
        draft_id = str(payload.get("draft_id") or "").strip()
        if draft_id and not re.fullmatch(r"[A-Za-z0-9_.:-]{1,160}", draft_id):
            raise ValueError("任务草稿 ID 格式不正确。")
        if not draft_id:
            draft_id = next_task_draft_id(recommendation_id, tasks)
        existing = next(
            (item for item in tasks if str(item.get("draft_id") or "") == draft_id),
            {},
        )
        linked_action_task_id = str(existing.get("linked_action_task_id") or "")
        linked_task = None
        if linked_action_task_id:
            linked_task = conn.execute(
                "SELECT * FROM action_tasks WHERE project_id = ? AND action_task_id = ?",
                (project_id, linked_action_task_id),
            ).fetchone()
            if linked_task and (
                normalize_action_task_status(linked_task["status"]) != "todo"
                or str(linked_task["started_at"] or "").strip()
            ):
                raise ValueError("任务开始执行后核心范围已锁定；重大变更请新建修订草稿，原任务继续保留。")

        draft = normalize_task_draft_payload(existing, payload, draft_id)
        quality = task_draft_quality_check(conn, project_id, draft)
        if linked_action_task_id and not quality["passed"]:
            raise ValueError("已批准任务的修改未通过质量门槛：" + "；".join(quality["missing_fields"]))
        plan = replace_recommendation_task_draft(plan, draft)
        conn.execute(
            """
            UPDATE recommendations
            SET implementation_plan_json = ?, updated_at = ?
            WHERE project_id = ? AND recommendation_id = ?
            """,
            (json.dumps(plan, ensure_ascii=False), now_iso(), project_id, recommendation_id),
        )
        if linked_task:
            done_definition = "\n".join(task_draft_string_list(draft.get("acceptance_criteria"), 20))
            conn.execute(
                """
                UPDATE action_tasks
                SET title = ?, priority = ?, done_definition = ?, updated_at = ?
                WHERE project_id = ? AND action_task_id = ?
                """,
                (
                    draft["title"],
                    draft["priority"],
                    done_definition,
                    now_iso(),
                    project_id,
                    linked_action_task_id,
                ),
            )
    data = db_project_recommendations_payload(project_id)
    saved = next(
        (
            item
            for item in data.get("task_drafts", [])
            if item.get("draft_id") == draft_id and item.get("recommendation_id") == recommendation_id
        ),
        None,
    )
    return {"ok": True, "project": data.get("project"), "task_draft": saved, "recommendations": data, "source": "sqlite"}


def db_approve_recommendation_task_draft_payload(project_id, recommendation_id, draft_id, payload):
    project_id = unquote(str(project_id or "").strip())
    recommendation_id = unquote(str(recommendation_id or "").strip())
    draft_id = unquote(str(draft_id or "").strip())
    payload = payload if isinstance(payload, dict) else {}
    if payload.get("approved") is not True:
        raise ValueError("必须明确勾选人工批准后才能创建正式任务。")
    timestamp = now_iso()
    reused = False
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        row = conn.execute(
            "SELECT * FROM recommendations WHERE project_id = ? AND recommendation_id = ?",
            (project_id, recommendation_id),
        ).fetchone()
        if not row:
            raise ValueError(f"Unknown recommendation_id: {recommendation_id}")
        recommendation = db_row_to_dict(row)
        plan = recommendation.get("implementation_plan")
        plan = plan if isinstance(plan, dict) else {}
        draft = next(
            (item for item in recommendation_task_drafts(plan) if str(item.get("draft_id") or "") == draft_id),
            None,
        )
        if not draft:
            raise ValueError(f"Unknown task_draft_id: {draft_id}")
        quality = task_draft_quality_check(conn, project_id, draft)
        if not quality["passed"]:
            raise ValueError("任务草稿未通过质量门槛：" + "；".join(quality["missing_fields"]))

        action_task_id = str(draft.get("linked_action_task_id") or "") or deterministic_action_task_id(
            project_id,
            recommendation_id,
            draft_id,
        )
        existing_task = conn.execute(
            "SELECT * FROM action_tasks WHERE project_id = ? AND action_task_id = ?",
            (project_id, action_task_id),
        ).fetchone()
        if existing_task:
            reused = True
        else:
            done_definition = "\n".join(task_draft_string_list(draft.get("acceptance_criteria"), 20))
            conn.execute(
                """
                INSERT INTO action_tasks (
                  action_task_id, project_id, recommendation_id, title, priority,
                  owner, done_definition, status, due_date, completed_at,
                  created_at, updated_at, execution_note, evidence_url,
                  retest_status, started_at, blocked_reason
                ) VALUES (?, ?, ?, ?, ?, ?, ?, 'todo', ?, '', ?, ?, '', '', 'not_ready', '', '')
                """,
                (
                    action_task_id,
                    project_id,
                    recommendation_id,
                    str(draft.get("title") or "").strip(),
                    str(draft.get("priority") or "P2"),
                    str(draft.get("owner") or "").strip(),
                    done_definition,
                    str(draft.get("due_date") or "").strip(),
                    timestamp,
                    timestamp,
                ),
            )

        baseline_run_id = quality["baseline_run_id"]
        for question_id in normalize_question_id_list(draft.get("retest_question_ids")):
            match_id = stable_retest_match_id(project_id, action_task_id, question_id)
            conn.execute(
                """
                INSERT OR IGNORE INTO recommendation_retest_questions (
                  match_id, project_id, recommendation_id, action_task_id,
                  question_id, score, reason, source, has_before_sample,
                  before_run_id, in_baseline, selected, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, 100, ?, 'human_approved_draft', 1, ?, 1, 1, ?, ?)
                """,
                (
                    match_id,
                    project_id,
                    recommendation_id,
                    action_task_id,
                    question_id,
                    "人工批准的同题复测范围",
                    baseline_run_id,
                    timestamp,
                    timestamp,
                ),
            )

        approved_draft = {
            **draft,
            "status": "approved",
            "linked_action_task_id": action_task_id,
            "approved_at": str(draft.get("approved_at") or timestamp),
            "approved_by_human": True,
            "quality_snapshot": quality,
            "updated_at": timestamp,
        }
        plan = replace_recommendation_task_draft(plan, approved_draft)
        conn.execute(
            """
            UPDATE recommendations
            SET implementation_plan_json = ?, validation_status = 'human_confirmed',
                approval_status = 'approved', updated_at = ?
            WHERE project_id = ? AND recommendation_id = ?
            """,
            (json.dumps(plan, ensure_ascii=False), timestamp, project_id, recommendation_id),
        )
    data = db_project_recommendations_payload(project_id)
    task = next(
        (item for item in data.get("action_tasks", []) if item.get("action_task_id") == action_task_id),
        None,
    )
    return {
        "ok": True,
        "project": data.get("project"),
        "action_task": task,
        "reused": reused,
        "recommendations": data,
        "source": "sqlite",
    }


def db_confirm_retest_effect_payload(project_id, retest_run_id, payload):
    project_id = unquote(str(project_id or "").strip())
    retest_run_id = unquote(str(retest_run_id or "").strip())
    payload = payload if isinstance(payload, dict) else {}
    if payload.get("confirmed") is not True:
        raise ValueError("必须明确完成人工效果确认。")
    human_conclusion = str(payload.get("conclusion") or "").strip()
    if not human_conclusion:
        raise ValueError("请填写人工确认后的最终效果结论。")
    with db_connect() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        row = conn.execute(
            "SELECT * FROM retest_runs WHERE project_id = ? AND retest_run_id = ?",
            (project_id, retest_run_id),
        ).fetchone()
        if not row:
            raise ValueError(f"Unknown retest_run_id: {retest_run_id}")
        current = db_row_to_dict(row)
        if current.get("status") == "completed" and str(current.get("conclusion") or "").strip():
            reused = True
            comparison = build_retest_comparison(conn, project_id, current)
            comparison["status"] = "completed"
            comparison["effect_confirmed"] = True
            comparison["final_conclusion"] = current["conclusion"]
        else:
            reused = False
            comparison = upsert_retest_comparison(
                conn,
                project_id,
                retest_run_id,
                confirmed=True,
                human_conclusion=human_conclusion,
            )
            if not comparison or not comparison.get("persisted"):
                reason = (comparison or {}).get("blocked_reason") or "复测范围尚不可比较。"
                raise ValueError(reason)
    data = db_project_retests_payload(project_id)
    item = next((entry for entry in data.get("items", []) if entry.get("retest_run_id") == retest_run_id), None)
    return {"ok": True, "project": data.get("project"), "retest": item, "reused": reused, "source": "sqlite"}


def db_project_recommendations_payload(project_id):
    with db_connect() as conn:
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        recommendations = db_rows_to_list(
            conn.execute(
                """
                SELECT *
                FROM recommendations
                WHERE project_id = ?
                ORDER BY priority, created_at, recommendation_id
                """,
                (project_id,),
            ).fetchall()
        )
        evidence_rows = db_rows_to_list(
            conn.execute(
                """
                SELECT e.*
                FROM recommendation_evidence e
                JOIN recommendations r ON r.recommendation_id = e.recommendation_id
                WHERE r.project_id = ?
                ORDER BY e.recommendation_id, e.created_at, e.evidence_id
                """,
                (project_id,),
            ).fetchall()
        )
        action_task_rows = conn.execute(
            """
            SELECT *
            FROM action_tasks
            WHERE project_id = ?
            ORDER BY priority, created_at, action_task_id
            """,
            (project_id,),
        ).fetchall()
        action_tasks = [decorate_action_task(row) for row in action_task_rows]
        retest_match_rows = retest_question_match_rows(conn, project_id)
        quality_by_draft = {}
        for recommendation in recommendations:
            plan = recommendation.get("implementation_plan")
            for draft in recommendation_task_drafts(plan):
                quality_by_draft[(recommendation["recommendation_id"], draft.get("draft_id", ""))] = task_draft_quality_check(
                    conn,
                    project_id,
                    draft,
                )

    evidence_by_recommendation = {}
    for evidence in evidence_rows:
        evidence_by_recommendation.setdefault(evidence["recommendation_id"], []).append(evidence)
    for item in recommendations:
        item["evidence"] = evidence_by_recommendation.get(item["recommendation_id"], [])
    task_drafts = []
    draft_by_action_task = {}
    recommendation_by_id = {item["recommendation_id"]: item for item in recommendations}
    for item in recommendations:
        drafts = []
        for raw_draft in recommendation_task_drafts(item.get("implementation_plan")):
            draft = {
                **raw_draft,
                "recommendation_id": item["recommendation_id"],
                "recommendation_title": item.get("title", ""),
                "recommendation_approval_status": item.get("approval_status", "pending"),
                "quality_check": quality_by_draft.get(
                    (item["recommendation_id"], raw_draft.get("draft_id", "")),
                    {"passed": False, "missing_fields": []},
                ),
            }
            drafts.append(draft)
            task_drafts.append(draft)
            linked_action_task_id = str(draft.get("linked_action_task_id") or "")
            if linked_action_task_id:
                draft_by_action_task[linked_action_task_id] = draft
        item["task_drafts"] = drafts
    retest_by_task = {}
    retest_by_recommendation = {}
    for match in retest_match_rows:
        retest_by_task.setdefault(match.get("action_task_id", ""), []).append(match)
        retest_by_recommendation.setdefault(match.get("recommendation_id", ""), []).append(match)
    for task in action_tasks:
        task["retest_questions"] = retest_by_task.get(task.get("action_task_id", ""), [])
        recommendation = recommendation_by_id.get(task.get("recommendation_id", ""), {})
        draft = draft_by_action_task.get(task.get("action_task_id", ""))
        formal_approved = bool(
            draft
            and draft.get("status") == "approved"
            and recommendation.get("approval_status") == "approved"
        )
        delivery_acceptance = draft.get("delivery_acceptance") if isinstance(draft, dict) else {}
        delivery_accepted = bool(
            isinstance(delivery_acceptance, dict)
            and delivery_acceptance.get("confirmed")
        )
        task.update(
            {
                "formal_approved": formal_approved,
                "legacy_rule_task": not formal_approved,
                "approval_label": "已人工批准" if formal_approved else "历史规则任务·待复核",
                "task_draft_id": draft.get("draft_id", "") if draft else "",
                "priority_reason": draft.get("priority_reason", "") if draft else recommendation.get("reason", ""),
                "target_question_ids": draft.get("target_question_ids", []) if draft else [],
                "impacted_scenes": draft.get("impacted_scenes", []) if draft else [],
                "deliverable": draft.get("deliverable", "") if draft else task.get("done_definition", ""),
                "execution_steps": draft.get("execution_steps", []) if draft else [],
                "required_materials_and_facts": draft.get("required_materials_and_facts", []) if draft else [],
                "content_requirements": draft.get("content_requirements", []) if draft else [],
                "acceptance_criteria": draft.get("acceptance_criteria", []) if draft else task_draft_string_list(task.get("done_definition", "")),
                "delivery_accepted": delivery_accepted,
                "delivery_acceptance": delivery_acceptance if isinstance(delivery_acceptance, dict) else {},
                "delivery_status": "accepted" if task.get("status") == "done" and delivery_accepted else ("pending_acceptance" if task.get("status") == "done" else "not_delivered"),
                "final_effect_status": "verified" if task.get("retest_status") == "tested" else ("awaiting_confirmation" if task.get("retest_status") in {"sampled", "comparison_ready"} else ("awaiting_retest" if task.get("status") == "done" and delivery_accepted else "not_ready")),
            }
        )
        task["retest_ready"] = bool(task.get("status") == "done" and delivery_accepted)
    for item in recommendations:
        item["retest_questions"] = retest_by_recommendation.get(item.get("recommendation_id", ""), [])

    task_center_summary = {
        "pending_approval": sum(1 for draft in task_drafts if draft.get("status") != "approved")
        + sum(1 for task in action_tasks if task.get("legacy_rule_task")),
        "todo": sum(1 for task in action_tasks if task.get("status") == "todo"),
        "doing": sum(1 for task in action_tasks if task.get("status") == "doing"),
        "blocked": sum(1 for task in action_tasks if task.get("status") == "blocked"),
        "delivered": sum(1 for task in action_tasks if task.get("status") == "done" and task.get("delivery_accepted")),
        "awaiting_retest": sum(1 for task in action_tasks if task.get("final_effect_status") == "awaiting_retest"),
        "awaiting_confirmation": sum(1 for task in action_tasks if task.get("final_effect_status") == "awaiting_confirmation"),
        "verified": sum(1 for task in action_tasks if task.get("final_effect_status") == "verified"),
    }
    return {
        "project": project,
        "summary": {
            "recommendation_count": len(recommendations),
            "action_task_count": len(action_tasks),
            "workbench": action_workbench_summary(action_tasks),
            "task_center": task_center_summary,
        },
        "items": recommendations,
        "action_tasks": action_tasks,
        "task_drafts": task_drafts,
        "source": "sqlite",
    }


def recommendation_enrichment_prompt(project, recommendation, public_facts, sample_context):
    fact_lines = [
        f"- {item['fact_type']}/{item['fact_key']}：{truncate_text(item['fact_value'], 500)}"
        for item in public_facts[:60]
    ]
    sample_lines = []
    for sample in sample_context[:8]:
        citations = sample.get("citations") or []
        citation_text = "；".join(
            f"{item.get('title') or '来源'} {item.get('url') or ''}" for item in citations[:8] if isinstance(item, dict)
        )
        sample_lines.append(f"- {sample.get('question_id')} {sample.get('question')}\n  当前联网引用：{citation_text or '无'}")
    plan_text = json.dumps(recommendation.get("implementation_plan") or {}, ensure_ascii=False)
    return f"""请使用联网搜索验证并增强一条 GEO 内容资产建议，只输出合法 JSON。

项目：{project.get('name', '')}
客户：{project.get('customer_name', '')}
行业：{project.get('customer_industry', '')}
平台：{project.get('platform', '')}

当前建议：
- 标题：{recommendation.get('title', '')}
- 原因：{recommendation.get('reason', '')}
- 动作：{recommendation.get('action', '')}
- 内容 brief：{recommendation.get('content_brief', '')}
- 结构化行动方案：{plan_text}

允许发送和使用的客户公开确认事实：
{chr(10).join(fact_lines) or '- 暂无'}

目标问题与当前联网引用：
{chr(10).join(sample_lines) or '- 暂无'}

输出格式：
{{"enhanced_action":"更具体但不夸大的执行动作","verification_summary":"联网证据支持什么、不支持什么","content_outline":["内容模块"],"source_strategy":["应建设或引用的公开来源"],"acceptance_criteria":["可核验验收标准"],"retest_plan":"用目标问题复测的方式","limitations":["数据或证据边界"]}}

规则：
1. 只使用上述公开确认事实，不要把未公开内部资料发送、推断或写入建议。
2. 外部网页只能用于验证行业、平台和来源策略，不能反向创造客户案例、资质、排名或效果承诺。
3. 建议口径必须写成“基于当前豆包样本和联网证据”，不得宣称破解、还原或掌握豆包 App 私有排序算法。
4. 验收标准必须可检查；复测方案必须绑定目标问题和品牌出现/推荐/竞品压制等指标。
"""


def normalize_recommendation_enrichment(answer, citations):
    try:
        result = json.loads(extract_json_text(answer))
    except (json.JSONDecodeError, TypeError):
        result = {"enhanced_action": truncate_text(answer, 1600)}
    if not isinstance(result, dict):
        result = {"enhanced_action": truncate_text(answer, 1600)}

    def string_list(name, limit=12):
        value = result.get(name) or []
        if not isinstance(value, list):
            value = [value]
        return [str(item).strip() for item in value if str(item).strip()][:limit]

    return {
        "enhanced_action": str(result.get("enhanced_action") or "").strip(),
        "verification_summary": str(result.get("verification_summary") or "").strip(),
        "content_outline": string_list("content_outline"),
        "source_strategy": string_list("source_strategy"),
        "acceptance_criteria": string_list("acceptance_criteria"),
        "retest_plan": str(result.get("retest_plan") or "").strip(),
        "limitations": string_list("limitations"),
        "citations": [item for item in (citations or []) if isinstance(item, dict)][:20],
    }


def db_run_recommendation_enrichment(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    recommendation_ids = list(dict.fromkeys(
        str(item).strip() for item in (payload.get("recommendation_ids") or []) if str(item).strip()
    ))
    if not recommendation_ids:
        raise ValueError("请至少选择一条重点建议。")
    if len(recommendation_ids) > 3:
        raise ValueError("每次最多联网增强 3 条重点建议。")
    config = doubao_api_websearch_config(include_secret=True)
    if not config.get("configured"):
        raise ValueError("豆包火山方舟联网配置尚未完成。")
    placeholders = ",".join("?" for _ in recommendation_ids)
    with db_connect() as conn:
        ensure_recommendation_detail_fields(conn)
        project = db_project_detail(conn, project_id)
        if not project:
            return None
        recommendations = db_rows_to_list(conn.execute(
            f"SELECT * FROM recommendations WHERE project_id = ? AND recommendation_id IN ({placeholders}) ORDER BY priority, recommendation_id",
            (project_id, *recommendation_ids),
        ).fetchall())
        if len(recommendations) != len(recommendation_ids):
            raise ValueError("部分建议不存在或不属于当前项目。")
        public_facts = db_rows_to_list(conn.execute(
            """SELECT fact_type, fact_key, fact_value FROM customer_facts
            WHERE customer_id = ? AND fact_type <> 'question_profile'
              AND visibility = 'public' AND confidence NOT IN ('draft', 'pending', 'unverified')
            ORDER BY fact_type, fact_key""",
            (project["customer_id"],),
        ).fetchall())
        sample_rows = db_rows_to_list(conn.execute(
            """SELECT s.question_id, q.question, s.citations_json
            FROM samples s JOIN question_pool q ON q.question_id = s.question_id
            WHERE s.project_id = ? AND s.sample_type = 'real'""",
            (project_id,),
        ).fetchall())
    sample_by_question = {item["question_id"]: item for item in sample_rows}
    previews = []
    for recommendation in recommendations:
        target_questions = recommendation.get("target_questions") or []
        sample_context = [sample_by_question[qid] for qid in target_questions if qid in sample_by_question]
        prompt = recommendation_enrichment_prompt(project, recommendation, public_facts, sample_context)
        response = call_doubao_api_websearch(prompt, config)
        preview = normalize_recommendation_enrichment(response["answer"], response.get("citations"))
        preview.update({
            "recommendation_id": recommendation["recommendation_id"],
            "title": recommendation["title"],
            "model": config["model"],
            "created_at": now_iso(),
            "basis_label": "基于当前豆包样本和联网证据",
        })
        with db_connect() as conn:
            ensure_recommendation_detail_fields(conn)
            conn.execute(
                """UPDATE recommendations SET enrichment_preview_json = ?, enrichment_status = 'preview',
                enrichment_model = ?, updated_at = ? WHERE project_id = ? AND recommendation_id = ?""",
                (json.dumps(preview, ensure_ascii=False), config["model"], now_iso(), project_id, recommendation["recommendation_id"]),
            )
        previews.append(preview)
    return {"project": project, "items": previews, "count": len(previews), "basis_label": "基于当前豆包样本和联网证据"}


def db_confirm_recommendation_enrichment(project_id, payload):
    project_id = unquote(str(project_id or "").strip())
    recommendation_ids = list(dict.fromkeys(
        str(item).strip() for item in (payload.get("recommendation_ids") or []) if str(item).strip()
    ))
    if not recommendation_ids:
        raise ValueError("请至少选择一条已预览的增强建议。")
    timestamp = now_iso()
    confirmed = []
    with db_connect() as conn:
        ensure_recommendation_detail_fields(conn)
        if not db_project_detail(conn, project_id):
            return None
        for recommendation_id in recommendation_ids[:3]:
            row = conn.execute(
                "SELECT * FROM recommendations WHERE project_id = ? AND recommendation_id = ?",
                (project_id, recommendation_id),
            ).fetchone()
            if not row:
                continue
            recommendation = db_row_to_dict(row)
            preview = recommendation.get("enrichment_preview") or {}
            if not isinstance(preview, dict) or not preview:
                raise ValueError(f"建议 {recommendation_id} 还没有联网增强预览。")
            plan = recommendation.get("implementation_plan") or {}
            if not isinstance(plan, dict):
                plan = {}
            for key in ("content_outline", "source_strategy", "acceptance_criteria", "retest_plan", "limitations"):
                if preview.get(key):
                    plan[key] = preview[key]
            plan["verification_summary"] = preview.get("verification_summary", "")
            plan["basis_label"] = "基于当前豆包样本和联网证据"
            enhanced_action = str(preview.get("enhanced_action") or recommendation.get("action") or "").strip()
            conn.execute(
                """UPDATE recommendations SET action = ?, implementation_plan_json = ?, source_evidence_json = ?,
                enrichment_status = 'confirmed', enrichment_model = ?, enriched_at = ?,
                validation_status = 'web_verified_human_confirmed', updated_at = ?
                WHERE project_id = ? AND recommendation_id = ?""",
                (
                    enhanced_action,
                    json.dumps(plan, ensure_ascii=False),
                    json_dump(preview.get("citations") or []),
                    str(preview.get("model") or recommendation.get("enrichment_model") or ""),
                    timestamp, timestamp, project_id, recommendation_id,
                ),
            )
            confirmed.append(recommendation_id)
    result = db_project_recommendations_payload(project_id)
    result["confirmed_enrichment_ids"] = confirmed
    return result


def db_project_route_payload(project_id, resource, query):
    project_id = unquote(project_id)
    if not resource:
        return db_project_payload(project_id)
    if resource == "status":
        return db_project_status_payload(project_id)
    if resource == "monitoring-trends":
        return db_project_monitoring_trends_payload(project_id, query)
    if resource == "monitoring-sets":
        return db_project_monitoring_sets_payload(project_id)
    if resource == "source-evidence":
        return db_project_source_evidence_payload(project_id, query)
    if resource == "source-verification-runs":
        return db_project_source_verification_runs_payload(project_id, query)
    if resource == "questions":
        return db_project_questions_payload(project_id)
    if resource == "samples":
        return db_project_samples_payload(
            project_id,
            sample_type=(query.get("sample_type") or ["real"])[0],
            limit=(query.get("limit") or [100])[0],
        )
    if resource == "analysis-results":
        return db_project_analysis_payload(project_id)
    if resource == "analysis-brief":
        return db_project_analysis_brief_payload(
            project_id,
            limit=(query.get("limit") or [ANALYSIS_REVIEW_MAX_SAMPLES])[0],
        )
    if resource == "recommendations":
        return db_project_recommendations_payload(project_id)
    if resource == "retests":
        return db_project_retests_payload(project_id)
    raise ValueError(f"Unknown project resource: {resource}")


def count_samples():
    return count_sections(RAW_FILE)


def b64url_encode(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def b64url_decode(value: str) -> bytes:
    padding = "=" * (-len(value) % 4)
    return base64.urlsafe_b64decode((value + padding).encode("ascii"))


def password_hash(password: str, salt: str = "", iterations: int = AUTH_PBKDF2_ITERATIONS) -> str:
    if not salt:
        salt = secrets_lib.token_hex(16)
    digest = hashlib.pbkdf2_hmac(
        "sha256",
        password.encode("utf-8"),
        salt.encode("utf-8"),
        int(iterations),
    )
    return f"pbkdf2_sha256${int(iterations)}${salt}${b64url_encode(digest)}"


def verify_password(password: str, stored_hash: str) -> bool:
    try:
        algorithm, iterations, salt, expected = str(stored_hash or "").split("$", 3)
    except ValueError:
        return False
    if algorithm != "pbkdf2_sha256":
        return False
    actual = password_hash(password, salt=salt, iterations=int(iterations)).rsplit("$", 1)[-1]
    return hmac.compare_digest(actual, expected)


def write_json_file(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


def read_json_file(path: Path) -> dict:
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8-sig"))
    except json.JSONDecodeError:
        return {}
    return data if isinstance(data, dict) else {}


def ensure_auth_config() -> dict:
    config = read_json_file(AUTH_LOCAL_CONFIG_FILE)
    changed = False
    if not config:
        username = os.environ.get("GEO_AGENT_AUTH_USER", "admin").strip() or "admin"
        env_password = os.environ.get("GEO_AGENT_AUTH_PASSWORD", "")
        password = env_password or secrets_lib.token_urlsafe(18)
        config = {
            "enabled": True,
            "username": username,
            "password_hash": password_hash(password),
            "session_secret": secrets_lib.token_urlsafe(48),
            "session_hours": AUTH_SESSION_SECONDS // 3600,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "note": "Internal fixed-account login for GEO Agent. Do not commit this file.",
        }
        write_json_file(AUTH_LOCAL_CONFIG_FILE, config)
        if not env_password:
            AUTH_INITIAL_PASSWORD_FILE.write_text(
                "\n".join(
                    [
                        "GEO Agent internal login initial credential",
                        f"created_at: {config['created_at']}",
                        f"username: {username}",
                        f"password: {password}",
                        "",
                        "Keep this file outside deployment packages. Delete it after recording or resetting the password.",
                    ]
                ),
                encoding="utf-8",
            )
        return config
    if "enabled" not in config:
        config["enabled"] = True
        changed = True
    if not config.get("username"):
        config["username"] = "admin"
        changed = True
    if not config.get("session_secret"):
        config["session_secret"] = secrets_lib.token_urlsafe(48)
        changed = True
    if not config.get("session_hours"):
        config["session_hours"] = AUTH_SESSION_SECONDS // 3600
        changed = True
    if changed:
        write_json_file(AUTH_LOCAL_CONFIG_FILE, config)
    return config


def auth_session_seconds(config: dict) -> int:
    try:
        hours = int(config.get("session_hours") or (AUTH_SESSION_SECONDS // 3600))
    except (TypeError, ValueError):
        hours = AUTH_SESSION_SECONDS // 3600
    return max(1, min(hours, 72)) * 3600


def auth_enabled() -> bool:
    config = ensure_auth_config()
    env_override = os.environ.get("GEO_AGENT_AUTH_ENABLED", "").strip().lower()
    if env_override in {"0", "false", "no", "off"}:
        return False
    return bool(config.get("enabled", True))


def make_auth_token(username: str, config: dict) -> str:
    payload = {
        "u": username,
        "exp": int(time.time()) + auth_session_seconds(config),
    }
    encoded = b64url_encode(json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    signature = hmac.new(
        str(config.get("session_secret") or "").encode("utf-8"),
        encoded.encode("ascii"),
        hashlib.sha256,
    ).hexdigest()
    return f"{encoded}.{signature}"


def parse_auth_token(token: str, config: dict) -> str:
    try:
        encoded, signature = str(token or "").split(".", 1)
        expected = hmac.new(
            str(config.get("session_secret") or "").encode("utf-8"),
            encoded.encode("ascii"),
            hashlib.sha256,
        ).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return ""
        payload = json.loads(b64url_decode(encoded).decode("utf-8"))
        if int(payload.get("exp") or 0) < int(time.time()):
            return ""
        username = str(payload.get("u") or "").strip()
        if username != str(config.get("username") or "").strip():
            return ""
        return username
    except Exception:
        return ""


def auth_cookie_header(token: str, max_age: int) -> str:
    return (
        f"{AUTH_COOKIE_NAME}={token}; Path={auth_cookie_path()}; Max-Age={int(max_age)}; "
        "HttpOnly; SameSite=Lax"
    )


def clear_auth_cookie_header() -> str:
    return f"{AUTH_COOKIE_NAME}=; Path={auth_cookie_path()}; Max-Age=0; HttpOnly; SameSite=Lax"


def make_customer_auth_token(account: dict, config: dict) -> str:
    payload = {
        "kind": "customer",
        "aid": str(account.get("account_id") or ""),
        "cid": str(account.get("customer_id") or ""),
        "u": str(account.get("username") or ""),
        "rev": str(account.get("updated_at") or ""),
        "exp": int(time.time()) + auth_session_seconds(config),
    }
    encoded = b64url_encode(json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    signature = hmac.new(
        str(config.get("session_secret") or "").encode("utf-8"),
        encoded.encode("ascii"),
        hashlib.sha256,
    ).hexdigest()
    return f"{encoded}.{signature}"


def parse_customer_auth_token(token: str, config: dict) -> dict:
    try:
        encoded, signature = str(token or "").split(".", 1)
        expected = hmac.new(
            str(config.get("session_secret") or "").encode("utf-8"),
            encoded.encode("ascii"),
            hashlib.sha256,
        ).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return {}
        payload = json.loads(b64url_decode(encoded).decode("utf-8"))
        if payload.get("kind") != "customer" or int(payload.get("exp") or 0) < int(time.time()):
            return {}
        if not payload.get("aid") or not payload.get("cid") or not payload.get("rev"):
            return {}
        return payload
    except Exception:
        return {}


def customer_auth_cookie_header(token: str, max_age: int) -> str:
    return f"{CUSTOMER_AUTH_COOKIE_NAME}={token}; Path={auth_cookie_path()}; Max-Age={int(max_age)}; HttpOnly; SameSite=Lax"


def clear_customer_auth_cookie_header() -> str:
    return f"{CUSTOMER_AUTH_COOKIE_NAME}=; Path={auth_cookie_path()}; Max-Age=0; HttpOnly; SameSite=Lax"


def portal_login_throttled(username, client_ip):
    key = (str(username or "").casefold(), str(client_ip or ""))
    now = int(time.time())
    with PORTAL_LOGIN_ATTEMPTS_LOCK:
        attempts = [value for value in PORTAL_LOGIN_ATTEMPTS.get(key, []) if now - value < 15 * 60]
        PORTAL_LOGIN_ATTEMPTS[key] = attempts
        return len(attempts) >= 5


def record_portal_login_failure(username, client_ip):
    key = (str(username or "").casefold(), str(client_ip or ""))
    now = int(time.time())
    with PORTAL_LOGIN_ATTEMPTS_LOCK:
        attempts = [value for value in PORTAL_LOGIN_ATTEMPTS.get(key, []) if now - value < 15 * 60]
        attempts.append(now)
        PORTAL_LOGIN_ATTEMPTS[key] = attempts


def clear_portal_login_failures(username, client_ip):
    key = (str(username or "").casefold(), str(client_ip or ""))
    with PORTAL_LOGIN_ATTEMPTS_LOCK:
        PORTAL_LOGIN_ATTEMPTS.pop(key, None)


