                if not status_project_id:
                    status_project_id = DEMO_PROJECT_ID
                try:
                    demo_status = db_project_status_payload(status_project_id)
                except Exception:
                    demo_status = None
                empty_workspace_status = None
                if not demo_status:
                    try:
                        empty_workspace_status = db_empty_workspace_status_payload()
                    except Exception:
                        empty_workspace_status = None
                try:
                    latest_run = db_latest_run_summary(status_project_id)
                except Exception:
                    latest_run = None
                if empty_workspace_status:
                    latest_run = None
                elif not latest_run:
                    run_store = load_run_store()
