                if demo_status:
                    question_count = demo_status.get("question_count", len(questions))
                    sample_count = demo_status.get("sample_count", count_samples())
                    sample_row_count = demo_status.get("sample_row_count", sample_count)
                    sampled_question_count = demo_status.get("sampled_question_count", sample_count)
